window.HINOS = [{"numero": 1, "titulo": "KUWAILA", "blocos": [{"type": "verse", "num": null, "lines": ["Wahiana Zambi mupema", "Angelo nyi athu twimbenu", "Kuli Zambi nyi mwanenyi", "Zambi spiritu halisenu", "Amem..."]}]}, {"numero": 2, "titulo": "KULI CHIFUCHI", "blocos": [{"type": "verse", "num": 1, "lines": ["Kuli chifuchi cha zango chakwa ufulielo", "Ku miaka yeswe nyi yesu kuli uhwimino.", "Yeswe muyi-kasoloka yitemo ya miaka.", "Chifuchi chato nyi chiseke chakwa ulamwino."]}, {"type": "verse", "num": 2, "lines": ["Chifuchi chakwa usandu, muato nyi zango.", "luchisa kechi kanjila musoma wa muene", "Shili ku yichi kapwa mo chipwe luchisa kha", "Chifuchi chize chipema cha akwa ululi."]}, {"type": "verse", "num": 3, "lines": ["Nyi kachi munguli chiza upi wami weswe", "Tuka tuame nyi angelo chifuchi cha muilo", "Munguya hamwe nyi Mose ngumone chifuchi.", "Nguvulame ye ya hashi ngukeve chiseke"]}]}, {"numero": 3, "titulo": "ZAMBI THANGI YAMI", "blocos": [{"type": "verse", "num": 1, "lines": ["Zambi yiye thangi watangile yeswe;", "keke ukuete nyi zango yena Zambi yami", "keke ukuete nyi zango yena Zambi yami"]}, {"type": "verse", "num": 2, "lines": ["Se wangu tangile yi ungwaha mwono.", "Wangu lamwinyine wana, nguka wahilile.", "Wangu lamwinyine wana, nguka wahilile."]}, {"type": "verse", "num": 3, "lines": ["Ulemu we upwe, muli yami muane.", "Hanga ngupwe nyi spiritu hanga tumpe hamwe;", "Hanga ngupwe nyi spiritu hanga tumpe hamwe."]}]}, {"numero": 4, "titulo": "TATA HITWEZA KULI YENA", "blocos": [{"type": "verse", "num": 1, "lines": ["Atata hitueza yena zambi wika", "Yena chilamuina tuna mono", "Mu chifuchi mwapwi twehe kama pangu", "Tukolese kama yena tata"]}, {"type": "chorus", "lines": ["Atata hitueza yetwe wika", "Muene twive kama evwa keke"]}, {"type": "verse", "num": 2, "lines": ["Tuchize misongo uli uhwimino", "Ha shimbo ya lamba hija tuhwa", "Tuli e alelu twehe kama thachi", "Tuna kufuliela twehe thachi"]}, {"type": "verse", "num": 3, "lines": ["Twehe chawana che hanga ungu zange", "Tweya ungu kwase kuchina ku upi", "Hanga nguye muilo mwono mu-usula", "Nguna zange mwilo tuye nyi yena"]}]}, {"numero": 5, "titulo": "TUHALISENU ZAMBI", "blocos": [{"type": "verse", "num": 1, "lines": ["Tuhalisenu Zambi zango lienyi yecha.", "Mwanenyi yafa ha shili yetu"]}, {"type": "chorus", "lines": ["Aleluya uhenya We:tumu halisenu,", "Aleluya chawana che tunechi amén."]}, {"type": "verse", "num": 2, "lines": ["Tuhalisenu shipiritu ya pangu", "Yize yatu nyinguikishine mwe kristu."]}, {"type": "verse", "num": 3, "lines": ["Tuhalisenu hauthu wa Mwene,", "Watu fwilile hindu kwali nyi mwono."]}, {"type": "verse", "num": 4, "lines": ["Utuzalise nyi zango lia Yena,", "Mba utulongese ku kwononokena."]}]}, {"numero": 6, "titulo": "KUSEHEJELA", "blocos": [{"type": "verse", "num": 1, "lines": ["Tuhalisenu wika Zambi yetu,", "Se hana tutumo mwe chilamwina;", "Hana konekena milonga yetu,", "Hana twazulwila pito lia mwilo."]}, {"type": "chorus", "lines": ["Chiseke!Chiseke", "Tumu halisenu,", "Mwe Khule, mwe Khule,", "Kuli Chilamwina.", "Tuhalisenu mwe Zambi wa mwilu,", "Mumu hana twehe Mwanenyi Yesu."]}, {"type": "verse", "num": 2, "lines": ["Chawana cha mwenemwene mwe Yesu,", "Hana tumwangina manyinga jenyi", "Mutuka hinga nyi akwa usandu.", "Hi una tufwetela ye milonga."]}, {"type": "verse", "num": 3, "lines": ["Tuku tayize kuyilakenyo,", "Tukalinge upale wa mwe Zambi.", "Yiya mafuliela mwe Mwene,", "Nyi Kuka mumona mu wanangana."]}]}, {"numero": 7, "titulo": "SHIMA LIAUWAHISO WESWE", "blocos": [{"type": "verse", "num": 1, "lines": ["Yena shima lia wahiso", "Ngulongese we mwaso,", "Yawana Ye yishi kuhwa", "Hanga nguku halise", "Ngulongese mwaso waha", "Wa Khule mu lie pangu;", "Mukweze We nyi athu Je", "Akuhalise Yesu."]}, {"type": "verse", "num": 2, "lines": ["Ami nguna sakwilila,", "Yesu hangu lamwina,", "Chawana Che ngutwaminyine", "Uka ngutwale mwilu,", "Natokele wangu wanyine", "kusuku nyi mwe Zambi,", "Napihile yangu sanyisa,", "Nyi manyinga ja Yesu."]}, {"type": "verse", "num": 3, "lines": ["Mukuli wa chawana che,", "Tangwa ha tangwa nguli,", "Nguvwile kama keke Ye,", "Hanga mba nguku zange.", "Mwono wami ku wahonga,", "Ukwate nyi zango Lie.", "Mbunge yami kuyapinda,", "Yitwale kama Mwilu."]}]}, {"numero": 8, "titulo": "LEMESENU JINA LIA YESU", "blocos": [{"type": "verse", "num": 1, "lines": ["Lemesa jina lia Yesu,", "Angelo wayilenu!", "Mwana Zambi wa uhenya,", "Tumusenu vumbi!", "Mwana Zambi wa uhenya,", "Tumusenu vumbi."]}, {"type": "verse", "num": 2, "lines": ["Enwe mavungu apema", "A Tata wa Mwilu.", "Yesu mwene mukwa Mwono,", "Tumusenu vumbi!", "Yesu mwene mukwa Mwono,", "Tumusenu vumbi."]}, {"type": "verse", "num": 3, "lines": ["Makonekena nyi zango", "Ku mutu kakumba;", "Zambi yiye Mukwa thachi", "Tumusenu vumbi!", "Zambi yiye Mukwa thachi,", "Tumusenu vumbi."]}, {"type": "verse", "num": 4, "lines": ["Enwe mavungu malimi,", "Halisenu mwene;", "Wa patwile e malenge,", "Tumusenu vumbi!", "Wa patwile e malenge,", "Tumusenu vumbi."]}]}, {"numero": 9, "titulo": "TUHALISENU KRISTU LONGESHI", "blocos": [{"type": "verse", "num": 1, "lines": ["Tuhalisenu Yesu longeshi mupema!", "Hakulusu watu fwilile.", "Hana tukonekena ye shili yetu,", "Hakulusu manyinga amwanganyine,", "Halisenu nyi kumu chichimieka,", "Hako lietu kechi katwehuka"]}, {"type": "chorus", "lines": ["Tuhalisenu Yiye wika se Mwene", "Kuma tukonekena chawana"]}, {"type": "verse", "num": 2, "lines": ["Tuhalisenu Yesu longeshi wa Mwilu,", "Kaku kanyamisa akwa shili.", "Twambujole yiwape Yenyi yipema,", "Yize Chilamwina anatwehe,", "Yenu eswe tupinji twa mwene", "Yesu mumu aye kechi katwehuka"]}, {"type": "verse", "num": 3, "lines": ["Tuhalisenu Yesu longeshi wa Mwilu!", "Twimbe, twimbenu ha zango Lienyi.", "Akwa Yesu twimbilenu hamuwika", "Tuhalise ha unene nyi uhenya!", "Mwe kafunga Yesu mafunga nyi-Enyi,", "Kristu malamwina akwa-ufulielo."]}]}, {"numero": 10, "titulo": "UHENYA KULI CHILAMWINA", "blocos": [{"type": "verse", "num": 1, "lines": ["Kuheta ku kulusu Lienyi", "Yingu wayila Chilamwina.", "Mba yeva kulinyenga chami", "Uhenya wenyi!"]}, {"type": "chorus", "lines": ["Uhenya kuli mwene!", "Uhenya kuli Mwene!", "Yiye wika mangu lamwina", "Uhenya Wenyi."]}, {"type": "verse", "num": 2, "lines": ["Zango lienyi nguna komoka,", "Shili yangu konekena pe!", "Yangu jitula maswi jami,", "Uhenya Wenyi!"]}]}, {"numero": 11, "titulo": "MUTHUMBU WA CHIMENE", "blocos": [{"type": "verse", "num": 1, "lines": ["Zambi chemene mangwiva.", "Hakumu halisa;", "Mungu mwita Yiye Mwene;", "Kuma kangu kwasa."]}, {"type": "verse", "num": 2, "lines": ["Muze shipiritu ya yena,", "Muyingu songwela;", "Yingu hetese mwe Mwilu,", "Tuka twame hamwe."]}, {"type": "verse", "num": 3, "lines": ["Tuli ane utufunge", "Utukwate kama.", "Ndo ha kukaheta Mwilu", "Tuka lilamwine."]}]}, {"numero": 12, "titulo": "PANGU LIA MUMBUNGE", "blocos": [{"type": "verse", "num": 1, "lines": ["Pangu lili ku milundu,", "Nyi mukalunga nawa,", "Mwalwa wa tangwa unatu,", "Nyi mumisenge mwapwi;", "Pangu likwo linapeme,", "Nyi mbunge yami yeswe,", "kuze kwafwilile Yesu,", "Hanga angulamwine."]}, {"type": "chorus", "lines": ["Lie pangu lia Mwilu lipema.", "Lie pangu lia ukule", "Kuli Yesu chinyengo kha", "Pangu lili mu mbunge."]}, {"type": "verse", "num": 2, "lines": ["Hinguna hichika shili,", "Chayi zangile nawa.", "Sambukila nyi chiseke,", "Zalisa thulo yami;", "Nyi we umwene mwene We,", "Ena lamba wamwene.", "Mungukaya nyi chiseke,", "Nguka twame nyi yena."]}, {"type": "verse", "num": 3, "lines": ["Yesu hi unangu lande,", "Ngukwehe Mwono wami,", "Ngufungile mwono wami,", "Ukapwe uhenya we.", "Muzuwo lia uhenya We;", "Chifuchi cha uhenya,", "Mungu kaya nyi chiseke,", "Mba nguka kuhalise."]}]}, {"numero": 13, "titulo": "MULEMU! MULEMU! MULEMU!", "blocos": [{"type": "verse", "num": 1, "lines": ["Mulemu! Mulemu! Mulemu!", "Mwe yehovwa Zambi.", "Chimenemene mutu kakuhalisa.", "Mulemu! mulemu! Mulemu!", "utu we nyi keke!", "Yena Zambi thangi, ku wahiana."]}, {"type": "verse", "num": 2, "lines": ["Mulemu! mulemu! mulemu!", "a walamwinyine", "Hamwe nyi angelo tu kakuhalise.", "Shimbu hashi lilu te kanda lipwa-ko,", "Wapwile hwoli, nyi kumukapwa."]}, {"type": "verse", "num": 3, "lines": ["Mulemu! mulemu! mulemu!", "Tuliakwashili!", "Uhenya we ku waswama shimbu yeswe,", "Yena wikha mulemu; te neya walifwa,", "Ku thachi ululi, mana wahiana"]}, {"type": "verse", "num": 4, "lines": ["Mulemu! mulemu! mulemu!", "Yena Zambi wika!", "Yeswe watangile yakuku tohesa.", "Mulemu! mulemu! mulemu!", "vumbi lie nyi keke", "Zambi mwe Thangi, wa yuma yeswe."]}]}, {"numero": 14, "titulo": "KUNDJILA CHA TANGWA", "blocos": [{"type": "verse", "num": 1, "lines": ["Tangwa liaya mwalwa kha,", "Hashi heswe hi hala", "Uholela zungo kha", "Shinginyeka kulemba.", "Hakulemba."]}, {"type": "chorus", "lines": ["Zambi yena, yena, mwe mulemu.", "Hashi heswe ha Yena;", "A ku halise yena,", "A Yehova."]}, {"type": "verse", "num": 2, "lines": ["Yize yihuhumuke,", "Tu fuke nyi kwoko lie;", "Yena uli mo mwilu;", "Pwako kama mu mbunge.", "Mu mambunge."]}, {"type": "verse", "num": 3, "lines": ["Ku songo tukamone", "Upi mu-uka tuchina", "Twehe chawana, Zambi", "Hanga utu hindwise", "Tu hindwise"]}]}, {"numero": 15, "titulo": "PWAKO NYI YAMI", "blocos": [{"type": "verse", "num": 1, "lines": ["Twongu sweke kama Zambi yami,", "Ufuku nyi milima yahiana,", "Kashika nguneza hamwe Mwene;", "Hanga ngutwame hamwe nyi yena"]}, {"type": "verse", "num": 2, "lines": ["Haliapwila kufa muchingwiza;", "Chiseke cha hashi kumu chihwa!", "Muze yeswe kumu yalumuka", "Ngukatwame nyi Mwene ndo ku miaka."]}, {"type": "verse", "num": 3, "lines": ["Mwene usoloke kuli yami;", "Longeshi wami ngulembejeke,", "Ngupulule kama ku yizezo", "Tweya utwame hamwe nyi yami"]}, {"type": "verse", "num": 4, "lines": ["Chipwe mu milima nyi mu pangu;", "Nguli nyi Yesu woma nawa kha;", "Kuli yiye ufwe ku ushiko.", "Nguka tunge Nenyi ndo ku miaka."]}]}, {"numero": 16, "titulo": "MILIMO YA SEMANA HIYAHWA", "blocos": [{"type": "verse", "num": 1, "lines": ["Hitwa sulisa milimo", "Sambata hiya kundama", "Nguwahile mu mbunge", "Lie tangwa lia uhwimino."]}, {"type": "verse", "num": 2, "lines": ["Kulutwe jita yiliko", "Halisenu mwe yehovwa", "Tangwa yika lina twehe", "Lina twehe sambukila."]}, {"type": "verse", "num": 3, "lines": ["Tuka hane ye yawana", "Vumba lia uhindukilo", "Yesu makeza nyi uhenya", "Maka twaha uhwimino."]}, {"type": "verse", "num": 4, "lines": ["Kuhola cha sambukila", "Kapindji ka mukwa Mwono", "Makahana uhwimino", "Mwilu makawahilila."]}]}, {"numero": 17, "titulo": "CHALUMINGU HICHAHWA", "blocos": [{"type": "verse", "num": 1, "lines": ["Ye semana hi yahwa", "Zambi kana tufungu;", "Athu je kaneuluka", "Atambule uwahiso", "Lie tangwa kulia hiana", "Tuhwime tuwahile", "Lie tangwa kulia hiana", "Tuhwime tuwahile"]}, {"type": "verse", "num": 2, "lines": ["Tukonekene kama", "ku chawana cha Mwene", "Tusolwele keke Ye", "Tu pemese ku shili", "Tu chize yipikalo", "Kuli yena tuhwime.", "Tu chize yipikalo", "Kuli Yena tuhwime."]}, {"type": "verse", "num": 3, "lines": ["Mutuhalisa yena", "Pwako hamwe nyi yetu,", "Muze mutu manuna", "Tushimbwile makeza", "Sambukila ya Mwilu", "Tusolwele a Zambi!", "Sambukila ya Mwilu", "Tusolwele a Zambi!"]}, {"type": "verse", "num": 4, "lines": ["Maliji kakwete unene", "Hanga atulembejeke", "Mutukumba ye yipi", "Nyi kwecha upi weswe", "Hanga litwambulwile", "Sambukila mu mbunge", "Hangalitwambulwile", "Sambukila mu mbunge."]}]}, {"numero": 18, "titulo": "KANDA UVULAMA SAMBATA", "blocos": [{"type": "verse", "num": 1, "lines": ["Musono ye sambata", "Zambi awahishile;", "Se ha semana yeswe", "Lie tangwa lipema", "Tuhwime kumilimo", "Sambukila Mwilu", "Mwalwa unatemuka", "Uhenya wa Mwilu."]}, {"type": "chorus", "lines": ["Yize kama yize kama!", "Sambata yipema", "Khachi lize khachi lize", "Tangwa lia Zambi."]}, {"type": "verse", "num": 2, "lines": ["Fungenu ye sambata,", "Tuka ule mwe Yesu", "Twi-uluke yize anambe", "Mwono nyi lie pangu", "Khachi mutu mukaula", "Chilamwina chetu", "Makatunwisa meya", "A Mwono nyi zango."]}, {"type": "verse", "num": 3, "lines": ["Tangwa liacho lilemu,", "Kuchatu tamba eswe", "Kuhalisa mwe Zambi", "Ha uwahiso wenyi", "Chilamwina mupema", "Yiye mukwa pangu", "Twata kuyilakenyo,", "Ya Yesu mupema."]}]}, {"numero": 19, "titulo": "SAMBATA YILEMU", "blocos": [{"type": "verse", "num": 1, "lines": ["Ye sambata yilemu ya tamba kuhwima,", "kutuneza a Mwene tukwite utwehe.", "Ha zango lie liahana, mba tuku wahile", "Tuneza Chilamwina utukonekene."]}, {"type": "chorus", "lines": ["Ye sambata yilemu lie liji lia Zambi", "Ye sambata yilemu chiseke cha athu", "Sambata kuyi napu chilay kuli-Ane", "Sambata yami hano nguka hwime Mwilu."]}, {"type": "verse", "num": 2, "lines": ["Hakachi kasemana tuna vulumuna,", "Musono kutuneza,uthukonekene;", "Tuliumbe kuli yena, Twehe kama pangu.", "Twehe mwono wa miaka yena mukwa-uthu."]}, {"type": "verse", "num": 3, "lines": ["Sambata yakuhwima, Yesu Chilamwina.", "Kutuna wahilila ha zango lia yena;", "Tunakwichi a mwene twehe kama pangu,", "Tuna kutalatala, neha ulamwino."]}, {"type": "verse", "num": 4, "lines": ["Mukwa zango a Yesu Chilamwina chami.", "Musambata ya yena nguna kuhalisa.", "A Yesu nguna liumbu nyi chinyengo chinji,", "Nguneza kuli yena ngu lebejeke."]}]}, {"numero": 20, "titulo": "KULIKUNGULULA CHA USOKO", "blocos": [{"type": "verse", "num": 1, "lines": ["Kafunga ketu Yesu tweya utufunge", "Mwene tupwise kama mujimba umu wika.", "Kulimika nyi ipi ikapwe kusuku;", "kanda tuhandunuka kuli kata chetu."]}, {"type": "verse", "num": 2, "lines": ["Muze wa tukulile Chilamwina Yesu,", "Tuli kungululenu zango li muwika,", "Nyi kutala nyi keke shili ya mukwetu ,", "Eswe tumukwasenu nyi zango liahiana."]}, {"type": "verse", "num": 3, "lines": ["Yesu chihomboloji tulongese keke;", "Tupwe ngwe yena mwene nyi kwakonekena", "Tuna zange tukwase nyi thachi je Mwene;", "Tuku nguluke twite ha zango lie Mwene."]}, {"type": "verse", "num": 4, "lines": ["Akwa chikungulwila nyi kanafuliela;", "Kuma kawahilila jina lia ufulielo;", "Nyi chize wangwichile mungu kakwaha cho,", "E ana je mba Mwene muka handununa."]}]}, {"numero": 21, "titulo": "NGUJI LIA UCHINYINO", "blocos": [{"type": "verse", "num": 1, "lines": ["Ye mbunge yetu mwe Zambi;", "Yiye lukhepwe mukolo;", "Mukwiza jita yahiana,", "Yehovwa kuma tukwasa,", "Mukwa khole ya athu,", "Satana malionga,", "Kumaka twenyeka;", "Ufwathulo-a-Kwete,", "Wahiana eswe ku yipi."]}, {"type": "verse", "num": 2, "lines": ["Nyi mutuli chichimieka,", "Mba etu kumututoka", "kuli umwe matukwasa", "Yoze hanamutongola", "Jina Lienyi Yesu,", "Mutalenu meso", "Jita masongwela,", "Tu chine Satana", "ku jita hanga tukumbe."]}, {"type": "verse", "num": 3, "lines": ["Chipwe chifuchi chahiana,", "Nyi mahamba ja Satana,", "kutuchi kwevwila woma", "Yehovwa wika Munene,", "Mwe mukwa kuhisa", "Tupinji twa Mwene", "kumaka muhisa", "kumaka limbuka", "Nyi lie liji lumuwika."]}, {"type": "verse", "num": 4, "lines": ["Lie liji lia miaka yeswe,", "Twa lifuliela cho chene;", "kutuchi kwivwa woma kha,", "kristu kumatu pulwila,", "Nyi mututokesa,", "Ana jetu,nyi pwo,", "Nyi hanji mutufwa,", "Tuli nyi Mwe Yesu,", "Matwaha we wanangana."]}]}, {"numero": 22, "titulo": "KULEMBA CHA KUWAHILILA", "blocos": [{"type": "verse", "num": 1, "lines": ["Ola yino yakulemba,", "Yakuneha sambukila", "Yitu uke kumisongo,", "Tukundame kuli mwene.", "Ha shimbu lia yipikalo,", "ku misongo nyi yeseko,", "Hanga ngukapwe nyi thachi", "Ja kulinunga nyi Mwene."]}, {"type": "verse", "num": 2, "lines": ["Ola yino yakulemba,", "Nyi ufulielo mu mbunge,", "Mu itwala vumbi mwilu,", "Lika hete kuli Mwene;", "Ola ya lamba muyihwa", "Nyi luyinda nyi yeseko,", "Mungu kemba uhaliso", "Kuli mwene wami Yesu."]}, {"type": "verse", "num": 3, "lines": ["Ola yino yakulemba,", "Muyitununga nyi Mwene,", "Muyi neha ufulielo,", "Zango muli zala hashi.", "Chipwe mwono mu usula", "Ufulielo nyi kulemba;", "Mwilu,mutu kazezuka", "Mba muchikapwa chiseke."]}]}, {"numero": 23, "titulo": "PHEKAMA MBIMBILIYA", "blocos": [{"type": "verse", "num": 1, "lines": ["Phekama Mbimbiliya,nayizanga,", "Mumu nayizanga kuyi kaula;", "Maliji jamo nawahilila no", "Waze ambujolele mwe Kristu."]}, {"type": "chorus", "lines": ["Phekama Mbimbiliya,Mukanda upema,", "Yinambujola pangu lipema.", "Yinalongesa zango nyi kuwaha", "Muyi tutwala kuli, Yesu."]}, {"type": "verse", "num": 2, "lines": ["Ngwehe Mbimbiliya,nguna yihono,", "Muyi kangu pulula ku shili;", "Maliji jamo kakwete unene", "Mangu tomesa mwono wami pe."]}, {"type": "verse", "num": 3, "lines": ["Ngwehe Mbimbiliya, yingu songwele,", "Yingu temwine mu mwono uno;", "Misayo yalio kuyatwa ndo mwilu,", "Muyi tusongela ku kulusu."]}]}, {"numero": 24, "titulo": "MALIJI A MWONO", "blocos": [{"type": "verse", "num": 1, "lines": ["Nguna hilukila nawa maliji a mwono;", "Eno akungu lembejeka maliji a mwono", "Waze ejile mwilo hanga angu songwele ."]}, {"type": "chorus", "lines": ["E apema a kuli Zambi maliji a Mwono", "Uwahiso wa kuli Zambi maliji a Mwono"]}, {"type": "verse", "num": 2, "lines": ["Yesu mahana kuli eswe maliji a mwono;", "Mukwa shili mupanjike ku maliji a Mwono.", "Aye mukwa ufulielo ku mamu lamwina."]}, {"type": "verse", "num": 3, "lines": ["Nwafuliela mwimbilenu maliji a mwono!", "Chipwe angelo kanembi je sango ja mwono,", "kristu soma ya Mwilu Mwe kasongo mupema."]}]}, {"numero": 25, "titulo": "UNGWAMBULWILE CHIMA CHIKULU", "blocos": [{"type": "verse", "num": 1, "lines": ["Ungwambulwile sango", "Lia mwe Chilamwina;", "Lia kristu nyi-uhenya Wenyi,", "Lia kristu nyi zango", "Uli nyingune mushi.", "Hanga mba ngunjile", "Te hanga ngunyingike;", "Zambi katuzanga."]}, {"type": "chorus", "lines": ["Ungwambulwile sango,", "Ngwambulwilenu sango,", "Nngwambulwile chishima", "Cha zango lia kristu."]}, {"type": "verse", "num": 2, "lines": ["Ungwambulwile kama", "Lie zango lia Yesu;", "Una nyingika-achize", "Nguli mukwa shili!", "Ngulembejeke kama", "Ha shimbu ya lamba", "Ngufumbe sango lino."]}, {"type": "verse", "num": 3, "lines": ["Muze pangu lia hashi", "Mulili takana,", "Ungwambulwile kama", "Chawana cha Yesu!", "Uhenya we wa miaka", "Mu-utemwina hashi", "Ungwambulwile sango;", "Yesu malamwina."]}]}, {"numero": 26, "titulo": "YESU MAKESA NYI KUNGUSAKA", "blocos": [{"type": "verse", "num": 1, "lines": ["Kristu wejile ku mbeteleme,", "Wamwenelamba kumulelesa", "Keke evwile hali akwa shili,", "Nyi kufupa yami!", "Nyi kufupa yami! (Yami) 2.", "Ha zango lia yami ejilile,", "Nyi kufupa yami"]}, {"type": "verse", "num": 2, "lines": ["Kristu se wafwile ha kulusu,", "Yapha chiseke nyi pangu lieny", "Mangu songwela jila ya muilu", "Ngulingile yeswe!", "Ngulingile yeswe!", "Mangu songwela jila ya Mwilu.", "Ngulingile yeswe"]}, {"type": "verse", "num": 3, "lines": ["Kristu Chilamwina ngwenyi tweya;", "Aye ngwenyi naku lamwinyine,", "Tweya Yesu hana ku lamwina,", "Kanda ulaluka.", "Kanda ulaluka (luka) 2,", "TweyaYesu hana ku lamwina,", "kanda ulaluka."]}, {"type": "verse", "num": 4, "lines": ["Kristu ngwenyi mungu keza nawa,", "Meza nyi uhenya nyi angelo", "kumungu Kamona huma Lienyi,", "Nyi kwijila yami!", "Nyi kwijila yami! (yami)", "Nyi kwijila yami! (yami)", "Mutu kamona lie huma Lienyi,", "Nyi kwijila yami."]}]}, {"numero": 27, "titulo": "NGUKAMBULULE SANGO LIPEMA", "blocos": [{"type": "verse", "num": 1, "lines": ["Ngu kembe sango lipema", "Lia Yesu Chilamwina,", "Mwilu ya hichika uhenya", "Mweza yangu lamwina."]}, {"type": "chorus", "lines": ["Ngu kembe sangolipema", "Lia Yesu Chilamwina.", "Hamwe nyi akwa usandu", "Haswa mu-uhenya pe."]}, {"type": "verse", "num": 2, "lines": ["Natokele mwe mushili", "Yesu mba yangwanda mo", "Mwangu wana yangu kwata", "Tukapwe Nenyi hamwe."]}, {"type": "verse", "num": 3, "lines": ["Yesu wangu nangishine,", "Muze nambile kufwa,", "Yangu-uka ye yilonda", "Yiye wangu pulwile."]}, {"type": "verse", "num": 4, "lines": ["Hama tangwa aluyinda,", "Cho chinyengo nakwivwa;", "Yiye nakujikijila,", "Hanga angu lamwine."]}]}, {"numero": 28, "titulo": "SANGO LIA ZAMBI", "blocos": [{"type": "verse", "num": 1, "lines": ["Sango lia kuli Zambi;", "Yesu malamwina!", "Eswe lia mbujolenu:", "Yesu Malamwina!", "kolojokenu kweswe.", "Mukwa shili panjika", "Zambi yecha Muanenyi", "Apwe mwe Chilamwina."]}, {"type": "verse", "num": 2, "lines": ["Talenu che chawana:", "Yesu Malamwina!", "Manyinga wa mwangine,", "Yesu maku lamwina!", "Mu mathungu yimbenu,", "Talenu che chawana", "Angelo nwambujole;", "Yesu Malamwina."]}, {"type": "verse", "num": 3, "lines": ["Akwa usandu yimbenu:", "Yesu Malamwina!", "Mavungu-awahilile", "Yesu Malamwina!", "Mahana mwono wana", "kuli chivulumunyi,", "Uhenya, uhenya wa Zambi", "Yesu Maku lamwina."]}]}, {"numero": 29, "titulo": "KUJIKIZA CHIPEMA", "blocos": [{"type": "verse", "num": 1, "lines": ["Kuli Yesu najikijila!", "Hapwila nguna wahilila!", "Muli Yesu, nguli swana ya Zambi,", "Mu-uhenya wenyi mangu twala."]}, {"type": "chorus", "lines": ["Yimbila Zambi a mwono wami!", "Muhalise nyi thachi yeswe!", "Yimbila Zambi a mbunge yami!", "Muhalise mathangwa eswe."]}, {"type": "verse", "num": 2, "lines": ["Ngunalise ku zango Lienyi!", "Nguli mukwa ku suswamiana!", "Angelo yeza, yaneha", "Sangolia chawana cha Zambi."]}, {"type": "verse", "num": 3, "lines": ["Ngunyongonone nyi zango Lie.", "Ngu wahilile Mwene wami:", "Mu pangu lienyi ngunedela,", "Ha uthu nyi zango lia Yesu"]}]}, {"numero": 30, "titulo": "KRISTU NAWA", "blocos": [{"type": "verse", "num": 1, "lines": ["Yuma ya Yesu nazanga", "Nazanga nyi zango Lienyi", "Nguzale nyi keke Yenyi", "Nyi kusula chenyi nawa."]}, {"type": "chorus", "lines": ["Ngu zange nawa kristu!", "Ngu zange nawa Kristu!", "Nyi zango lienyi liahiana", "Nawa yena Chilamwina."]}, {"type": "verse", "num": 2, "lines": ["Yuma ya kristu nguyivwe", "Ngunonoke kuli Kristu,", "Shipiritu ya umwenemwene", "Yitu songwele nyi keke."]}, {"type": "verse", "num": 3, "lines": ["Nguna zange ngupwe hehi,", "Nguli nunge nyi zango Lie,", "Hanga liji Lie ngulivwe,", "Hanga ngufunge shimbi Je."]}, {"type": "verse", "num": 4, "lines": ["Mungu kamona mwe Kristu", "Mahinga wanangana Wenyi", "Upwe kama mu mbunge yami", "Musono ndo nyi kulutwe."]}]}, {"numero": 31, "titulo": "A YESU NAKUZANGA.", "blocos": [{"type": "verse", "num": 1, "lines": ["Yesu nakuzanga uli nyi wami;", "Ha vumbi lia Yena ngukuhalise.", "Uli longeshi,nyi mwe Mwanangana", "wami, kuli yena kristu mungu kononoka."]}, {"type": "verse", "num": 2, "lines": ["Nakuzanga, mumu wangu fwilile,", "Nguna komoka, ha zango lia Yena,", "Kuli yena najikijila ndo ku miaka;", "Kuli yena Kristu mungu kononoka!"]}, {"type": "verse", "num": 3, "lines": ["Nguchili nyi Mwono mungu kuzanga;", "Ngukwimbile miaso ya uhaliso,", "Nguna zange tukapwe hamwe ndo", "kumiaka;", "kuli yena Kristu mungu kononoka"]}]}, {"numero": 32, "titulo": "AU NAFULIELA NGUNA MUNYINGIKA", "blocos": [{"type": "verse", "num": 1, "lines": ["Cha nyigikine zango-ali", "Zambi asolwele,", "Mumu ya tuma Mwanenyi", "yafwa hali yami."]}, {"type": "chorus", "lines": ["Nanyingika namufuliela,", "Yiye mahasa ku ngupulula", "Mafunga upite wami", "Ndo muze makesa."]}, {"type": "verse", "num": 2, "lines": ["Na yambashana Spiritu", "Ya kungusongwela,", "Mu yitulwesa ngo kristu", "Yiye mwe chikwashi."]}, {"type": "verse", "num": 3, "lines": ["Yipi nyi ipema yeswe", "Yili muli yami;", "Alioze ha zango lienyi", "Maka ngu tambula."]}, {"type": "verse", "num": 4, "lines": ["Chanyingikine Tangwa makeza", "Yiye wachi nyingika", "Alioze mwene Yesu makeza;", "Makeza nyi uhenya."]}]}, {"numero": 33, "titulo": "MUNGU FULIELA KRISTU", "blocos": [{"type": "verse", "num": 1, "lines": ["Chinapeme kufuliela", "Jina lia Mwene Yesu", "Kutayiza yuze mamba", "Nyi yilakenyo yenyi."]}, {"type": "chorus", "lines": ["Kristu, Kristu,nafuliela,", "Jina lie nyi unene We;", "Kristu!Mwene!Mukwa zango,", "Ngu wezele ufulielo."]}, {"type": "verse", "num": 2, "lines": ["Uwayiso kufuliela,", "Manyinga amwanganyine", "Mumu shili yami yeswe;", "Zambi yayijimuna."]}, {"type": "verse", "num": 3, "lines": ["Kuwaha,tayiza Kristu", "Ku makukonekena!", "Mutambula kuli Kristu", "Mwono nyi ulamwino."]}, {"type": "verse", "num": 4, "lines": ["Kuwaha kupwa nyi Kristu", "Ngukapwe hamwe Nenyi", "Nguli hane kuli Yiye,", "Nyi ku mwononokena"]}]}, {"numero": 34, "titulo": "YESU KASENDO MUPEMA", "blocos": [{"type": "verse", "num": 1, "lines": ["Kasendo mupema Kristu", "Kana hiana mwakwetu;", "Kana twambe tuyitwale", "Kumeso ja Mwe Zambi.", "Mu mbunge ku tuna hono", "Sanbukila nyi keke?", "Mumu kutwa yitwalile", "Ku meso ja mwe Zambi."]}, {"type": "verse", "num": 2, "lines": ["Nyi chiteli muchilema", "Cha luyinda nyi woma?", "Yesu che chiswamo chetu,", "Mba kumaka tusweka.", "Kachi akwenu maku yunga?", "Ambulwila Mwene we,", "Zango lienyi kuliahiana", "Kumu kevwa chiseke."]}, {"type": "verse", "num": 3, "lines": ["Khachi muze mutuhonga;", "kristu kumatu kwasa,", "Mumu yiye thachi jetu,", "Ha shimbu yakulemba,", "Nyi-akwa hashi matuyunga;", "Tulembe kuli Yesu;", "Tutwame mukondo yenyi", "Kumatu lembenjeka."]}]}, {"numero": 35, "titulo": "MWE SEPA MUNENE", "blocos": [{"type": "verse", "num": 1, "lines": ["Kasendo mupema Yesu", "Musandu mwe mupema!", "Ulemu wa, Yena wahiana,", "Nyi zango lie liahiana,", "Kuli phanga keshi tachi,", "Yamu tala nyi keke;", "Nyi kwoko Lienyi lia uthu", "Kuli nangu songuela."]}, {"type": "verse", "num": 2, "lines": ["Mwe sepa munene Yesu!", "Kusuku yangu saka;", "Wejile nyi kumona lamba,", "Hanga angu lamwine", "Uhenya wa che Chifuchi", "Mungu pwisa nyi hamu", "Nguna twaminyina Yena,", "Hanga ungu Tambule."]}, {"type": "verse", "num": 3, "lines": ["Mwe sepa munene Yesu,", "Kasongo wakanyama;", "Yiye uchinyino wa miaka,", "Kasongo chitakame!", "Nguli wa Yesu, Mwene wami", "Uhenya wa miaka yeswe!", "Ngukapwe hamwe nyi Zambi", "Uthu wa zango Lienyi."]}]}, {"numero": 36, "titulo": "KASENDO MUPEMA", "blocos": [{"type": "verse", "num": 1, "lines": ["Kasendo mupema mwe Kristu,", "Muze yizezo muyinguka", "Molola kwoko Lienyi,", "Mahombonwesa mbunge;", "Mwe kasendo mupema kristu."]}, {"type": "chorus", "lines": ["Yesu kasendo mupema;", "B.T. Yena kasendo.", "Yesu kasendo mupema;", "B.T. Yena kasendo.", "Makanyamisa phundu", "Ku makangwaha thachi!", "Mwe kasendo mupema kristu."]}, {"type": "verse", "num": 2, "lines": ["Kasendo mupema mwe kristu,", "Yiye maka ngulembejeka", "Ngushimbwile kwoko Lie;", "Chichi woma Mwe kasendo mupema", "Kristu."]}, {"type": "verse", "num": 3, "lines": ["Nyi te manguya mumilima,", "Munguya ku lwiji Yordau,", "Woma kha Mwene Yesu", "Ngutwale ku Chifuchi,", "Mwe kasendo mupema Kristu."]}, {"type": "verse", "num": 4, "lines": ["Ku zuwo lienyi hamwe nenyi,", "Hamwe nyi ana asandu", "Mwaso waku halisa", "Mutukembila Mwene,", "Mwe kasendo mupema Kristu."]}]}, {"numero": 37, "titulo": "KULI UMWE SEPA", "blocos": [{"type": "verse", "num": 1, "lines": ["Kuli sepa wanyingika", "lamba lia we mwono uno;", "Haye shimbu yina tambe", "Mayalumuna chiseke;", "Kuli sepa wanyingika", "Yinyengo nyi misongo ye,", "Kana zange kukulweza", "Zango lienyi kuliahiana."]}, {"type": "verse", "num": 2, "lines": ["Kuli sepa wanyingika", "Satana kanatetwoka;", "Yikola yinji anevu,", "Nyi keke machiza shili;", "Unalele nyi chinyengo,", "Unendela kusuku,", "Kuli sepa Waku funga,", "Kwiza cha mwana chimwangi."]}, {"type": "verse", "num": 3, "lines": ["Kuli sepa Waku zanga,", "Majikiza nyi malela", "Keshi kuhichika Mwana", "Ku yala ya Satana", "Kutala Chenyi kusuku,", "Kuchi kapwa ndumbwami,", "Hulako Lie jina Lienyi?", "Yesu, twehe ulamwino."]}]}, {"numero": 38, "titulo": "KASENDO WAHIANA", "blocos": [{"type": "verse", "num": 1, "lines": ["Wakuhi kasendo ngwe mwe Kristu,", "Nyi umwe! Nyi umwe!", "Kumaka lamwina mwono wami!", "Nyi umwe! Nyi umwe!"]}, {"type": "chorus", "lines": ["Kristu kakutu mwena yeswe;", "Masongwela ndo kuheta;", "Wakuhi weka ngwe Mwene Yesu,", "Nyi umwe! Nyi umwe!"]}, {"type": "verse", "num": 2, "lines": ["Hanga angu hichikile wika,", "Nyi umwe! Nyi umwe!", "Nyi Yesu chichi kunenganyana;", "Nyi umwe! Nyi umwe!"]}, {"type": "verse", "num": 3, "lines": ["Wakuhi kasendo mwe mulemu;", "Nyi umwe! Nyi umwe!", "Wakuli lelesa mukwa uthu;", "Nyi umwe! Nyi umwe!"]}, {"type": "verse", "num": 4, "lines": ["Wakuhi kasendo mwe mulemu;", "Nyi umwe! Nyi umwe!", "Wakuli lelesa mukwa uthu;", "Nyi umwe! Nyi umwe!"]}]}, {"numero": 39, "titulo": "A ZANGO LIA MWONO WAMI", "blocos": [{"type": "verse", "num": 1, "lines": ["Ena uli zango liami,", "Ngutwame ha thulo ye!", "Muze linyika muliza;", "Muze kalunga mafuza,", "A Chilamwina ngufupe,", "Ndo hakuhwa chasanga,", "Ngu songwele nyi lie zango.", "Ku Chifuchi cha miaka."]}, {"type": "verse", "num": 2, "lines": ["Nguka swame kuli yena;", "Ngupombe hamolu je,", "Kanda uka nguhichika,", "Ungu lembejeke kama,", "Ngufuliele, kuli Yena.", "Yana chikwashi Chami.", "Ngwehe kama lie zango Lie,", "Ngufunge nyi kwoko Lie."]}, {"type": "verse", "num": 3, "lines": ["Ha lamba wa kungu sweka,", "Chipwe liahiana naye,", "Kuwa kungu huzulula;", "Ngwehe we mwono wa miaka,", "Mukwa zango Yena Yesu!", "Nguli mwe mukwa upi", "Ha ye shili yami yinji,", "Ku mukangu lamwina"]}, {"type": "verse", "num": 4, "lines": ["Keke Ye ya miaka yeswe", "Yingukose ku yipi.", "Keke Ye ya miaka yeswe.", "Yingo kose mba ngupeme.", "Fuji lia miaka a Yesu,", "Yena ukwete yeswe", "Kumu nguka wahilila,", "Ngukapwe nawo! Amén."]}]}, {"numero": 40, "titulo": "KULI YESU NGUNAWAHILILA", "blocos": [{"type": "verse", "num": 1, "lines": ["Ngunevu chiseke!", "Nawana Yesu!", "Chiseke nguli nacho;", "Cha mwe Yesu!", "Chiseke cha hashi;", "Hapwila muchihwa;", "Nguli nyi sambukila,", "Ya mwe Yesu"]}, {"type": "verse", "num": 2, "lines": ["Ami mujinguhwa,", "Yesu aye kha!", "Chipwe mungu swala,", "Yesu phichi", "Mungu wana yeswe,", "Muyi ka ngukwasa,", "Nyi Yesu chichi", "Kahona nyi chimwe."]}, {"type": "verse", "num": 3, "lines": ["Chifuchi muchihwa,", "Masala Yesu!", "Maka ngusopesa", "Yesu kwali!", "Tukevwe chiseke,", "Hakwiza cha Yesu", "Mutukevwa ngwenyi;", "“Yami Yesu”"]}]}, {"numero": 41, "titulo": "KULI YESU NGUNA WAHILILA", "blocos": [{"type": "verse", "num": 1, "lines": ["Chipwe sambukila mungwivwa yinji.", "Chipwe mungwivwa yikola,", "Cheswacho muchipwa nguli nyi Yena,", "Cho kuwaha nguli nyi Yesu."]}, {"type": "chorus", "lines": ["Kuwaha…Nyi Yesu", "B.T. Mungwivwa…Chahiana!", "Kuwaha nyi Yesu, Muene wami"]}, {"type": "verse", "num": 2, "lines": ["Chipwe Satana, meza nyi kungwonga,", "Mangu nehena yizezo;", "Nyi nguna jikiza munguyikumba,", "Cho chiseke, nguli nyi Yesu!"]}, {"type": "verse", "num": 3, "lines": ["Chiyengo chami mungu munehena,", "Yeswe hanangu fwetela:", "Ha mutondo Yesu angu fwilile!", "Cho kuwaha nguli nyi Yesu!"]}, {"type": "verse", "num": 4, "lines": ["Zango nguli nalio lia kwiza Chenyi;", "Hapwila kuma ngwijila;", "Tukaye Nenyi mwilu, ndo ku miaka", "Nyi khule um pangu lia Mwene!"]}]}, {"numero": 42, "titulo": "KRISTU, LONGESHI YAMI", "blocos": [{"type": "verse", "num": 1, "lines": ["Kristu, Longeshi,", "Mwe kesendo wahiana;", "Mutuhwimisa,", "Um wanangana.", "Muze mangweseka,", "Mungu kajikijila,", "Yena Kristu zango,", "Hanga ungu kwase"]}, {"type": "chorus", "lines": ["Hehe, ha kamwihi,", "Kuli Yena nguneza;", "Hehi, haka mwihi,", "Tweya a Mwene"]}, {"type": "verse", "num": 2, "lines": ["Yena chikwashi,", "Muze mungwendangana,", "Ngwize a Kristu,", "Ungu pulule!", "Nyi Yena nguhase,", "Kukumba ye yeseko,", "Kuli yena kuli,", "Thachi nyi keke"]}, {"type": "verse", "num": 3, "lines": ["Kristu, Longeshi,", "Ku nguna wahilila,", "Mu wanangana We", "Muli uhenya;", "Ha thulo ya Mwene,", "Ngu chachile we mutwe,", "Ngu kahwimineho,", "Kwe ku milimo."]}]}, {"numero": 43, "titulo": "WO USONA!", "blocos": [{"type": "verse", "num": 1, "lines": ["Chilamwina, Mwata, Sepa liami,", "Yiye Longeshi wa mwilu,", "Kuli Yena kuli uwahiso", "Yesu, uli mwe nyi wami!"]}, {"type": "chorus", "lines": ["Nguli nyi usona wa yena Yesu;", "Neha kawashi, tangwa lia yena!", "Tupwe nyi yena, shimbu yeswe,", "Wo usona, cho chiseke."]}, {"type": "verse", "num": 2, "lines": ["Nyi chimwe hashi muchi nguchiza,", "Kuli Longeshi wa mwilu!", "Nazanga kwimba ye shimbu yeswe,", "Yesu, uli mwe nyi wami."]}, {"type": "verse", "num": 3, "lines": ["Zango liahiana kalunga lwiji,", "Kristu Longeshi wa mwilu!", "Nguvwile kama Vumbi liahiana;", "Yesu, mwe nyi wami pundu"]}, {"type": "verse", "num": 4, "lines": ["Chipwe masepa mangu kunjika,", "Longeshi wa Mwilu kechi..,", "Kungu hana kuli akwa khole,", "Yesu,Yiye mwe nyi wami!"]}]}, {"numero": 44, "titulo": "NGULAMWINE NYI YAMI", "blocos": [{"type": "verse", "num": 1, "lines": ["Yesu, kanda unguhiana.", "Ungwivwe kama!", "Walamwinyine akwetu,", "Lamwina yami."]}, {"type": "chorus", "lines": ["Kristu, Kristu,", "Ungwivwe kama!", "Walamwinyine akwetu,", "Kanda ungu hiana."]}, {"type": "verse", "num": 2, "lines": ["nguna liumbu kuli Yena,", "Chinyengo, chinji,", "Ungu lembejeke kama;", "Mu mbunge yami."]}, {"type": "verse", "num": 3, "lines": ["Mumu lia manyinga ja Yena,", "Ku chawana che,", "Mbunge yami ya chinyengo,", "Ngwehe zango Lie."]}, {"type": "verse", "num": 4, "lines": ["Yena shima lia uhwimino,", "Ukwete mwono;", "Ngu huzule hapwila,", "Ngu konekene."]}]}, {"numero": 45, "titulo": "LIJI LIPEMA LIA CHILAMWINA", "blocos": [{"type": "verse", "num": 1, "lines": ["Liji lipema lia Yesu", "Katwaha lio chawana;", "Matu sanyika nyi zango,", "Hanga atwehe mwono."]}, {"type": "chorus", "lines": ["Keshi kwivwa ko e athu,", "Chipwe mwilu muli, pangu", "Maliji jacho apema", "Lie jina Lienyi Yesu."]}, {"type": "verse", "num": 2, "lines": ["Musenge wacho usasu,", "Yesu wanwine weswe,", "Kuli yoze mukwa shili,", "Hanga amu konekene."]}, {"type": "verse", "num": 3, "lines": ["He ha ulamwino unene,", "Kau hana chawana,", "Chatamba ku chi-uluka", "Hapwila nyi ku miaka."]}]}, {"numero": 46, "titulo": "SAMBUKILA YINGUNU", "blocos": [{"type": "verse", "num": 1, "lines": ["Mwene Yesu naku zanga,", "Kuhiana Chifuchi;", "Sambukila wangu hele", "Ngu chine kutoka."]}, {"type": "chorus", "lines": ["Kuli amwe kevwile ko,", "Ku zango lia yena!", "Kuli akwo kevwile ko,", "Ku sambukila Ye."]}, {"type": "verse", "num": 2, "lines": ["Mwene haka mwihi uli", "Kuhiana masepa;", "Naku wahilila chingi,", "Muze mungu nyonga."]}, {"type": "verse", "num": 3, "lines": ["Chiseke chinji ngunevu,", "Kuchina supwoka;", "Nyi kachi chishi nyi Yena,", "Mungu vulumuna."]}, {"type": "verse", "num": 4, "lines": ["Yena Chilamwina chami,", "Nguna wahilila", "Hamwe nyi Yena woma kha,", "Nguka mone huma Lei."]}]}, {"numero": 47, "titulo": "TWEYA KULI YAMI UHWIME", "blocos": [{"type": "verse", "num": 1, "lines": ["Liji lia Yesu nevwile,", "Tweya kuli Yami;", "Kujina kuhu uhwime", "Nguku lembejeke;", "Mba kuli Yesu nejile", "Ngwe mukwa chinyengo;", "Yingu wana uhwimino,", "Nyi kulembejeka."]}, {"type": "verse", "num": 2, "lines": ["Liji lia Yesu nevwile,", "Ngwo a mukwa pwuila;", "Wakama meya a mwono,", "Hetama hanga unwe;", "Mba kuli Yesu nejile", "Nanwine e meya;", "Nguna yuku pwila yahwa,", "Mba hanga ngutwame."]}, {"type": "verse", "num": 3, "lines": ["Liji lia Yesu nevwile,", "Nguli pangu hashi,;", "Linga wize kuli yami utambule pangu,", "Nawanyine Mwene Yesu,", "Tangwa lia henyama", "Mu lie pangu mungwendela,", "Ndo songo lia miaka"]}]}, {"numero": 48, "titulo": "HANJIKILA MU MBUNGE YAMI", "blocos": [{"type": "verse", "num": 1, "lines": ["Ngu hanjikile –A Kristu, nyi zango mu mbunge;", "Uli nyingune Mushi: Nguli Chilamwuina.", "Ngwazule mu mbunge, mba ngwivwe liji Lie,", "Hanga ngu kuhalise, Ngupwe nyi We pundu."]}, {"type": "chorus", "lines": ["Linyingune nyi yami, ungwiulule ngwe;", "Namwangine manyinga muku kulamwina.", "Heswe nguli hanjika, nyi zango Lie lieswe,", "Nguwambulwile mu twitwi: Nguli Chilamwina."]}, {"type": "verse", "num": 2, "lines": ["Hanjika nyi ana Je, hanga wa songwele;", "Azale nyi chiseke, ku milimo yeswe;", "Apwise kama –a ngunu, a kakulingile", "Uli mwe Mwanangana, hapwila muwiza."]}, {"type": "verse", "num": 3, "lines": ["Nguwe chize walingile, yikomokeso Ye;", "Nyi yami ungu lweze, se nguna yizange;", "Kunguna zange wika, ngu halise Yena,", "Miaka yeswe jina Lie, munguli vumbika."]}]}, {"numero": 49, "titulo": "TWIVWE KAMA KAFUNGA WA MWILU", "blocos": [{"type": "verse", "num": 1, "lines": ["Twivwe akafunga wa mwilu,", "Ku chihela chipema,", "Twali kungulwila mutanga,", "Hanga tuku lemese.", "Tu zangenu Yesu Mwene,", "Tweya utu wahise,", "Yesu mwene watu zanga,", "Tweya utu wahise."]}, {"type": "verse", "num": 2, "lines": ["nyi mutoka mwe mushili", "Nyi woma-wo mamona;", "Tuka sanyike e yiswale,", "Hanga evwe maliji;", "Tunayiji, tunayiji,", "Meza nyi kwalamwina?", "Tunayiji, tunayiji,", "Meza atu lamwine."]}, {"type": "verse", "num": 3, "lines": ["Neha chiswale ana kase", "Mutanga Lie a Mwene;", "Tambulako phanga mulelu", "Mu khondo –Ye kafunga;", "Twehe kulia, twehe kulia,", "Cha zango Lie lia Mwilu.", "Twehe kulia, twehe kulia,", "Cha zango Lie lia Mwilu."]}, {"type": "verse", "num": 4, "lines": ["Evwa kama kulemba chetu", "Che cha uhomboloji,", "Zalisa kama lie tanga Lie", "Nyi unene wa Yena;", "Hanga tuku chichimieke,", "Wakufunga kanawa.", "Hanga tuku chichimieke,", "Wakufunga kanawa."]}]}, {"numero": 50, "titulo": "JINA LIPEMA", "blocos": [{"type": "verse", "num": 1, "lines": ["Mbatako jina lilemu,", "Lia yesu Chilamwina;", "Muli kaku lembejeka", "Kweswako mukendela"]}, {"type": "chorus", "lines": ["Lie jina lipema,", "Kutalatala chetu,", "Lie jina, lipema kutalatala meza."]}, {"type": "verse", "num": 2, "lines": ["Endako nyi jina liacho,", "Hanga likulamwine;", "Likapwe uta unene,", "Muze upi muwiza."]}, {"type": "verse", "num": 3, "lines": ["Tulemesenu lie jina,", "Mulineha chiseke,", "Nyi Yesu makutayiza,", "Kuma kukonekena."]}, {"type": "verse", "num": 4, "lines": ["Jina liatela ulemu!", "Lia Yesu mukwa zango,", "Mwanangana wa masoma,", "Mwilu hamuswanyisa."]}]}, {"numero": 51, "titulo": "JINA LILEMU", "blocos": [{"type": "verse", "num": 1, "lines": ["Kukushi jina nyi limwe,", "Ngwe jina lia mwe Yesu,", "Yiye uhenya wa-angelo Jenyi,", "Pangu lia akwa ufulielo."]}, {"type": "chorus", "lines": ["Yesu! Yesu", "Kuhushi jina lipema!", "Yesu Yesu!", "Jina lia kulemesa"]}, {"type": "verse", "num": 2, "lines": ["Kukushi jina nyi limwe,", "Nyi chinyengo unevu;", "Kukushi jina nyi limwe,", "Mulineha chiseke."]}, {"type": "verse", "num": 3, "lines": ["Kunguna kutwaminyina,", "Muze Kristu mukeza,", "Nguka mone huma Lienyi,", "Ngwivwe mungu sanyika"]}, {"type": "verse", "num": 4, "lines": ["Nyi unazange milimo,", "Yakwambujola sango,", "Nyi yami nguna muzange", "Uwahiso We wa miaka."]}]}, {"numero": 52, "titulo": "YESU YANGWALUMUNA", "blocos": [{"type": "verse", "num": 1, "lines": ["Nguna toko mushili", "Kusuku nyi Yesu,", "Kunguna hono thachi,", "Kunguna lienyeka,", "Kristu kana ngumono", "Yapha kwoko Lienyi,", "Mangu lamwina kuku toka chami."]}, {"type": "chorus", "lines": ["Kanguzanga, ngupulule", "Nyi zango liahiana ngwalumune", "Thachi jenyi, zango Lienyi.", "Kristu, chilamwina ngwalumune."]}, {"type": "verse", "num": 2, "lines": ["We mwono wami weswe,", "Hanga ngumwehe wo;", "Ngupwe kulumbu lienyi,", "Zango lienyi, nguimbe;", "Ngu kambujole sango;", "Kuli akwa kutoka", "No eze hanga atambule", "Ulamwino."]}, {"type": "verse", "num": 3, "lines": ["Akwa shili, tweyenu,", "Kristu anulamwine,", "Yiye wika mahasa,", "Kulamwina Yesu,", "Aye chipwe kalunga", "Mamwononokena;", "Kanda uhonga", "Kumaku lamwina."]}]}, {"numero": 53, "titulo": "TALA ALI SHIMA", "blocos": [{"type": "verse", "num": 1, "lines": ["Kuli yitho yazuluka;", "Manyinga ja Yesu;", "Nyi mukosamo kulusu,", "Yipeka muyihwa", "Muyihwa ye yipeka", "Muyihwa ko yipeka", "Nyi mukosamo kulusu,", "Kumuli katoma."]}, {"type": "verse", "num": 2, "lines": ["Manyinga a Mwana-Phanga,", "Unene akwete;", "Mukwa-shili meza kuli Kristu,", "Kumanu lamwina", "Kumanu lamwina", "Kumanu lamwina", "Mukwashili eze kuli Kristu,", "Hanga hakulamwine."]}, {"type": "verse", "num": 3, "lines": ["Chize muze natayile,", "Mumu ha zango Lie,", "Ena hiwangu lamwina,", "Hichapwa ngwe pande", "Hichapwa ngwe mwaso", "Hitchapwa kuwaha,", "Mumu lia ulamwino we hichapwa je pande."]}, {"type": "verse", "num": 4, "lines": ["Mungu kaya mu uhenya We", "Ngukembe kanawa", "Uli Soma, Chilamwina chami,", "Ngu kaku halise", "Ngu kaku halise", "Ngu kaku halise", "Soma yami, Chilamwina,", "Ngu kaku halise."]}]}, {"numero": 54, "titulo": "MWANA: PANGA WA ZAMBI", "blocos": [{"type": "verse", "num": 1, "lines": ["Halisenu Mwana-Phanga", "Wamwene lamba hakulusu!", "Halisenu mayinga Jenyi", "Hamwanganyine yetu-akwa shili,", "Kukosa mu manyinga jacho,", "Akwa shili hanulamwina,", "Kuli zambi nuli musono"]}, {"type": "chorus", "lines": ["Ngwe chikokoto! Ngwe chikokoto!", "Kukosela mumanyinga yacho,", "Kumungu katoma chinji"]}, {"type": "verse", "num": 2, "lines": ["Chipangula cha mbimbo,", "Yesu amu twikile", "Yilonda amu lemekene", "China tulweze zango Lienyi!", "Ha yilonda china soloka,", "Ku yuka cha mukwa shili!", "Chinatomo nyi kuhiana.", "Manyinga Je mutwalumuna!"]}, {"type": "verse", "num": 3, "lines": ["Tata tukonekene, kama!", "Hanga twendele mu pangu Lie!", "Hikutu konekena ko wika,", "Tutomese nawa a Yesu!", "Shili utukonekene yo,", "Zango Lie kulia komwesa;", "Mba hanga nguka tome tho,", "Manyinga Je mutwalumuka!"]}]}, {"numero": 55, "titulo": "ULUMBUNWISO WAKULUSU", "blocos": [{"type": "verse", "num": 1, "lines": ["Shimbu te nguna laluka", "Kusuku nyi Mwene,", "Yakatuka mu malilu", "Alamwine mukwa shili."]}, {"type": "chorus", "lines": ["Hákulusu lume, he namunyingikina", "Shili yami Yesu yayifwila;", "Ha ufulielo, keshika namona;", "Nawahilila nyi pangu Lienyi."]}, {"type": "verse", "num": 2, "lines": ["Zago linene nevwile,", "Lie zango lia Yesu,", "Mu matwi ngwe najikile", "Nasawile kulusu"]}, {"type": "verse", "num": 3, "lines": ["Namwene ngwe umwe katana", "Meza kuli yami.", "Nachinyine ku molu a Kristu", "Aye yangu sweka."]}, {"type": "verse", "num": 4, "lines": ["Hi wangu kula a Kristu,", "Hinapwa wa Yena,", "Jina Lie nguli vumbike,", "Vumbi ha zango Lie."]}]}, {"numero": 56, "titulo": "MANYINGA WIKA", "blocos": [{"type": "verse", "num": 1, "lines": ["Yiya mangu lamwina?", "Kristu wamwangine manyinga.", "Kuli mungu sanyina?", "Ndo manyinga Jenyi wika."]}, {"type": "chorus", "lines": ["Ayo sambukila!", "Hakulusu Lienyi.", "Yesu mangwaha yo", "Ha manyinga Jenyi alemu."]}, {"type": "verse", "num": 2, "lines": ["Nguli nyi ulamwino?", "Manyinga Jenyi alemu;", "Zambi makonekena,", "Ha manyinga waze alemu."]}, {"type": "verse", "num": 3, "lines": ["Nyi sambukila Yenyi", "Manyinga Jenyi alemu;", "Zambi makonekena,", "Manyinga jacho alemu."]}, {"type": "verse", "num": 4, "lines": ["Ku makangu sambisa", "Manyinga akwete ulemu,", "Maneha sambukila.", "Manyinga jacho alemu."]}, {"type": "verse", "num": 5, "lines": ["Mwilu mungu kanjila,", "Ha manyinga Jenyi alemu,", "Mungukaku halisa,", "Manyinga Jenyi alemu."]}]}, {"numero": 57, "titulo": "YESU MANGUKULA", "blocos": [{"type": "verse", "num": 1, "lines": ["Yesu yangukula nyi manyinga!", "Ami mungu kamwimbila", "Yangu kula te kuchatele,", "Nyi che chawana chinene"]}, {"type": "chorus", "lines": ["Yangu kula, hakulusu yangukula Yesu;", "Yangu kula, ngunendela hapwila um pangu"]}, {"type": "verse", "num": 2, "lines": ["yangu kula Yesu chawana!", "Chiseke chacho chahiana!", "Pangu lina katuka mwuilu", "Munguka zala nalio tho."]}, {"type": "verse", "num": 3, "lines": ["Ngu shinginyeke kama Mwene,", "Ha mwalwa, ufuku nyi hakupomba,", "Chazangile kama kuhola,", "Ha chawana Che mungwimba."]}, {"type": "verse", "num": 4, "lines": ["Mungu kamona uhenya we,", "Mwanangana wa chiyulo;", "Masongwela je ngano jami", "Mangusa mwaso mukanwa"]}]}, {"numero": 58, "titulo": "KULI YESU CHICHI KAHONA", "blocos": [{"type": "verse", "num": 1, "lines": ["Lie liji lia Yesu", "Nguli mukwa shili", "Natayiza mu mbunge", "Yesu, mwe Chilamwina."]}, {"type": "chorus", "lines": ["Ye shili yami,", "Hi unayifwete,", "Ha kulusu chawana,", "Yesu yangulamwina."]}, {"type": "verse", "num": 2, "lines": ["Hi nguli mungunu ko;", "Wana-angu tuswile.", "Mikuli yami yeswe,", "Mwene hana yifwete."]}, {"type": "verse", "num": 3, "lines": ["Sambukila ya Yesu,", "Chiseke nyi keke;", "Chichi kahona chimwe,", "Shimbu nguli nyi Yesu"]}]}, {"numero": 59, "titulo": "CHIZE HAZE NAWANYINE UKONEKENO", "blocos": [{"type": "verse", "num": 1, "lines": ["Nguli nyi mwaso nazanga", "Hangu konekena", "Wa kasendo Chilamwina,", "Hangu konekena."]}, {"type": "chorus", "lines": ["Hangu konekena", "Hanangu lamwina, hanangu lamwina.", "Hana ngulamwina, mungo halisa Yesu.", "Hangu konekena, hanangu lamwina.", "A afumane Chilamwina."]}, {"type": "verse", "num": 2, "lines": ["Kristu kakungu wahisa,", "Hana ngulamwina,", "Ngulinge upale wenyi", "Hangu konekena."]}, {"type": "verse", "num": 3, "lines": ["Nguli nyi uwahililo,", "Hangu konekena", "Hana ngu mwangina manyinga", "Hangu konekena."]}, {"type": "verse", "num": 4, "lines": ["Nguli nyi zuwo mwilu", "Hangu konekena", "Miaka yeswe ngukatwame mo", "Hangu konekena."]}]}, {"numero": 60, "titulo": "LIWE LIA MIAKA", "blocos": [{"type": "verse", "num": 1, "lines": ["Mwe Yesu hamutondo", "Haze wangu fwilile,", "Wahichile manyinga", "Angukose ku-upi wami", "Ngukonekene kama", "Chiseke nyi ulamwino."]}, {"type": "verse", "num": 2, "lines": ["Chipwe hi yitanga ko,", "Mukwa shili masamba.", "Ndo wika Yena Yesu,", "Munwaha mwono nyi pangu;", "Ngukonekene Mwene,", "Ngujikijile zango Lie."]}, {"type": "verse", "num": 3, "lines": ["Chipwe kufwa muchiza,", "Cha mwono wacho, uno;", "Muze Munguya mwilu,", "Nguka mone huma Lie;", "Liwe lia miaka yeswe,", "Muli Yena ngutwame."]}]}, {"numero": 61, "titulo": "MANYINGA JENYI UNENE AKWETE", "blocos": [{"type": "verse", "num": 1, "lines": ["kuna zange kupuluka ku shili?", "Manyinga Jenyi ulemu akwete,", "Nyi unazange kuhichika Liapu?", "Manyinga unene akwete."]}, {"type": "chorus", "lines": ["Manyinga Je thachi akwete", "Ndo manyinga ja Yesu", "Kuli unene a mukwa shili!", "Taiza kuli Yesu"]}, {"type": "verse", "num": 2, "lines": ["Kuwazanga che kulengumuka?", "Manyinga Jenyi thachi akwete", "Upi nyi lamba kuwayi zanga?", "Manyinga Jenyi alemu."]}, {"type": "verse", "num": 3, "lines": ["Kuwazanga kutomesa mbunge ye?", "Manyinga Jenyi thachi akwete;", "Machiza ko yipeka ye yeswe?", "Manyinga tchachi akwete."]}, {"type": "verse", "num": 4, "lines": ["Una zange milimo ya Soma?", "Manyinga Jenyi thachi akwete;", "Wazanga kupwa mukweze Wenyi?", "Manyinga unene akwete."]}]}, {"numero": 62, "titulo": "YESU MEZA HAPWILA", "blocos": [{"type": "verse", "num": 1, "lines": ["Akweze ja Zambi shikenu yitavwi;", "Yesu hapwila meza;", "Twalenu maliji yifuchi yeswe;", "Yesu kumeza nawa."]}, {"type": "chorus", "lines": ["Ku makeza!", "Ku makeza!", "Yesu hapwila meza!"]}, {"type": "verse", "num": 2, "lines": ["Akwa ufulielo ambujolenu;", "Yesu hapwila meza!", "Sakwilenu, nyi chiseke, yimbenu;", "Yesu hapwila meza."]}, {"type": "verse", "num": 3, "lines": ["Milundu nyi mihwahwa yikolojoke", "Yesu ku meza nawa!", "Makimba-a kalunga embenu miaso", "Yesu ku meza nawa!"]}, {"type": "verse", "num": 4, "lines": ["Jita nyi zala tunayi mono,", "Yesu hapwila meza!", "Ye yikomokeso tunayi mono;", "Yesu hapwila meza."]}]}, {"numero": 63, "titulo": "MWENE NYI KAWASHI MEZA", "blocos": [{"type": "verse", "num": 1, "lines": ["Yifuchi yeswe hamona yilayi,", "Yina tulweze kwiza cha kristu;", "Enwe ngeji januhwa nyi kwenda?", "Tangwa lia-ulamwino hilia kundama!"]}, {"type": "chorus", "lines": ["Ambujolenu Sango ali!", "Kristu kaneza hapwila lume;", "Akwa mbunge ja zango lembenu;", "Kaneza kawashi, Mwene Chilamwina!"]}, {"type": "verse", "num": 2, "lines": ["Ye yilayi hana yisoneka", "Yina tulweze tangwa muliza;", "Athu to nyi mwongo wamilima;", "Amwe kana lezumuka nyi woma."]}, {"type": "verse", "num": 3, "lines": ["Zambi hambulwila akwa ufuleilo", "Kuli thachika chenu muchihwa;", "Nukapwe nyi zango mu mambunge,", "Lia waze azanga tangwa lipema."]}, {"type": "verse", "num": 4, "lines": ["Tupwenu nawa nyi thachi jikwo,", "Mumu tangwa kulishi kusuku,", "Yesu mejila akwa kushishika", "Akaye no mwe muchifuchi cha miaka."]}]}, {"numero": 64, "titulo": "MWANANGANA KU MEZA", "blocos": [{"type": "verse", "num": 1, "lines": ["Mwanangana ha kundama,", "Wafwilile ha kulusu;", "Mukwa ululi makaya", "Hamwe Nenyi mwilu."]}, {"type": "chorus", "lines": ["Haka mwihi he ali,", "Mumu Yiye heza ku pito", "Kumakeza, kumakeza.", "Hapwa lume ku pito."]}, {"type": "verse", "num": 2, "lines": ["Kutuna mono yilayi", "Kwiza se hicha kundama,", "Eswe waze maka kumba", "Makaya nyi Mwene"]}, {"type": "verse", "num": 3, "lines": ["Kanda upwa nyi chiseke,", "Jita kumuyi nunga;", "Ha kuhiluka cha Yesu,", "Yeswe, muyi kahwa."]}, {"type": "verse", "num": 4, "lines": ["Zuwo lietu mulikapwa,", "Muchifuchi chize chaha;", "Kufwa kuchichi kanjila,", "Yeswe yichi kahwa"]}]}, {"numero": 65, "titulo": "TANGWA CHALINYINGIKINE", "blocos": [{"type": "verse", "num": 1, "lines": ["Lie tangwa liaku hiluka ndungwi, kwiji,", "Yilayi wika yangu vwisa kuwaha,", "Haliapwa muchiza kusula cha hashi,", "Halie tangwa kwiji."]}, {"type": "chorus", "lines": ["Makeza etu tulayilile;", "Makeza aleluya! Aleluya!", "Ha malelwa meza nyi angelo mu uhenya,", "Mba lie tangwa kwiji."]}, {"type": "verse", "num": 2, "lines": ["Ye yisoneko, mamona akwa-ufulielo,", "Ngwo we uwahiso wetu himu wiza,", "Tutalenu we uhenya mu-ukeza,", "Mba lie tangwa kwiji."]}, {"type": "verse", "num": 3, "lines": ["Kulemba nyi kulayilila, chinate,", "Tu shimbwi shilenu mu pangu lipema;", "Muthuka hwima mulimbo lipema", "Mba lie tangwa kwiji."]}]}, {"numero": 66, "titulo": "KRISTU MEZA ALELUYA", "blocos": [{"type": "verse", "num": 1, "lines": ["Chimene nyi haku thuhuka cha tangwa,", "Pangu muli katemwina mumilima,", "Kristu makeza angelo mu-henya.", "Kristu maka tambula nyi-Enyi."]}, {"type": "chorus", "lines": ["Mwene, Yesu, Chilamwina", "Shimbu lika-mutwimba:", "Hiluka kristu, aleluya!", "Aleluya, Amem! Aleluya, Amem!"]}, {"type": "verse", "num": 2, "lines": ["Chimene, nyi muchikapwa; chingoloshi?", "Nyi hanji nawa mukachi ka ufuku,", "Pangu muli kalumuka lia uhenya", "Muze Kristu matambula nyi-Enyi."]}, {"type": "verse", "num": 3, "lines": ["Cho kuwaha chinji! Hakukumba che kufwa,", "Yesu maka twaha mwono ku-ushi kuhwa", "Eswe tukaye kuzuwo lia uhenya", "Mwe muzuwo Yesu analulieka."]}]}, {"numero": 67, "titulo": "YESU MEZA", "blocos": [{"type": "verse", "num": 1, "lines": ["Talenu, akwa ufulielo,", "Mumu kusula chineza;", "Ndeya jenu jitemuke", "Hindukenu nyi kawashi."]}, {"type": "chorus", "lines": ["Yo meza, Kristu meza!", "Meza ahinge nyi uhenya,", "Nyi akwa usandu hakukumba,", "Ku meza, Kristu meza"]}, {"type": "verse", "num": 2, "lines": ["Yesu hana lilakenya", "Ukonekeno nyi chawana,", "Uzalo nyi yipangula", "Lwezenu mavungu eswe!"]}, {"type": "verse", "num": 3, "lines": ["Te minyiko kuma soma;", "Lwezenu Chifuchi cheswe", "Ngwo yesu hapwila meza,", "Zango linji ali nalio."]}, {"type": "verse", "num": 4, "lines": ["Akwa shili eswe tweyenu,", "Kristu mapwa hako lienu;", "Tweyenu ye shimbu yino,", "Tweyenu Zambi manwita!"]}]}, {"numero": 68, "titulo": "HAMENE UHENYA", "blocos": [{"type": "verse", "num": 1, "lines": ["Hamene uhenya muze mu mukucha!", "Soma makeza", "Athu jenyi muchifuchi cha miaka!", "Aye makeza."]}, {"type": "chorus", "lines": ["Hamene uhenya muze mukucha.", "Pangu ku mulikeza!", "Hamene uhenya muze mukucha.", "Yesu kaneza"]}, {"type": "verse", "num": 2, "lines": ["Hindu tunevu maliji a miaka,", "Kanda nulaluka!", "Kumeza nyi uhenya uze wahiana,", "Mwe Kristu Mwene"]}, {"type": "verse", "num": 3, "lines": ["Nyi angelo mu-uhenya uze wahiana", "Kristu, Ngaji, meza!", "Mavungu, minyachi, liluliekenu,", "Kechi kushimbula."]}, {"type": "verse", "num": 4, "lines": ["Tuka mone waze afwile khulu,", "Tuka linunge no!", "Kushi kufwa, kulila chipwe yikola,", "Ku Chifuchi chetu."]}]}, {"numero": 69, "titulo": "KWILU HIKWACHA", "blocos": [{"type": "verse", "num": 1, "lines": ["Hilia kundama tangwa lia Kristu", "Ngunevu mangu sanyika;", "Ngwo tala kwilu hikwacha,", "Tenu pangu Lienyi himuliza"]}, {"type": "chorus", "lines": ["Chochene kwilu himu kucha-a!", "Chochene kwilu himu kucha-a!", "Ufuku mu-uchina, mwalwa ku-uneza,", "Chochene kucha hicha kundama!"]}, {"type": "verse", "num": 2, "lines": ["Yilayi yeswe yiya palika,", "Hashi mwilu mukalunga,", "Talenu kwilu hikwacha,", "Kwiza cha Kristu hicha kundama."]}, {"type": "verse", "num": 3, "lines": ["Laulenu haliapwa hikwacha,", "Kulizelula chimbilenu,", "Nutemwine pangu hashi,", "Pwenu thethekeli ja thununu."]}, {"type": "verse", "num": 4, "lines": ["Yenu hanga nuka kolojoke", "Hashi, mwilu nyi mukalunga,", "Yilema, tupuputa, kwalakenya,", "Ku chiwanyino chinene cha zambi"]}]}, {"numero": 70, "titulo": "UHENYA! ALELUYA! KRISTU MEZA", "blocos": [{"type": "verse", "num": 1, "lines": ["Aleluya, Kristu meza!", "Tumu tambulenu", "Nyi athu eswe aliho,", "Tambulenu Mwanangana", "Swanyisenu Soma,", "Swanyisenu Soma,", "Mwe Yesu, Mwanangana Yiye Soma."]}, {"type": "verse", "num": 2, "lines": ["Aleluya, meza ahinge", "Kana Muswanyisa,", "Ku milundu , nyi muyilombo,", "Ku mbunga ja athu,", "Ku mbunga ja athu,", "Mwe Soma Yiye,", "Mwanangana wayifuchi."]}, {"type": "verse", "num": 3, "lines": ["Shili nyi yikola, kuyishiko,", "Chipwe missongo kha;", "Se yesu mwe mwanangana,", "Matwaha yeswe twafupa,", "Mu pangu lia zango…", "Mu pangu lia zango…", "Lie zango, zango lia Tata wa mwilu."]}, {"type": "verse", "num": 4, "lines": ["Ku makeza hanga ahinge,", "Tu wahililenu,", "Ululi nyi sambukila,", "Maka twaha uwahiso,", "Tulamwine kama..,", "Tulamwine kama..,", "Wa miaka, hanga tuka lindujoke."]}]}, {"numero": 71, "titulo": "MUZE MWANANGANA MAKEZA", "blocos": [{"type": "verse", "num": 1, "lines": ["Yesu kana lulieka kulia,", "Kashishika nyi kulakenyia;", "Mba kuchi yena nyi yami?", "Hakwiza cha soma?"]}, {"type": "chorus", "lines": ["Muze soma meza ndumbwami,", "Muze soma makeza.", "Mba kuchi yena nyi yami,", "Hakwiza cha soma?"]}, {"type": "verse", "num": 2, "lines": ["Yoze wa twama mu lie pangu,", "Watufwilile hákulusu;", "Anenyi makaya no mwilu,", "Muze aye meza."]}, {"type": "verse", "num": 3, "lines": ["Makatambula ana jenyi,", "Maka-ajika uzalo utoma;", "Muykapwa ola yetu yipema", "Hakwiza cha soma."]}, {"type": "verse", "num": 4, "lines": ["Kumaka handununa ko akwo", "Waze keshi ulamwino;", "Makalila chimwe chahiana;", "Hakwiza cha soma."]}]}, {"numero": 72, "titulo": "KUKUCHI KAPWA NAWA MILIMA", "blocos": [{"type": "verse", "num": 1, "lines": ["Yesu kechi keza ufuku kha", "Yesu kechi keza ufuku kha", "Yesu kechi keza ufuku kha", "Akejile anenyi.", "WTAWIZO", "Akejile anenyi", "Akejile anenyi", "Yesu kechi keza ufuku kha", "Akejile anenyi."]}, {"type": "verse", "num": 2, "lines": ["Nyi yikolo kuyichi kapwa ko", "Nyi yikolo kuyichi kapwako", "Kuwaha wika ha kwiza chenyi", "Akejile anenyi."]}, {"type": "verse", "num": 3, "lines": ["Kulila ako kuchichi kapwa", "Kulila ako kuchichi kapwa", "Kulembejeka muchikapwa ko", "Akejile anenyi"]}, {"type": "verse", "num": 4, "lines": ["Mutu kamu halisa ha kwiza", "Mutu kamu halisa ha kwiza", "Chiseke chinji muze makeza", "Akejile anenyi."]}]}, {"numero": 73, "titulo": "YESU KANEZA HAKUMBA", "blocos": [{"type": "verse", "num": 1, "lines": ["Hakumba kana mutwala", "Ye yizavu ya angelo.", "Yesu majinga Chifuchi", "Nyi lelwa lia kukumba,", "Aleluya! Meza nyi kutumina", "Aleluya! Meza nyi kutumina"]}, {"type": "verse", "num": 2, "lines": ["Uhenya wenyi, wahiana,", "Eswe mutu kaumona,", "Lamba kuli akwa shili", "Waze amushihile", "Tungumuku makamumona yo meza!", "Tungumuku makamumona yo meza!"]}, {"type": "verse", "num": 3, "lines": ["Muze hashi muhachikima;", "Yizenge malimbwoka", "Mukwa shili malezumuka", "Haze hambozo yenyi", "Ha usoma Wenyi Kristu meza asopese!", "Ha usoma Wenyi Kristo mesa asopese!"]}, {"type": "verse", "num": 4, "lines": ["Vumbi uhenya, kusakwila", "Kuli Soma ya Mwilu!", "Tambula Usoma, solola", "Kuhisa Che a Zambi!", "Mu Usoma We, Mwene Yesu uhinge!", "Mu Usoma We, Mwene Yesu uhinge!"]}]}, {"numero": 74, "titulo": "KRISTU KANAKUSANYIKA", "blocos": [{"type": "verse", "num": 1, "lines": ["Kristu maku sanyika nyi zango;", "Mukwa shili tweya kuli Yiye!", "Kanda wivwa woma umuchine,", "Lihane kuli Yesu!"]}, {"type": "chorus", "lines": ["Mukwa shili, Yesu au", "Tweya ute, Chilamwina kana sanyika!"]}, {"type": "verse", "num": 2, "lines": ["Kristu kana kusanyika uhwime;", "Mukwa shili tweya kuli Yiye!", "Chilemo che machitepulula", "Yesu makutambula!"]}, {"type": "verse", "num": 3, "lines": ["Tweya Kristu, makukonekena;", "Mukwa shili tweya ute!", "Yeswe alingile akulamwine", "Tweya Yesu akulamwine!"]}, {"type": "verse", "num": 4, "lines": ["Kristu kana kusanyika nawa;", "Mukwa shili tweya ute!", "Tambuka ko hanga ulihane", "Kanda ukokoloka."]}]}, {"numero": 75, "titulo": "CHIHOMBOLOJI", "blocos": [{"type": "verse", "num": 1, "lines": ["Nyi uhomboloji Yesu masanyika", "Yena nawa nyi yami,", "Tala se pito lichili lia washi,", "Hali yena nyi yami."]}, {"type": "chorus", "lines": ["Tweya, tweya, a,a!", "Yena jinakuhu tweya a!", "Chihomboloji Yesu masanyika;", "Yena: “Chivulumunyi”!"]}, {"type": "verse", "num": 2, "lines": ["Yika tuna manyina? Yesu ngwenyi,", "Tweya yena nyi yami.", "Kanda usaula makwaha mwono,", "Mahana yena nyi yami"]}, {"type": "verse", "num": 3, "lines": ["Shimbu yinayi mathangwa kanahu,", "Hali yena nyi yami,", "Lamba nyi ufwe yatuzulamina,", "Mwe yena nyi yami"]}, {"type": "verse", "num": 4, "lines": ["Zango linene Yesu atuhele", "Kuli yena nyi yami,", "Heneza atulamwine ku shili,", "Wejile hali yetu."]}]}, {"numero": 76, "titulo": "MBUNGE HIYALAULA", "blocos": [{"type": "verse", "num": 1, "lines": ["Mbunge hayi lawisa-a", "Yesu kuma lamwina;", "Etu eswe kutuna kwichi", "Kristu utulamwine."]}, {"type": "chorus", "lines": ["Kasendo, tweya nyi,", "Lihane kuli Yesu!", "Kasendo, tweya, nyi,", "Aye makulamwina!"]}, {"type": "verse", "num": 2, "lines": ["Kuzwela mba hichawa,", "Cha sonyi nyi kutoka.", "Kushishika, nyi zango", "Mwene makulamwina,"]}, {"type": "verse", "num": 3, "lines": ["Ya hashi nyi chechimwe", "Yichi kakulamwina", "Yesu wika makwaha", "Ulamwino nyi zango"]}, {"type": "verse", "num": 4, "lines": ["Kasendo kanda ushimbula", "Tayiza kuli Yesu,", "Muli Yiye mukawana mo", "Mwono wa sambukila."]}]}, {"numero": 77, "titulo": "MWESWAWO HEVWA MALIJI", "blocos": [{"type": "verse", "num": 1, "lines": ["Mweswawo hevwako, a-ambujole;", "Kutambula wa wana ulamwino.", "Hanga Chifuchi cheswe chivwe maliji;", "Mweswe mazanga eze!"]}, {"type": "chorus", "lines": ["Mweswe mazanga! Eze atambule!", "Eswe hanga evwe maliji apema", "Mwe Tata wa mwilu unatu sayika;", "Mweswe mazanga eze!"]}, {"type": "verse", "num": 2, "lines": ["Mweswawo hevwako eze atayize;", "Pito lichili liawashi njilenu;", "Yesu ye jila manutwala mwilu;", "Mweswe mazanga eze"]}, {"type": "verse", "num": 3, "lines": ["Chilakenyo chipema a mukwa shili;", "Unazange mwono? Tweya kuli Yesu;", "Nyi kuzanga chinji kanatulweze.", "Mweswe mazanga eze!"]}]}, {"numero": 78, "titulo": "WANGUZANGA YAMI CHIVULUMUNYI", "blocos": [{"type": "verse", "num": 1, "lines": ["Mwono pajika Mwene;", "Yesu mwe Chilamwina;", "Kana kwambe nyi zango;", "Ami kuwangu Zanga?", "Yami nakujitwile,", "Naukile yilonda ye;", "Nakatukile mwilu.", "Amukwa-shili wanguzanga?"]}, {"type": "verse", "num": 2, "lines": ["Uhenya-Wami mukamona,", "Mukalia ye yawana,", "Mwono mungu kakwaha,", "Chichi kakuhichika.", "Mwene nguna linyenge", "Mumu chishi nyi zango;", "Ngwalumune a Yesu,", "Ngupwe –nyi zango lia Yena."]}]}, {"numero": 79, "titulo": "NGUKAULE! TWEYAUNGUKAULE", "blocos": [{"type": "verse", "num": 1, "lines": ["Panjika liji lia Yesu;", "Ngu kaule kaula!", "Mungu kutwala ku pangu;", "Ngu kaule kaula!", "Nakuhetesele shimbi;", "Nakunwina yize yisasu;", "Nakufwilile nyi lamba;", "Ngukaule kaula."]}, {"type": "verse", "num": 2, "lines": ["Naku tusula ku shili,", "Ngukaule, ngukaule!", "Mwilu mungu kusongwela,", "Ngukaule, kaula!", "Nakuku sanyika chinji,", "Kuwafungile shimbi Jami", "Hinguna kupwila chela;", "Ngukaule kaule"]}, {"type": "verse", "num": 3, "lines": ["Makahwimina hali Yami;", "Ngukaule, kaula;", "Tweya unehe shili ye;", "Ngukaule kaula!", "Nguli Zambi, Chilamwina", "Nakuzanga mukwa shili,", "Hichika woma we weswe", "Ngukaule,kaula."]}, {"type": "verse", "num": 4, "lines": ["Yesu, munguku kaula,", "Ngukaule, kaula!", "Munguka hichika yeswe,", "Nguhichike, hichika,", "Nguli mulelu liakulu,", "Chichi kuhasa kwenda kha;", "Nguzalise nyi thachi Je,", "Ngukaule, kaula."]}]}, {"numero": 80, "titulo": "MWECHE ANJILE", "blocos": [{"type": "verse", "num": 1, "lines": ["Kristu yeu kupito,", "Munjise;", "Mwazulwile anjile,", "Munjise;", "Kuma kukonekena,", "Sambukila makwaha,", "Kachi kakuhichika", "Munjise"]}, {"type": "verse", "num": 2, "lines": ["Mwazulwile mbunge ye,", "Munjise;", "Kanda ukokoloka,", "Munjise;", "Makapwa kasendo ke", "Ku yipi akufunge,", "Yiye makupulwila,", "Munjise"]}, {"type": "verse", "num": 3, "lines": ["kanda umu manyisa,", "Munjise;", "Nyi kha makuhichika;", "Munjise;", "Nyi kha yikola mwivwa;", "Kechi kakwivwa nawa;", "Nyi kha mulitokela.", "Munjise."]}]}, {"numero": 81, "titulo": "PITO LIAWASHI", "blocos": [{"type": "verse", "num": 1, "lines": ["Kana twazulwila pito", "Lia kuzuwo lia mwilu;", "Kristu kumatutayiza", "Tunjile hitwakumba."]}, {"type": "chorus", "lines": ["Keke ya Yesu yahiana", "Lie pito yangwazulwila!", "Yami, yami;", "Hana ngwazulwila."]}, {"type": "verse", "num": 2, "lines": ["Mukwa shili nyi muzanga,", "Pito hakwazulwila!", "Mwilu mukapwa nyi zuwo", "Lize Kristu makwaha"]}, {"type": "verse", "num": 3, "lines": ["Akwa shili eswe tweyenu,", "Kanda nukokoloka,", "Nyi kha shimbu muyipalika,", "Ola ya ulamwino."]}]}, {"numero": 82, "titulo": "KULI YESU NYI CHIMWE", "blocos": [{"type": "verse", "num": 1, "lines": ["Mbunge ye yinazala,", "Kushi chihela cha Yesu?", "Nyi kushi ufulielo,", "Waku kaula Yesu?", "Hanakufwila hakulusu,", "Hindu kana ngongwela,", "Laula mukwa thulo,", "Ukaule mwe Yesu."]}, {"type": "verse", "num": 2, "lines": ["Unenyeka shimbu ye,", "Ku-ushi chuma cha Yesu?", "Unenyeka mbongo je,", "Ku-ushi chuma cha Yesu", "Una zange mu pangu?", "Umu fumbwile akwenu?", "Tweya ukilikite,", "Ukaule mwe Yesu."]}, {"type": "verse", "num": 3, "lines": ["Yipi una kaula,", "Uhichike mwe Yesu?", "Yiye wa miaka yeswe,", "Upihise kulusu.", "Tweya tambula pangu,", "Tambula zango Lienyi?", "Tayiza kuli Chilamwina,", "Mba ukamone Yesu."]}, {"type": "verse", "num": 4, "lines": ["Mafwo a mokomoko,", "Mihuko ya Yesu mba?", "Mutondo ku-ushi thachi,", "Ye milima wazanga", "Mba thachi ja kulusu,", "Fuliela zango lia zambi", "Wivwe kuwaha cha mwilu", "Mba ukamone Yesu"]}]}, {"numero": 83, "titulo": "YIYA ULI KUSALI LIA MWENE", "blocos": [{"type": "verse", "num": 1, "lines": ["Unazange upwe kuli Mwene?", "Nyi ku-unazange Satana?"]}, {"type": "chorus", "lines": ["Mosono tongola kusali lika unazange?", "Musono tongola:", "Kutoka hanji nyi kumwono."]}, {"type": "verse", "num": 2, "lines": ["Tununu hindu ali mushili,", "Kanatalikisa ku ufwe."]}, {"type": "verse", "num": 3, "lines": ["Tweyenu kusali lia Mwene Yesu,", "Munuwana ulamwino, nyi sambukila."]}]}, {"numero": 84, "titulo": "LWANO UMUWIKA", "blocos": [{"type": "verse", "num": 1, "lines": ["Ayema maliji ha mwe Yesu,", "Masanyika nyi zango,", "Nyi kuzazulula moko kanambe,", "Tweya kuli Chilamwina!"]}, {"type": "chorus", "lines": ["Kristu kasanyika angulamwine,", "Shimbu yimuwika, ufulielo!", "Mungu lisa kuchitamba Che,", "Ungutayize a Kristu."]}, {"type": "verse", "num": 2, "lines": ["Shili ye yinji kuwahonga!", "Makwonga mukwa yizezo.", "Hinalinga yeswe liji linambe", "Fuliela Chilamwina!"]}, {"type": "verse", "num": 3, "lines": ["Nguna lele namba kulimbuka;", "Nguna khakajana.", "Chichi kwivwa woma, mumu lia Kristu:", "Kechi kangwehuka."]}, {"type": "verse", "num": 4, "lines": ["Chifuchi cha mahuza, chinatoko;", "We mwalwa wamahuza,", "Sambukila, mwono zango anangwehe;", "Nguli wa Yesu mu mbunge."]}]}, {"numero": 85, "titulo": "KULI YENA NGUNEZA A MWENE", "blocos": [{"type": "verse", "num": 1, "lines": ["Napwile nyi chinyengo mu mwono,", "Kusuku nyi Chilamwina chami;", "Sambukila nyi ukonekeno,", "Kuli Yena Mwene.", "Kulithachika nyi yeseko,", "Lamba nyi luyinda namwene;", "Kujikiza mu mbunge yami,", "Mwene kungu neza."]}, {"type": "verse", "num": 2, "lines": ["Kulengumuka mungu chimbila,", "Kusuku a Chilamwina;", "Nguna zange zango lia Yena,", "Ngulingile Mwene.", "Zango lia Yena kuliahiana", "Kunguna wahilila nalio,", "Nguna zange tutwame hamwe;", "Hanga ngupwe nyi we."]}, {"type": "verse", "num": 3, "lines": ["Chishi woma wakufwa nawa,", "Se hamwe tuli nyi Yena;", "Ngunazange tukapwe hamwe.", "Uka ngutambule.", "Nguna zange kupwa nyi Yena,", "Hamwe nyi Yena ngwase jita,", "Nguka kumbe nyi hanji kufwa;", "Kristu Chilamwina."]}]}, {"numero": 86, "titulo": "NGUHILUKILE KUZUWO", "blocos": [{"type": "verse", "num": 1, "lines": ["Kusuku nguli nyi Mwene", "Nguye ku zuwo;", "Ngunende mu majila api;", "Nguhiluke a Zambi."]}, {"type": "chorus", "lines": ["Munguya kuzuwo,", "Nalungajala,", "Ngu kwate nyi kwoko Lie;", "Ngwize a Mwene."]}, {"type": "verse", "num": 2, "lines": ["Ngunenyeka shimbu yami,", "Nguye ku zuwo;", "Chipi kwenyeka je shimbi;", "Ngwize a Zambi."]}, {"type": "verse", "num": 3, "lines": ["Hijanguhwa shili nyi lamba,", "Nguye kuzuwo;", "Nguna fuliela zango Lie;", "Nwize a Zambi."]}, {"type": "verse", "num": 4, "lines": ["Manyinga Je mangu tomesa;", "Nguye kuzuwo;", "Ngutomese tho ngwe mbundu;", "Ngwize a Mwene."]}]}, {"numero": 87, "titulo": "KUKAULA YESU", "blocos": [{"type": "verse", "num": 1, "lines": ["Yesu mungu mukaula,", "Chipwe kuyuka yeswe;", "Kuze Longeshi makaya", "Ngukaule woma kha."]}, {"type": "chorus", "lines": ["Yesu nguna ku kaula,", "Yena wangu fwilile", "Chipwe eswe, makuchina", "Hindu mungu kukaula."]}, {"type": "verse", "num": 2, "lines": ["Chipwe jila muyikala,", "Nyi milima yahiana:", "Ena wayipalikile", "Ungu kwate ku kwoko."]}, {"type": "verse", "num": 3, "lines": ["Nyimungu mona lamba,", "Yizezo muyingwoka,", "Chipwe Yena akuzezele", "Wamwene lamba linji"]}, {"type": "verse", "num": 4, "lines": ["Nyi muzanga kungu twala", "Muphuya ya chinyengo", "Chipwe Yena wayile mo", "Ngu kaule nyi ngano."]}, {"type": "verse", "num": 5, "lines": ["Nyi Yena ku-unazange", "Ngu zauke mwe yordau", "Yesu, wamuzaukile", "ngu kaule nyi hamu."]}]}, {"numero": 88, "titulo": "NYI KRISTU MAYA NYI YAMI", "blocos": [{"type": "verse", "num": null, "lines": ["Muyihela ya khole munguka palika;", "Nyi milundu yisuku nguye nyi kuwaha;", "Kunguna jikiza muchihuhumuke;", "Ngwendele mu pangu, hamwe nyi Yesu."]}, {"type": "chorus", "lines": ["Kweswako hindu mutuya, nyi Yesu", "Ngufunge shimbi, mwilu ngukaye;", "Hamwe Nenyi.", "Lie zango liami ngumbate lie kulusu;", "Kweswako hindu Munguya nyi Yesu."]}, {"type": "verse", "num": 2, "lines": ["Chipwe meya a mwono,", "Nguwambachile Yoze", "Nyi kachi muzanga mungu", "Kulongesa,", "Nyi mungu songwela nguye nyi Yesu"]}, {"type": "verse", "num": 3, "lines": ["Chipwe kunyonga chami numbate kulusu", "Ayo kana linyenge mumu ha shili yo;", "Ami ngufuliele ngumwononoke", "Yeswayo mangwamba nguye nyi Yesu."]}, {"type": "verse", "num": 4, "lines": ["Yeswe Kristu mangwamba chichi", "Kukolema,", "Mungu mukaula kweswe masongwela", "Nguye kweswe mamba nyi chiseke chinji", "Shimbu yeswe nyi yami nguli nyi Yesu."]}]}, {"numero": 89, "titulo": "SANGO LIA KULUSU", "blocos": [{"type": "verse", "num": 1, "lines": ["Yajika kulusu ha mulundu umwe,", "Chinyingi cha sonyi nyi lamba;", "Nazanga kulusu, henaho mwe Yesu,", "Afwilile ha shili yami."]}, {"type": "chorus", "lines": ["Nazanga sango lia kulusu;", "Nguliambujole ndo kukufwa,", "Ngumbate lie kulusu liami", "Mba ngutambule chipangula."]}, {"type": "verse", "num": 2, "lines": ["Yahichika uhenya", "Mwana-Phanga wa Zambi", "Ha ngongota yamona lamba", "Hakulusu liacho nguna wahilila", "Henaho angulamwinyine."]}, {"type": "verse", "num": 3, "lines": ["Lie lamba amwene kusongo mba yafwa", "Yesu hanga angukonekene", "Hakulusu Lienyi ngunawahilila,", "Mumu ha ulamwino wami."]}, {"type": "verse", "num": 4, "lines": ["Hamwe nyi mwe Yesu, sonyi ja kulusu", "Chipwe nyi lamba ngulimbate.", "Aye mangwijila nguye nenyi hamwe.", "Kuzuwo Lienyi lia uhenya."]}]}, {"numero": 90, "titulo": "OLA YILEMU YAKULEMBA", "blocos": [{"type": "verse", "num": 1, "lines": ["Ola yakulemba te, sambukila mwilu,", "Tutalenu mwe Kistu kasendo ketu;", "Shimbu yacho yilemu, tuhanjike Nyenyi,", "Muyineha je thachi, chinapeme kulemba."]}, {"type": "chorus", "lines": ["Chipema kulemba, kulemba nyi thachi.", "Muchineha je thachi!", "Chinapeme kulemba"]}, {"type": "verse", "num": 2, "lines": ["Ola yakulemba te, yisongwele mwono,", "Ku yinyengo ya mwono ku Molu a Yesu;", "Tu mwimbilenu miaso, ngwe", "Makimba a kalunga,", "Muyineha je thachi, chinapeme kulemba"]}, {"type": "verse", "num": 3, "lines": ["Ola yakulemba te, muze mukua kuzeza", "Mamukumba nyi tachi ja chilamwina;", "Malilu ma soloka nyi uhenya unji,", "Muyineha je tachi chinapeme kulemba."]}]}, {"numero": 91, "titulo": "NGUNAZANGE KUPWA HAKAMWIHI NYI KULUSU", "blocos": [{"type": "verse", "num": 1, "lines": ["Nguli wa Yena, liji Lie nevwa", "Zango lina ngutambieka;", "Mwene nguna zange kupwa hehi,", "Vulie a Chilamwina!"]}, {"type": "chorus", "lines": ["Haka muihi nyi kulusu Lie,", "Nguna zange Chilamwina!", "Ngukundame he hakulusu Lie;", "Ngumbate Mwene wami."]}, {"type": "verse", "num": 2, "lines": ["Ku nguna lihana kuli Yena,", "Ku zango Lie ngu tambule;", "Mbunge yami yinawahilila", "Mwene nguku lingile."]}, {"type": "verse", "num": 3, "lines": ["Hi kuwaha ko! Chiseke chinji", "Kutwama kuyiliato Ye;", "Nyi ufulielo wakutakama,", "Nguhanjike nyi Mwene."]}]}, {"numero": 92, "titulo": "NGUNAZANGE KUPWA HAKAMWIHI NYI KULUSU", "blocos": [{"type": "verse", "num": 1, "lines": ["Hehi nyi kulusu Lie", "Shima lia upite,", "Liolio mulivwelwoka", "Mulundu Shiyono."]}, {"type": "chorus", "lines": ["Kulusu, Hakulusu,", "Nguna wahilila,", "Munguya ngukahwime,", "Musali lia lwiji."]}, {"type": "verse", "num": 2, "lines": ["Ha woma wa kulusu,", "Chawana cha miaka,", "Muthumbu wachimene,", "Kanangu temwina."]}, {"type": "verse", "num": 3, "lines": ["Hakulusu Zambi yami,", "Hanga ungwi-uluke;", "Mushi lia Chilamwina,", "Hanga ungusweke."]}, {"type": "verse", "num": 4, "lines": ["Hakulusu nyi ufulielo,", "Chishi kwivwa woma;", "Nguye Chifuchi chacho,", "Mba nguli lamwine."]}]}, {"numero": 93, "titulo": "HEHI HAKAMWIHI LUME", "blocos": [{"type": "verse", "num": 1, "lines": ["Longeshi wa mwilu, mwe Yesu,", "Ngusongwele hehi nyi kulusu!", "Nguna zange sambukila Ye", "Yize mungwaha nguyi tambule.", "Yize mungwaha nguyi tambule."]}, {"type": "verse", "num": 2, "lines": ["Ngukapwe hehi nyi mwe Kristu,", "Chishi nyi chuma ngumu lambule;", "Ndo wika mbunge yami yipi,", "Kwi-yinyengo ngwite ukonekeno.", "Kwi-yinyengo ngwite ukonekeno."]}, {"type": "verse", "num": 3, "lines": ["Hehi nyi Yena Zanbi yami,", "Shili yami yimbile kusuku;", "Nguhichike yeswe ha zango Lie,", "Ngunazange Yesu Chilamwina,", "Ngunazange Yesu Chilamwina chami"]}, {"type": "verse", "num": 4, "lines": ["Nuna zange ngupwe hakamwihi,", "Ndo mungu heta lume musali", "Kuze mungu kapwa nyi Mwene,", "Mba ngumu halise ha zango Lie,", "Mba ngumu halise ha zango Lie."]}]}, {"numero": 94, "titulo": "KUTALA", "blocos": [{"type": "verse", "num": 1, "lines": ["Ha kutala ha kulusu,", "Afwilile Soma ya uhenya,", "Chiseke cha mwono wa hashi", "Ami chachalwile nawa."]}, {"type": "verse", "num": 2, "lines": ["Kandangulisamba, a Zambi yami", "Ngu sambile ha ufwe wa Yesu;", "Chize nakuzanga chinji", "Nguchi hichike, ha zango Lie."]}, {"type": "verse", "num": 3, "lines": ["Talenu! Kulusu lia manyinga,", "Shima lia chinyengo nyi zango;", "Yikola nyi keke ya Yesu", "Mumu lia yami muthu mupi."]}, {"type": "verse", "num": 4, "lines": ["Chifuchi cheswe te nyi chami,", "Kachi mungu chaha Yesu;", "Mumu hakumba ha kulusu.", "Nyi mwono weswe nyi zango."]}]}, {"numero": 95, "titulo": "NGWEHE KRISTU", "blocos": [{"type": "verse", "num": 1, "lines": ["Wa chifuchi ngwehe Kristu,", "Chiseke chamokomoko;", "Soma ya zango lia miaka", "Kulishi kwalumuka."]}, {"type": "chorus", "lines": ["Kutanda chize, chisuku,", "Ha lie zango lia Yesu!", "Kuli Yiye twajikijila", "Tukatwame mu pangu."]}, {"type": "verse", "num": 2, "lines": ["Wa chifuchi ngwehe Kristu,", "Chikwashi ha lie lamba;", "Nyi mungupwa nyi Chilamwina", "Ku mangu lembejeka."]}, {"type": "verse", "num": 3, "lines": ["Wa Chifuchi ngwehe Kristu,", "Angu sambise Yiye;", "Muno mu ungeji nguli", "Ngwendele mujila Ye."]}, {"type": "verse", "num": 4, "lines": ["Wa chifuchi ngwehe Yesu,", "Ngufuliele kulusu,", "Mwene mungu kamumona,", "Huma Lienyi mu pangu."]}]}, {"numero": 96, "titulo": "YESWE MUNGUMWAHA", "blocos": [{"type": "verse", "num": 1, "lines": ["Yeswe, Kristu, mungu kwaha,", "Yeswe, mungu kwaha yo!", "Nyi hamu, nyi kwononoka,", "Ngu kaule ndo miaka."]}, {"type": "chorus", "lines": ["Ngu mwehe yeswe! Ngu mwehe yeswe!", "Mumu lia Yesu, mupema,", "Yeswe ngu kwehe."]}, {"type": "verse", "num": 2, "lines": ["Yeswe, Kristu mungu kwaha,", "Mbunge nyi mwono yino!", "Nguna likale Chifuchi,", "A Yesu, ngu tambule!"]}, {"type": "verse", "num": 3, "lines": ["Yeswe, Kristu, mungu kwaha,", "ngupwe mwe nyi We pundu;", "Ngononoke ku-upale We,", "Ngwe angelo mu malilu."]}, {"type": "verse", "num": 4, "lines": ["Yeswe, Kristu, mungu kwaha,", "Nguna mono zango Lie", "Alumuna mwono wami", "Nyi mbunge yami, a Mwene!"]}, {"type": "verse", "num": 5, "lines": ["Yeswe, Kristu, mungu kwaha,", "Cho kuwaha, a Mwene!", "Sambukila nyi chiseke!", "Uhenya, uhenya Chilamwina!"]}]}, {"numero": 97, "titulo": "CHIZE CHENE NGULI", "blocos": [{"type": "verse", "num": 1, "lines": ["Chize chene nguli-a Mwene,", "Manyinga Je malamwina", "A mwanganyine ha shili;", "A Chilamwina, Nguneza!"]}, {"type": "verse", "num": 2, "lines": ["Se chishi kutalatala", "Ngwalumune mwono wami,", "Chawana Che kucha hiana;", "A Chilamwina nguneza!"]}, {"type": "verse", "num": 3, "lines": ["Nguna hono chishi thachi,", "Tala hakuhona chami", "Ha yeswe yize nafupa;", "A Chilamwina nguneza!"]}, {"type": "verse", "num": 4, "lines": ["Chize chene ngu tambule;", "Kosa kama mbunge yami,", "Nyi zango Lie ungu sweke;", "A Chilamwina!"]}]}, {"numero": 98, "titulo": "TWEYENU", "blocos": [{"type": "verse", "num": 1, "lines": ["Lino tangwa lia ulamwino,", "Tweyenu ngunu tomese;", "Nguna nusanyika tweyenu,", "Hingu nanufwila,", "Tweyenu…"]}, {"type": "verse", "num": 2, "lines": ["Hinguna mwange manyinga,", "Lio lamba nakumwenene,", "Nguna nusanyika, tweyenu,", "Hingu nanufwila", "Tweyenu…"]}, {"type": "verse", "num": 3, "lines": ["Mwono nanwaha nyi zango,", "Tweyenu kuli Chilamwina!", "Ngunanu sanyika tweyenu,", "Hingu nanufwila,", "Tweyenu…"]}, {"type": "verse", "num": 4, "lines": ["Uhindukilo muwiza,", "Jikijila kuli Yami,", "Ngunanu sanyika, tweyenu,", "Hingu nanufwila,", "Tweyenu…"]}]}, {"numero": 99, "titulo": "KULIHANA MWESWE", "blocos": [{"type": "verse", "num": 1, "lines": ["Tambula Zambi mwono wami,", "Nguna kwehe wo Yena Mwene,", "Tambula moko jami,", "Alinge milimo Ye."]}, {"type": "chorus", "lines": ["Ngukoseuum manyinga a Yesu,", "Nguchize a Zambi upi wami,", "Zambi, nguli hane kuli Yena", "Ngupwe mwe nyi We ndo kumiaka."]}, {"type": "verse", "num": 2, "lines": ["Tambula kupwa chami, Mwene,", "Ngulinge chize mutumina,", "Tambula liji liami, Zambi,", "Shimbu yeswe nguku halise."]}, {"type": "verse", "num": 3, "lines": ["Kanwa liami likapwe", "Liato kuhalisa Yena;", "Tambula upite wami, Zambi,", "Chau zangile nawa."]}, {"type": "verse", "num": 4, "lines": ["Tambula shimbu yami,", "Shimbu yeswe nguku Halise;", "Tambula mbunge yami", "Nguna kwehe yo yeswe."]}]}, {"numero": 100, "titulo": "MWESWE NYI WE", "blocos": [{"type": "verse", "num": 1, "lines": ["Ngunazange ngupwe a Chilamwina,", "Nguli nyi We, nguli;", "Ngufunge shimbi ja Yena", "Hano nyi mwilu."]}, {"type": "chorus", "lines": ["Mweswe", "Nyi We mweswe", "Chenacho nguna zange", "Mweswe nyi We mweswe", "Lienalio zango liami."]}, {"type": "verse", "num": 2, "lines": ["Yamu Chifuchi nyi che chimwe;", "Yesu wika Mwene;", "Nguhichike yeswe woma kha", "Ngumbate kulusu."]}, {"type": "verse", "num": 3, "lines": ["Nguhichike Chifuchi chino,", "Yesu twongu kwase!", "Nguna zange kupwa nyi Yena", "Ngunjile mwilu."]}]}, {"numero": 101, "titulo": "YESWE KULI KRISTU", "blocos": [{"type": "verse", "num": 1, "lines": ["Kunguna zange kupwa mwe wa Chilamwina;", "Kupulula ku yipi", "Nguna zange mwono."]}, {"type": "chorus", "lines": ["Ngukapwe mwe wa Kristu,", "Yeswe ngu mwehe yo;", "Yeswe ya Kristu, yeswe, yeswe", "Hanga ngumwehe yo."]}, {"type": "verse", "num": 2, "lines": ["Nguka lingile Kristu", "Nguhete kawashi,", "Ha sambukila nyi jita,", "Ngulinge milimo."]}, {"type": "verse", "num": 3, "lines": ["Nguka twame nyi Kristu,", "Ngwendangane Nenyi;", "Ku mwono nyi ku ufwe,", "Ndo kuheta mwilu."]}, {"type": "verse", "num": 4, "lines": ["A mwene, ngu tambule", "Chize chene nguli;", "Nguli hane hapwila,", "Nguli nyi we Mwene."]}]}, {"numero": 102, "titulo": "KULUSU LIAMI", "blocos": [{"type": "verse", "num": 1, "lines": ["Kulusu anguhele Kristu,", "Lilelu kuhiana zango;", "Yikola yatuchikimisa,", "Yichi kuthuchiza Mwene"]}, {"type": "chorus", "lines": ["Kulusu anguhele kumbata,", "Yikola yatuchikimisa,", "Yichi kusweka Yesu,", "Ngwende mu pangu Lienyi,", "Nguka kumbe ndo Mwilu."]}, {"type": "verse", "num": 2, "lines": ["Chifuchi cha lelesa Kristu,", "Mahungumiona athu a Yesu.", "Ha zango Lienyi nyi keke,", "Ngumbate lie kulusu."]}, {"type": "verse", "num": 3, "lines": ["Ngulinge upale wa Kristu,", "Shimbu yeswe nguli pundu;", "Ngwambujole chishima chipema", "Kuwaha nyi sambukila."]}]}, {"numero": 103, "titulo": "KULIHANA CHAMI", "blocos": [{"type": "verse", "num": 1, "lines": ["Kristu, Longeshi, nguna zange,", "Hanga ngulinge upale We:", "Ngwehe je tchachi jakukumba", "Ku lamba lieswe mulikeza."]}, {"type": "verse", "num": 2, "lines": ["Kristu, Longeshi, nguna zange,", "Hanga nguka tomese mwono;", "Ngukwase Kristu, Zambi yami,", "Kanda nguhichika jila ya Mwilu."]}, {"type": "verse", "num": 3, "lines": ["Kristu, Longeshi, nguna zange,", "Hanga ngukumbe shili yami;", "Ngutakamise kwe kujita,", "Hanga ngukumbe shimbu yeswe."]}]}, {"numero": 104, "titulo": "TANGWA LIA CHISEKE", "blocos": [{"type": "verse", "num": 1, "lines": ["Tangwa liacho! Cho kuwaha", "Kuli Mwene ulamwino;", "Sambukila hinayi wana", "Yitwame mu mbunge yami."]}, {"type": "chorus", "lines": ["Kuwaha ngunevu", "Ha tangwa nalumukine!", "Hapwila nguli nyi zango Lie,", "Ngujikize nyi sambukila,", "Kuwaha! Cho Chiseke!", "Chiseke chami nyi Yesu."]}, {"type": "verse", "num": 2, "lines": ["Lisambe, kama, mbunge yami,", "Hali Mwana –atwaha Zambi", "Mumu Yiye wathukula,", "Yatukonekena Mwilu."]}, {"type": "verse", "num": 3, "lines": ["Chilakenyo nguli nacho,", "Kumwono nguchihetese,", "Tangwa nyi tangwa ngumwimbile", "Uhaliso Zambi wahiana."]}]}, {"numero": 105, "titulo": "TWEYA UTUPAPACHISE", "blocos": [{"type": "verse", "num": 1, "lines": ["Two papachise,", "Nyi unene We,", "Se tuli ana Je,", "A Chilamwina!"]}, {"type": "chorus", "lines": ["A Mwene nyi Spiritu", "Two papachise,", "Tuna kufuliela;", "Tweya kawashi!"]}, {"type": "verse", "num": 2, "lines": ["Tuli athu-api,", "Etwe tunechi", "Ku shili yetu te", "Tu konekene."]}, {"type": "verse", "num": 3, "lines": ["Keke ya mwilu", "Two utwehe yo", "Cheseko chinene", "Zambi wahiana."]}, {"type": "verse", "num": 4, "lines": ["ngunevu liji", "Lie mumalilu", "Muli Yena Mwanami,", "Nakuzanga!"]}]}, {"numero": 106, "titulo": "SHIMA LIA MANYINGA", "blocos": [{"type": "verse", "num": 1, "lines": ["Namona shima lia manyinga", "Litoma lia miaka!", "Manyinga Yesu a mwangine", "Yafwa ha kulusu."]}, {"type": "chorus", "lines": ["Namona fuji lia manyinga", "Mungu njila mo ngutome;", "Nguna sakwila kuli Mwene!", "Manyinga Jenyi matomesa."]}, {"type": "verse", "num": 2, "lines": ["Kwalumuka achi chinene", "Chaheta um mbunge;", "Mwono ukulu wasala,", "Ku-uchi kupinda."]}, {"type": "verse", "num": 3, "lines": ["Ngwende mu pangu lia mwilu,", "Haku konekena;", "Mazalo Kristu makwaha", "Nyi kukusongwela."]}, {"type": "verse", "num": 4, "lines": ["Yalweza zango liahiana", "Yamwanga manyinga;", "Ku mungu kamuhalisa", "Ha kungu lamwina."]}]}, {"numero": 107, "titulo": "HEHI NYI YENA ZAMBI YAMI", "blocos": [{"type": "verse", "num": 1, "lines": ["Nguku ndame hehi,", "Zambi yami", "Chipwe kumisongo", "Kungu neza;", "Hanga ngukalembe;", "Ngwize haka mwihi,", "Ngwize haka mwihi,", "Zambi yami."]}, {"type": "verse", "num": 2, "lines": ["Nguna nyenganyana,", "Mwe mupuya,", "Sambukila nyi kuhwima,", "Muka ngwaha.", "Hanga nguka lembe;", "Ngwize haka mwihi,", "Ngwize haka mwihi zambi yami"]}, {"type": "verse", "num": 3, "lines": ["Miaso mungu kemba,", "Kuli Yena,", "Kunguna sakuila", "Ha zango Lie.", "Hanga nguka lembe;", "Ngwize haka mwihi,", "Ngwize haka mwihi zambi yami"]}]}, {"numero": 108, "titulo": "YESU KANASANYIKA", "blocos": [{"type": "verse", "num": 1, "lines": ["Chifuchi chino cha woma", "Kristu kanatusanyika,", "Kanechi tangwa nyi tangwa", "Akwashili Tweyenu!"]}, {"type": "verse", "num": 2, "lines": ["Kristu kana kukanjisa", "Kuwayila mahamba,", "Kanatwichi hanga tumwehe,", "Zango lize lipema."]}, {"type": "verse", "num": 3, "lines": ["Ha chiseke, ha chinyengo,", "Hamilimo nyi kuhwima,", "Hakutala nyi kuwaha,", "Tumulweze lie zango."]}, {"type": "verse", "num": 4, "lines": ["Mwene wami, chawana Che,", "Hanga ungu sanyike;", "Mbunge yami yiku zange", "Ngulinge milimo Ye."]}]}, {"numero": 109, "titulo": "NGULI WA KRISTU", "blocos": [{"type": "verse", "num": 1, "lines": ["Nguhichike yeswe yipi,", "Nguli wa mwe Kristu;", "Hanga nwivwe liji Lienyi,", "Nguli wa mwe Kristu."]}, {"type": "chorus", "lines": ["Yesu ngu kwimbulule,", "Chichi kunyenganyana,", "Kweswako nyi muzuwo.", "Nguli mwe wa Kristu."]}, {"type": "verse", "num": 2, "lines": ["Hana kumbu mukwa khole,", "Nguli mwe wa Kristu,", "Mangusweka mwe kanawa,", "Nguli mwe wa Kristu"]}, {"type": "verse", "num": 3, "lines": ["Chize hash indo mu-uhenya,", "Nguli mwe wa Kristu;", "Miaso mungu kemba hanga,", "Nguli mwe wa Kristu"]}, {"type": "verse", "num": 4, "lines": ["Mwilu mungu kamumona,", "Ngupwe mwe wa Kristu;", "Mungu kamuhalisa, mba", "Ngu kapwe nyi Wenyi."]}]}, {"numero": 110, "titulo": "AKWENU KANAMONO YESU MUKACHI KE?", "blocos": [{"type": "verse", "num": 1, "lines": ["Tuli hakamwihi nyi mwe Yesu,", "Kweswe mutuya ku mwono uno,", "Akwa Chifuchi matunyingika", "Nyi kulifwa cha Yesu?"]}, {"type": "chorus", "lines": ["Kana ngu mwena mwe Yesu?", "Kana kumwena mwe Yesu?", "Nyi zango ukwete", "Kuli mwe Chilamwina?", "Kana kumwena mwe Yesu?"]}, {"type": "verse", "num": 2, "lines": ["Zango tuli nalio ngwe lia mwilu,", "Akwa shili kanalaluka?", "Twakwatenu hanga twa chize mo,", "Hanga alilamwine?"]}, {"type": "verse", "num": 3, "lines": ["Ngwe mukanda makatu tangila,", "Ha yitanga yetu twakulinga,", "Yesu matambula nyi kwa zanga,", "Nyi manuvutwokela?"]}]}, {"numero": 111, "titulo": "SEMUKA KAMUCHALI", "blocos": [{"type": "verse", "num": 1, "lines": ["Ufuku phichi yeza kuli Yesu", "Hanga anyingike jila ya pangu;", "Mba Longeshi yamwambulwila", "Ngwenyi,", "Kusemuka ka-ali"]}, {"type": "chorus", "lines": ["Kusemuka ka-ali! Kusemuka ka-ali!", "Liji lia mwenemwene Yesu ngwenyi;", "Kusemuka ka-ali!"]}, {"type": "verse", "num": 2, "lines": ["Enu, ana ja hashi, yivwenu kuli", "Mwene", "Kananu sanyika nyi zango liahiana;", "Kujishi kumuhwa nyi kwamba ngwenyi;", "Kusemuka ka-ali!"]}, {"type": "verse", "num": 3, "lines": ["Nwazanga kuhwimina kuli Zambi", "Hanga nukanjile no hamuwika,", "Panjikenu kuma liji a Kristu,", "Kusemuka ka-ali!"]}]}, {"numero": 112, "titulo": "SHIMBU YA USANDU ULISELO YO", "blocos": [{"type": "verse", "num": 1, "lines": ["Ulisela shimbu ya kushimwinya,", "Pwako nyi Longeshi, hanga utange,", "Henda nyi athu Jenyi nyi kwakwasa,", "Uwahiso wa mwilu Zambi makwaha."]}, {"type": "verse", "num": 2, "lines": ["Shimbu yakutoma ulisela yo,", "Haze uli wika lemba nyi Kristu,", "Hulikila meso kuli mwe Zambi,", "Maka kusongwela ku thachi Jenyi."]}, {"type": "verse", "num": 3, "lines": ["Hapwila ye shimbu yakujikiza,", "Kweswe Longeshi maku tetekela;", "Chipwe nyi lamba umwononokena,", "Zambi hanga kechi kakuvulama."]}, {"type": "verse", "num": 4, "lines": ["Ufunga ye shimbu yino yipema,", "Kusula yeswayo jamina Zambi;", "Pwako mukwa keke nyi-akwenu", "Eswe.", "Ukaule mungano ja Chilamwina."]}]}, {"numero": 113, "titulo": "HIYAMI KO, ALIOZE KRISTU", "blocos": [{"type": "verse", "num": 1, "lines": ["Kanda nulemesa yami, ndo Kristu,", "Ami kha, mungu nulweza Kristu;", "Ami kha, nyi Yesu nguna yilingi,", "Ami kha, ndo Kristu nyi manyonga."]}, {"type": "verse", "num": 2, "lines": ["Ami kha, ndo Kristu mangukolesa,", "Ami kha, Kristu ngulembejeke,", "Ami kha, Yesu nguchize yiteli,", "Ami kha, Kristu, nguchize woma."]}, {"type": "verse", "num": 3, "lines": ["Yesu keshi kuhanjika nyi lwelia,", "Yesu, chichi kulinyenga nawa;", "Yesu, chichi kulengumuka nawa;", "Yesu kalingile ko upi kha."]}, {"type": "verse", "num": 4, "lines": ["Ami kha, Kristu, hana ngufwetela,", "Ami kha, Yesu mangwaha thachi;", "Yesu, nyi chimwe ndo ye Spiritu ye,", "Yesu, nyi chimwe uli wa miaka."]}]}, {"numero": 114, "titulo": "KRISTU MU MBUNGE YAMI", "blocos": [{"type": "verse", "num": 1, "lines": ["Mbunge yami hapwila yinalumuka,", "Se Kristu heza mu mbunge;", "Hinawana pangu lize nafupile;", "Se Kristu heza mu mbunge!"]}, {"type": "chorus", "lines": ["Se Kristu heza mumbunge, yami,", "Se Kristu heza mumbunge, yami,", "Cho kuwa chinji ngunevu mu", "Mbunge", "Se Kristu heza mumbunge;"]}, {"type": "verse", "num": 2, "lines": ["Chichi kwendangana nguhichike jila,", "Se Kristu heza mu mbunge;", "Shili yami yeswe yangu konekena,", "Se Kristu heza mu mbunge."]}, {"type": "verse", "num": 3, "lines": ["Kutalatala chami cha miaka yeswe,", "Se Kristu heza mumbunge;", "Kuze nawa chichi kanyenganyana", "Se Kristu heza mu mbunge."]}, {"type": "verse", "num": 4, "lines": ["Ndo kusongo lia kufwa nguna", "Mono pangu,", "Se Kristu mumbunge yami", "Tale hombo lilemu mulihenyama,", "Se Kristu heza mumbunge."]}, {"type": "verse", "num": 5, "lines": ["Limbo liacho mungukapwa shimbu", "Yeswe,", "Se Kristu mumbunge yami", "Mungu kawahilila hakunjila mo,", "Se Kristu heza mu mbunge."]}]}, {"numero": 115, "titulo": "NYI KULUSU MUNGUYA MWILU", "blocos": [{"type": "verse", "num": 1, "lines": ["Yesu hanazulula jila mwilu;", "Ku kushi nawa yikwo;", "Chichi te kanjila um malilu", "Nyi chakawile kulusu"]}, {"type": "chorus", "lines": ["Mungu kaya nyi Yesu,", "Mwilu ngukaye nyi Yesu,", "Kuwaha chami chiseke chinji;", "Mwilu Munguya nyi Yesu."]}, {"type": "verse", "num": 2, "lines": ["kumunguya mujila yakulusu", "Kwenda nyi kujikiza;", "Lie zango liami ngukalie ya mwilu", "Che chihinga chamwe Kristu."]}, {"type": "verse", "num": 3, "lines": ["Hinguna hichika majila api;", "Kwakaula nawa kha;", "Ngukaule Yesu nyi kulusu", "Mujila yakuya mwilu."]}]}, {"numero": 116, "titulo": "NGULI MWANA WA MWANANGANA", "blocos": [{"type": "verse", "num": 1, "lines": ["Nguli wa Mwene mwana wa", "Mwanangana,", "Mungu kapwa muzuwo Lienyi;", "Hingunevu lufuma muji wa mwilu,", "Mu katwama nyi Anenyi."]}, {"type": "chorus", "lines": ["Nguli wa mwane mwana wa", "Mwanangana,", "Aye kechi kangu vulama;", "Yiye mangulamwina nyi chawana", "Chenyi;", "Mungu kapwa mu uhenya Wenyi."]}, {"type": "verse", "num": 2, "lines": ["Nguli wa mwe Soma, zango linji", "Akwete,", "Sambukila Yenyi uhwimino,", "Ha uthu wenyi se hanangu", "Hindwisa,", "Shimbu yeswe mafunga Anenyi."]}, {"type": "verse", "num": 3, "lines": ["Nguli wa mwe Soma, kanatulakenya;", "Malamwina waze amu zanga;", "Mu Limbo lia Zambi muchitwamo", "Chenyi,", "Hamwe nyi akwa ulamwino."]}]}, {"numero": 117, "titulo": "KWENDA NYI KUTWAMA NYI YESU", "blocos": [{"type": "verse", "num": 1, "lines": ["Chinyengo nenda nacho chiseke kha,", "Musono nguli nyi chiseke chinji,", "Ngu hanjike nyi Mwene Zambi,", "Chamwenemwene nguli wa Yesu."]}, {"type": "chorus", "lines": ["Nguli wa Yesu, aleluya!", "Nguli wa Kristu, Mwene!", "Chazangile kuphianguka nawa,", "Ngwende ngutwame nyi Yesu!"]}, {"type": "verse", "num": 2, "lines": ["Napwile nyi kulinga shili yinji,", "Chifuchi changu mbilile mu mbongo;", "Hapwila nguli kajila wa mwilu,", "Hina pema mumu nguli wa Yesu!"]}, {"type": "verse", "num": 3, "lines": ["Mwono waluyinda, kanda ulila?", "Kuli Kristu hiwawana ulamwino;", "Chiseke cha miaka nyi ulamwino;", "Tweya, tweya kuli Kristu, kawashi!"]}]}, {"numero": 118, "titulo": "AMI HANO NGULI NGEJI", "blocos": [{"type": "verse", "num": 1, "lines": ["Nejile ngwe ngeji nyi kutwama", "Hano,", "Ku usoma wa mwilu nguli mwe", "Kanganda!", "Soma yami Yesu, wanutuma Liji", "Liji lia ukonekeno."]}, {"type": "chorus", "lines": ["Sango aji angutumine", "Yesu watufwilile;", "Wanenu nyi Yiye, che chiyulo Chenyi,", "Wanenu nawa nyi Zambi!"]}, {"type": "verse", "num": 2, "lines": ["Shimbi ya mwe Soma mukwa shili", "Mweswe", "Alikonyike kuli Chilamwina", "Mweswe mukwa shili kana lilakenya", "Kukonekena nyi zango."]}, {"type": "verse", "num": 3, "lines": ["Zuwo liami mwilu kulishi nyi woma;", "Waze malamwina maka wahilila!", "Makamona Zambi maka twama Nenyi", "Mu wanangana wa mwilu."]}]}, {"numero": 119, "titulo": "YESU NGUNA ZANGE", "blocos": [{"type": "verse", "num": 1, "lines": ["Nguna zange Yesu!", "Mwe Yena a Mwene!", "Nyi liji lia Yena", "Mungu huzuluka!"]}, {"type": "chorus", "lines": ["Mwe Chilamwina chami;", "Nguna kuzange chinji!", "Hanga ungu wahise;", "Nguna hono!"]}, {"type": "verse", "num": 2, "lines": ["Nguna zange Yesu!", "Ngulinunge Nyenyi!", "Shili nyi yizezo", "Kuyishi nyi thachi!"]}, {"type": "verse", "num": 3, "lines": ["Mu shimbi ya yena", "Tweya ungu longese", "Nguna zange kwivwa", "Zango Lie liahana."]}, {"type": "verse", "num": 4, "lines": ["Chilamwina chami", "Yena ha yizezo", "Ungu konekene", "Ngwehe ulamwino."]}]}, {"numero": 120, "titulo": "AMI NGUNA KUZANGE CHINJI!", "blocos": [{"type": "verse", "num": 1, "lines": ["A mwene nguna kuzange!", "Nguli mwe mukwa shili,", "Kwata kama kwoko liami,", "Ngusongwele nyi zango Lie."]}, {"type": "chorus", "lines": ["Haliapwa, chize haliapwila,", "Mwene ami nguna kwichi;", "Haliapwa, chize haliapwila,", "Ungufunge a Mwene."]}, {"type": "verse", "num": 2, "lines": ["Ungujike uzalo We", "Uzalo wami wapwi;", "Nguli mupi nguna lele", "Hanga ungwehe thachi."]}, {"type": "verse", "num": 3, "lines": ["Nguna jikijila Zambi;", "Nyi kha mungu limbuka;", "Mwene ngusongwele kama,", "Nguwendele mu pangu Lie."]}, {"type": "verse", "num": 4, "lines": ["Nyi kulutwe mungu wana,", "Luyinda nyi chiseke;", "Ngujamine kuli Yena,", "Hanga ungu songwele."]}]}, {"numero": 121, "titulo": "KULEMBEJEKA", "blocos": [{"type": "verse", "num": 1, "lines": ["Lihumikize a mbunge yami,", "Nyi kuhwimina kuli Zambi.", "Ha zango lienyi makangusweka,", "Nyi kuhwimina kuli Zambi"]}, {"type": "chorus", "lines": ["Uhwimino,", "Mwe mukhondo ya Zambi yami;", "Ngujikize,", "Nyi kuhwimina kuli Zambi."]}, {"type": "verse", "num": 2, "lines": ["Nguye kulutwe chiseke chinji", "Mungu hwimina kuli Zambi", "Ku thachi Jenyi mungu kakumba,", "Nyi kuhwimina kuli Zambi."]}, {"type": "verse", "num": 3, "lines": ["Nyi chimwe te munguvwila woma,", "Nyi kuhwimina kuli Zambi.", "Yiwape yeswe yukuli Mwene,", "Nyi kuhwimina kuli Zambi."]}, {"type": "verse", "num": 4, "lines": ["Nyi jita muyingujingilika,", "Mungu hwimina kuli Zambi.", "Kechi kangwecha mangu pulula,", "Nyi kuhwimina kuli Zambi."]}]}, {"numero": 122, "titulo": "CHAWANA CHIPEMA CHA MWILU", "blocos": [{"type": "verse", "num": 1, "lines": ["Ngunevu miaso ya mwilu…mwilu,", "Ye miaso ya kuwaha nyi…kwimba;", "Mayimba nyi chiseke chinji", "Vumbi! Chawana Chenyi."]}, {"type": "chorus", "lines": ["Sambukila", "Achi chawana cha mwilu!", "Kuwaha chiseke Chinji,", "Keke chawana cha Zambi!"]}, {"type": "verse", "num": 2, "lines": ["Kristu yafwa hakulusu…Yafwa,", "Mba yatu fwetela kongo…lietu,", "Kashika twa tambwile lume", "Sambukila ya Zambi."]}, {"type": "verse", "num": 3, "lines": ["Mwanangana wami Yesu…Yiye", "Se nguna wane keke Ye…yinji", "Nguna wane chiseke chinji", "Sambukila chawana cha Zambi!"]}, {"type": "verse", "num": 4, "lines": ["Kupwa hamwe nyi mwe Yesu…Yesu,", "Chiseke cha Yiye chinji…chinji,", "Mawahisa matanwa eswe", "Chawana cha Zambi yami."]}]}, {"numero": 123, "titulo": "MBUNGE YE MUSANBUKILA", "blocos": [{"type": "verse", "num": 1, "lines": ["Milima yinalayisa majila je,", "Kanda wivwa chinhengo halisa", "Zambi!", "Lelwa lia liakuneha lukhongolo,", "Muze sambukila muyisa mu mbunge."]}, {"type": "chorus", "lines": ["Mbunge yipwe nyi sambukila,", "Muka wana ye sambukila yahiana;", "Mbunge yipwe nyi ye sambukila,", "Kumukamona lelwa lia lukongolo."]}, {"type": "verse", "num": 2, "lines": ["Nyi mu mwono kulithachika nyi", "Lamba,", "Lamba lie leswe kumu kalivulama;", "Kumu kapwa nyi sambukila nyi zango."]}, {"type": "verse", "num": 3, "lines": ["Ufuku mu-uhwa kwilu hanga kuche;", "Lilu hilia temuka lamba hilihwa!", "Kutuchi katoka ndo mutukakumba!", "Yinyengo muyihwa kwize", "Sambukila."]}]}, {"numero": 124, "titulo": "NGUTWAME KU MOLU A KRISTU", "blocos": [{"type": "verse", "num": 1, "lines": ["Ngutwame ku molu –a Kristu", "Ngwivwe chize mangwamba!", "Ngupanjike liji Lienyi", "Sambukila mu mbunge;", "Nyi mungu tala kunyima,", "Muze nguli nyi Yesu,", "Shimbu yeswe ngulemese", "Chawana cha kulusu."]}, {"type": "verse", "num": 2, "lines": ["Ngutwame ku molu –a Kristu,", "Ngutambule uwahiso,", "Shili yami nguyitwale,", "Kuma ngukonekena;", "Ngutwame ku molu –a Kristu,", "Kuze mungu kalemba,", "Thachi jami kumujiza,", "Kuma ngwaha chawana!"]}, {"type": "verse", "num": 3, "lines": ["A Yesu ungu wahise,", "Kutala che cha Zango!", "Hanga chingupwile chashi", "Kukamona Huma Lie;", "Ngwhe manyonga apema", "Hanga ngupwe ngwe Yena!", "Nguchilweze kuli akwetu,", "Nguli Mwane wa pangu."]}]}, {"numero": 125, "titulo": "KULULAMA", "blocos": [{"type": "verse", "num": 1, "lines": ["Cheseko cha mwenemwene,", "Muka mona lamba,", "Mukapwa nyi sambukila", "Nyi kuli hana."]}, {"type": "chorus", "lines": ["Lihane ko,", "Mujila yipema,", "Saka chawana chahiana,", "Nyi kuli hana."]}, {"type": "verse", "num": 2, "lines": ["Muze yizezo muyiza,", "Yako ukalembe;", "Mukakumba hakusula,", "Nyi kuli hana."]}, {"type": "verse", "num": 3, "lines": ["Yeswe, yeswe yinahenge,", "Yeswe kuchikima;", "Thachi jinji mwopwa najo,", "Hakuli hana."]}, {"type": "verse", "num": 4, "lines": ["Nyi umwe makwamba yipi,", "Mukonekene yo;", "Lemba Yesu kumakwivwa,", "Nyi kuli hana."]}]}, {"numero": 126, "titulo": "CHIYULO CHINAHIANA", "blocos": [{"type": "verse", "num": 1, "lines": ["Achino Chifuchi chipi,", "Nyi ye jila yacho yipi,", "Mungu kwita Chilamwina:", "Utumbate, Chilamwina!"]}, {"type": "chorus", "lines": ["Hanga Yesu ungu mbate,", "Ku uhenya nyi lie zango,", "Mangu funga munguheta", "Ku limbo lize lia mwilu!"]}, {"type": "verse", "num": 2, "lines": ["Kuheshi zango he hano,", "Chiseke se kuchishiho;", "Miaka yeswe lamba wika", "Nguna zange kuli Yena."]}, {"type": "verse", "num": 3, "lines": ["Nguna zange nguka twame,", "Mumu hajina lia Yena!", "Hina wana ufulielo", "Chifuchi cha ulamwino."]}]}, {"numero": 127, "titulo": "KUTWAMA HATHO YA MEYA", "blocos": [{"type": "verse", "num": 1, "lines": ["Tu twame kumeya a mwono,", "Eno mavwelwoka,", "Nyi pwila mungu nwisa mwono", "Kwenako mungunwa."]}, {"type": "chorus", "lines": ["Ngutwame tulwiji a mwono,", "Tuluiji alemu a mwono", "Nyi pwila ngunwise mwono,", "Ngunwe pwila yinguhwe."]}, {"type": "verse", "num": 2, "lines": ["Kujina tuhu nyi milimo,", "Muhapwa kuhwima;", "Hano ha meya waze a mwono", "Mbunge yihuzuluke."]}, {"type": "verse", "num": 3, "lines": ["tweya uchivwe meya ja mwono", "Kristu maka kwaha;", "E meya a mwono wa miaka", "Mba pwila muyihwa."]}, {"type": "verse", "num": 4, "lines": ["Yoze manwa meya a mwono", "Masemuka chaha;", "Mwe mwilu, muli lwiji wa mwono", "Muwiza kunwa mo."]}]}, {"numero": 128, "titulo": "FULIELENU NYI KWONONOKA", "blocos": [{"type": "verse", "num": 1, "lines": ["Fulielenu Yesu nyi kufunga shimbi", "Kuwaha sambukila yinji!", "Nyi chiseke nyi ku funga yeswe", "Mamba,", "Miaka yeswe twivwe chiseke."]}, {"type": "chorus", "lines": ["Fulielenu yeswe manutuma;", "Washishika mononoka yize Kristu", "Mamba!"]}, {"type": "verse", "num": 2, "lines": ["Mukwa khole mamba, mukwa saki", "Awezele", "Kristu Yiye mahangulula;", "Chinyengo nyi yikola, chipwe saki", "Jinji", "Wafuliela kechi kwivwa woma"]}, {"type": "verse", "num": 3, "lines": ["Zango linapeme, kuli kata nyi", "Mwene", "Chinatela mukwa kufuliela;", "Huma Lienyi liato, zuka jila Jenyi,", "Yiye makakulembejeka."]}, {"type": "verse", "num": 4, "lines": ["Mwene twatongola, zango nyi", "Ufulielo,", "Mutu kukaula mungano Je", "Tufunge shimbi Je, Jina Lie", "Lifumane.", "Tuhetese chize wazanga"]}]}, {"numero": 129, "titulo": "YESU MANGUSONGWELA", "blocos": [{"type": "verse", "num": 1, "lines": ["Kuwaha Yesu, mangu twala!", "Liji lia kulembejeka!", "Chipwe ku lamba lieswalio,", "Kwoko Lienyi lingutwale."]}, {"type": "chorus", "lines": ["Chiseke Yesu mangutwala,", "Kwoko Lienyi lingu twale,", "Mungano jeswe angutwale", "Ngusonwele Mwene Yesu."]}, {"type": "verse", "num": 2, "lines": ["Chipwe mungu mona lamba,", "Mukachi ka mwongo nyi yikola,", "Ku meya apema hanji kalunga", "Mwene wami ngusongwele."]}, {"type": "verse", "num": 3, "lines": ["Ngu kwase kanda ngulinyenga,", "Ha cheswacho muchingwiza;", "Nyi kuwaha mungu twala;", "Kwoko Lie lize lia uthu."]}]}, {"numero": 130, "titulo": "YESU NYI WAMI KAKUNGOSONGWELA", "blocos": [{"type": "verse", "num": 1, "lines": ["Yesu kakungu songwela,", "Te mungu zanga chimwe?", "Naku khakhajana Kristu?", "Nyi kufuliela Zambi?", "Sambukila nguli nayo,", "Ya uwahililo We;", "Ku makangu funga chinji", "Nyi mbunge Ye ya uthu", "Ku makangu funga chinji", "Nyi mbunge Ye ya uthu."]}, {"type": "verse", "num": 2, "lines": ["Yesu kakungu songwela,", "Ngulongese kutwama,", "Ngwehe chawana nyi thachi,", "Hanga mba ngujikize.", "Chichi katoka nawa kha,", "Yiya mba mamana ko", "Kuli Zambi mwe Chisemi,", "Wazanga kufu kula?", "Mwe Zambi Tata wathachi", "Wazanga kungu kula?"]}, {"type": "verse", "num": 3, "lines": ["Yesu kakungu songwela,", "Nyi zango Lienyi liahiana!", "Mwono upema wa miaka", "Mwene ngu kwase kama.", "Tangwa Lie hilia kundama,", "Lia ulamwino wetu,", "Muze mukatu lamwina,", "Tuka likungulule", "Muze mukatu lamwina,", "Tuka likungulule."]}]}, {"numero": 131, "titulo": "NGUNAZANGE CHILAMWINA", "blocos": [{"type": "verse", "num": 1, "lines": ["Nguna zange Chilamwina,", "Kwenda ukawami kha", "Ngunazange apwe hehi,", "Nguhwimine kuli Yiye."]}, {"type": "chorus", "lines": ["Nguku…fuliele Mwene,", "Ngulembe…jeke kama,", "Jila ye …swayo Munguya,", "Woma nyi chinyengo kha."]}, {"type": "verse", "num": 2, "lines": ["Nguna zange Chilamwina,", "Ufulielo nahona.", "Liji Lie lingukolese,", "Muze mungu phaianguka."]}, {"type": "verse", "num": 3, "lines": ["Nguna zange Chilamwina,", "Mu-ungeji wa mwono.", "Ku chinyengo, nyi milimo,", "Ha lamba nyi chiseke."]}]}, {"numero": 132, "titulo": "NGUNAZANGE KWENDA NYI YENA MWENE", "blocos": [{"type": "verse", "num": 1, "lines": ["Zambi ngwende hamwe nyi Yena,", "Chize wendele nyi Yinoke.", "Ngu kwate kama nyi kwoko Lie,", "Mumu ami ngunalele.", "Chipwe mujila munala pwi", "Hindu nguye hamwe nyi Mwene."]}, {"type": "verse", "num": 2, "lines": ["Cha hashile kwenda a Zambi;", "Mukwa khole kanakenana,", "Se hana ngutela miheto;", "Hana ngujikinyina kweswe", "Akangutwale ngukatoke;", "Kuli Yena kuli ulamwino."]}, {"type": "verse", "num": 3, "lines": ["Ngwendele hamwe nyi Yesu", "Chiseke cha hashi nyi chimwe;", "Ami ngulitwike kulusu", "Munguya, nyi woma wakuhi.", "Ngukahete kuzuwo mwilu", "Ngukendele hamwe nyi Yesu."]}]}, {"numero": 133, "titulo": "MUZE MUKAPAKULA MUKANDA", "blocos": [{"type": "verse", "num": 1, "lines": ["Muze ngaji mapakula mukanda", "Chiseke mukevwa?", "Jina lie mulikapwa kuli Mwene", "Nyi kuli waze makatoka?"]}, {"type": "chorus", "lines": ["Nyi chiseke …mungukemba mwaso", "Mwaso wakuhalisa;", "Mumu jina liami halisoneka", "Mu Mukanda wa chilamwina."]}, {"type": "verse", "num": 2, "lines": ["Muze chitavwi muchishika", "Ngaji makatuka mwilu,", "Mungu kapwa nyi masepa Jenyi,", "Nyi hanji waze amunwa?"]}, {"type": "verse", "num": 3, "lines": ["Muze makasolola yitanga ye", "Mukevwa Yesu makamba;", "Au Tata hingu namulamwina", "Mukwa shili apwe nyi mwono"]}]}, {"numero": 134, "titulo": "KWESWE NYI YESU", "blocos": [{"type": "verse", "num": 1, "lines": ["Kweswe Hamwe nyi Yesu", "Kumunguya,", "Mwanagana wami nyi Chilamwina", "Chipwe kujita hindu kumunguya,", "Chipwe kuminda tuye nyi kulima."]}, {"type": "chorus", "lines": ["Kweswako, kweswako, Zambi", "Manwamba,", "Hehi nyi chilamwina mungwendela."]}, {"type": "verse", "num": 2, "lines": ["Kweswe nyi Chilamwina mungu", "Kapwa,", "Mbunge yami yinevu zango Lienyi,", "Se kuli Yiye kwe ngunajamina,", "Kweswe mangu songwela, cho kuwaha."]}, {"type": "verse", "num": 3, "lines": ["Kweswe kuze mangutwala Munguya;", "Ngukawane zuwo liami lipema.", "Kweswe Munguya, hindu mungukemba;", "Yena Mwene, chichi kwivwa woma kha."]}]}, {"numero": 135, "titulo": "UCHINYINO HA SHIMBU YALAMBA", "blocos": [{"type": "verse", "num": 1, "lines": ["Liwe lia miaka mwe Yesu,", "We uchinyino ha lamba;", "Kutuchi kwivwa woma kha,", "We uchinyino ha lamba."]}, {"type": "chorus", "lines": ["Yiye liwe lia uchinyino,", "Yiye che chiswamo chetu,", "Haluyinda kakusoloka,", "Ku yikola malamwina."]}, {"type": "verse", "num": 2, "lines": ["Mapulwila malamwina", "We uchinyino ha lamba", "Kutuchi kwivwa woma kha,", "We uchinyino ha lamba."]}, {"type": "verse", "num": 3, "lines": ["Nyi makimba matenuka,", "We uchinyino ha lamba;", "Upi ku-uchi kutwenyeka,", "We uchinyino ha lamba."]}, {"type": "verse", "num": 4, "lines": ["Yesu lie Liwe lia miaka,", "We uchinyino ha lamba;", "Mungu songwela ku pangu,", "We uchinyino ha lamba."]}]}, {"numero": 136, "titulo": "KUTALATALA CHAMI", "blocos": [{"type": "verse", "num": 1, "lines": ["Kuli mungu jikijila,", "Ndo kuchawana cha Yesu;", "Chitapo cha ulamwino,", "Mu manyinga a Chilamwina."]}, {"type": "chorus", "lines": ["Zango liami nyi ufulielo", "Nguna yise kuli Mwene;", "Nguna yise kuli Mwene."]}, {"type": "verse", "num": 2, "lines": ["Chahashile kumumona,", "Mu chawana chenyi ngupwe;", "Lamba lieswe mungu mona,", "Yiye mungu jikijila."]}, {"type": "verse", "num": 3, "lines": ["Hana ngulakenya khulu,", "Ha lamba makangusweka;", "Muze yizezo muyiza,", "Kristu Yiye ulamwino wami."]}]}, {"numero": 137, "titulo": "KULI YENA MWENE", "blocos": [{"type": "verse", "num": 1, "lines": ["Yena Zambi yami,", "Ngu hetule meso,", "Ngu panjike", "Kanda unguhichika", "Nguchize hamavu,", "Yena mukwa keke,", "Nyi lie zango!"]}, {"type": "verse", "num": 2, "lines": ["Pekama mu mbunge", "Thachi Je nyi hamu,", "Ndo kumiaka,", "Chipwe nyi zango Lie", "Chilamwina chami,", "Yena Mwanangana,", "Se wa miaka!"]}, {"type": "verse", "num": 3, "lines": ["We mwono wa hashi,", "Ku-ushi chiseke,", "Kuwaha kha;", "Chizako ufuku!", "Ngupemese kama", "Mbunge yami yipi", "Sambukila."]}]}, {"numero": 138, "titulo": "UCHINYINO", "blocos": [{"type": "verse", "num": 1, "lines": ["Ku yinyengo ya mwono uno,", "Nguka hwime ku milimo;", "Jina nguhu ngwehe thachi,", "Tweya ungufunge, Chilamwina."]}, {"type": "chorus", "lines": ["Ngu kwase kama …Ngusweke kama", "Upi kuchi kahetako", "Ngu kwase kama …Ngusweke ka;", "Uli Chilamwina chami."]}, {"type": "verse", "num": 2, "lines": ["Akwa khole manguvutwokela,", "Muze mazanga kunwenyeka;", "Angelo mangu jingilika", "Kechi kungwecha ngutoke."]}, {"type": "verse", "num": 3, "lines": ["Chipwe mungu mona lie lamba,", "Chichi kulimbuka nawa;", "Chipwe thachi himujinguhwa,", "Nyi Yesu mungu kakumba."]}, {"type": "verse", "num": 4, "lines": ["shimbu nguchili hano hashi", "Nyi mukwiza upi umwe,", "Kuli Yesu zango liahiana,", "Mafupa kungu hwimisa."]}]}, {"numero": 139, "titulo": "TALA KWILU", "blocos": [{"type": "verse", "num": 1, "lines": ["Nyi unevu chinyengo,", "mu mbunge yikola,", "tala kwilu nyi ufulielo", "zambi makukwasa."]}, {"type": "chorus", "lines": ["Shimbu yeswe!", "Tala nyi ufulielo kwilu,", "Kuze Yesu anatemwina!", "Tala kwilu ufuliele."]}, {"type": "verse", "num": 2, "lines": ["masepa makuchina,", "Muze mwopwa, ukawe,", "Tala kwilu nyi ufulielo,", "Yesu makuzanga"]}, {"type": "verse", "num": 3, "lines": ["Nyi musweka yikola", "Nyi umwe mayimona?", "Tala kwilu fuliela;", "Kumaku hindwisa"]}, {"type": "verse", "num": 4, "lines": ["Kanda ulihetamina", "Chinji munyenganyana;", "Tala nyi ufulielo kwilu,", "Fupa Kristu umumone."]}]}, {"numero": 140, "titulo": "MWANGELO WA MWENE", "blocos": [{"type": "verse", "num": 1, "lines": ["Mwangelo kaku jingilika", "Waze akumu fuliela,", "Mafunga mwalwa nyi ufuku", "Kuhwa kha!"]}, {"type": "chorus", "lines": ["Lelwa lia uhenya, lelwa lipema,", "Litu songwele mwilu!", "Lelwa lia uhenya, lelwa lipema,", "Litu songwele mwilu."]}, {"type": "verse", "num": 2, "lines": ["Matu chikimisa nyi yipi", "Se Mwene kakutufunga", "Makatusa mu maphulwa", "Kuwaha!"]}, {"type": "verse", "num": 3, "lines": ["Kweswe maya mutuya Nenyi", "Nyi kupalika ye phuya,", "Tukanjile mu kanana", "Mwe mwilu!"]}]}, {"numero": 141, "titulo": "KRISTU YIYE KASONGO", "blocos": [{"type": "verse", "num": 1, "lines": ["Kristu kuma kapwa kasongo ketu,", "Chipwe jita yiye mapwa kulutwe.", "Kechi kahichika tujita Twenyi!", "Eswe mutumukaula."]}, {"type": "chorus", "lines": ["Tuyenu kulutwe! Nyi mwe kasongo;", "Tuyenu kulutwe! Tukumbe yipi!", "Jikizenu, kanda tuhonga!", "Nyi Yesu kumutu kakumba."]}, {"type": "verse", "num": 2, "lines": ["Twashilenu jita pendelo lietu,", "Tuli thachike nyi akwa khole.", "Kasongo ketu makumba Chifuchi", "Tukaulenu Yesu."]}, {"type": "verse", "num": 3, "lines": ["Ha jita yathachi matulamwina,", "Mbunga yeswe kumuyi kemba miaso;", "Eswe mamba mwaso wa Mwanangana,", "Muze mutuheta ko."]}]}, {"numero": 142, "titulo": "KANDA ULIKALA", "blocos": [{"type": "verse", "num": 1, "lines": ["Kanda ulika milimo yihiana;", "Lilulieke wize.", "Ulinge upale we,", "Kanda ulelesa", "Ku liji lia Zambi.", "Kuli kwononona", "Makakwaha hano."]}, {"type": "chorus", "lines": ["tweya nyi …kanda ulikala!", "Tweya nyi …Lilulieke wize!", "Kanda ulikala Muhasa kumwivwa", "Mweswe maswilika.", "Kechi katambula."]}, {"type": "verse", "num": 2, "lines": ["Kanda ulikala,", "Zambi masanyika,", "Kanda ulelesa", "Milimo anakwehe.", "Wande ku-unahi,", "Akwa kucha akuhi?", "Akwo kevwile ko,", "Sanyikenu athu."]}, {"type": "verse", "num": 3, "lines": ["Kanda ulikala,", "Kanda uswilika,", "Nyi kha mukafulwa,", "Likolweze kwenda.", "Shimbu yacho ayi,", "Ngukwehe milimo,", "Kristu kanazange", "Hanga akuwahise."]}]}, {"numero": 143, "titulo": "SWALALE YA YESU", "blocos": [{"type": "verse", "num": 1, "lines": ["Nguli swalale wa Yesu,", "Mukweze wa Mwene?", "Mungu mbata lie kulusu,", "Nyi, kumona lamba?"]}, {"type": "verse", "num": 2, "lines": ["Alingile nyi ufulielo,", "Kanda nwivwa woma?", "Ngulimike hali Mwene?", "Nyi kupwa mwe nyi We."]}, {"type": "verse", "num": 3, "lines": ["Shishikenu shimbu yeswe!", "Kanda nupwa kunyima", "Yiya makaula Soma;", "Nyi chawana chenyi."]}]}, {"numero": 144, "titulo": "MILIMO YAMUKWA KRISTU", "blocos": [{"type": "verse", "num": 1, "lines": ["Tulingenu milimo ya Mwene Zambi,", "Tukaule Longeshi mujila mwilu;", "Nyi chiyulo chipema matwalumuna,", "Nyi kulinga nyi mana chize", "Matwamba!"]}, {"type": "chorus", "lines": ["Milimo, kawashi, kulingila Yesu,", "Ufulielo, kutala nyi kulemba,", "Ndo Mwene makahiluka."]}, {"type": "verse", "num": 2, "lines": ["Tulinge milimo, tukwase akwa zala;", "Tutwale kawashi kushima lia meya;", "Ku kulusu Lienyi lize lia uhenya,", "Yesu maka lamwina nyi chawana", "Che!"]}, {"type": "verse", "num": 3, "lines": ["Tulingilenu Kristu mwe Mwene", "Wethu,", "Makakumba wanangana wamilima;", "Yiye makapwa Munene shimbu yeswe,", "Wanangana mahana chawana", "Cheny!"]}, {"type": "verse", "num": 4, "lines": ["Tulinge milimo Zambi matukwasa,", "Chipangula cha uhenya makatwaha;", "Tuka hwime hamwe nyi akwa ufulielo,", "Yesu muka tulamwina chawana Che!"]}]}, {"numero": 145, "titulo": "MOKO KUMILIMO", "blocos": [{"type": "verse", "num": 1, "lines": ["moko ku milimo akweze,", "Tangwa linatoko;", "Tuyenu shimbu lino", "Tuli nyi mwono!", "Shimbu kuchili mwalwa,", "Tukilikitenu;", "Tenu ufuku uneza,", "Milimo yihwe."]}, {"type": "verse", "num": 2, "lines": ["Milimo makulwana,", "Shimbu kuli pangu;", "Tenu yino Ye shimbu", "Tulingile Yesu!", "Yenu nyi hamo lieswe", "Tuli lakenyenu;", "Ufuku ku uneza;", "Milimo yihwe."]}, {"type": "verse", "num": 3, "lines": ["Chipwe tushina kaji", "No alikolweze;", "Talenu shimbu kufwa", "Kanda chichiza!", "Tuyenu ku milimo,", "Tulinge nyi Kristu;", "Ufuku ku uneza,", "Hanga tuhwime."]}]}, {"numero": 146, "titulo": "AKWA KUCHA KULI ALI?", "blocos": [{"type": "verse", "num": 1, "lines": ["Kulihi ali akwa milimo,", "E mande kanahi eze akache?", "Milimo kawashi thachi jinji.", "Yiya una zange akayiche?"]}, {"type": "chorus", "lines": ["E akwa kucha, kuli ali?", "Hanga akazalise muwande?", "Yiya maliyula alihane", "Akahele mbuto yipema."]}, {"type": "verse", "num": 2, "lines": ["Mbuto yipi kuyina pihisa,", "Mbuto yipema kuyina lele.", "Akwa kucha yenu nyi washi,", "Tangwa linayi likolwezenu."]}, {"type": "verse", "num": 3, "lines": ["Ana zane eze ku milimo,", "Mavungu kanafupu ulamwino,", "Akwa milimo ambujolenu,", "Makonekena nyi zango Lienyi."]}]}, {"numero": 147, "titulo": "LONGESHI KANASANYIKA", "blocos": [{"type": "verse", "num": 1, "lines": ["Mba hakucha cha ye minda", "Muli mbuto yinahi!", "Mwene kanazange athu,", "Ngunevu kusanyika!"]}, {"type": "chorus", "lines": ["Ngunevu kusanyika,", "Ngunevu kusanyika!", "Mwene kanazange athu,", "Ngunevu kusanyika!"]}, {"type": "verse", "num": 2, "lines": ["Kristu sepa lia akwa shili,", "Kanafuphu phanga au;", "Kanazange ngufupe akwetu,", "Ngunevu kusanyika!"]}, {"type": "verse", "num": 3, "lines": ["Nguli hane kumilimo,", "Nguye kweswe mangwamba;", "Akwa milimo akehe,", "Ngunevu kusanyika!"]}, {"type": "verse", "num": 4, "lines": ["Wande una twaminyina;", "Longeshi se kanechi?", "Akweze, makulwana, tweyenu,", "Ngunevu kusanyika!"]}]}, {"numero": 148, "titulo": "YAMI UNO NGUTUME", "blocos": [{"type": "verse", "num": 1, "lines": ["Yivenu liji lino ngwo;", "Yiya mamu lingila?", "Tenu mbuto hiyinahi", "Tuyenu tuka yiche", "Se Mwene knatutumu!", "Kuma katwononona", "Mba yiya unata ngwenyi:", "Chipwe yami tumenu?"]}, {"type": "verse", "num": 2, "lines": ["Nyi kweka kunusoloko,", "Kwambujola sango ali", "Awo yenu kkuli anyembo", "Anatambe kwakwasa", "Nyi hi uli mwangelo ko", "Yako ukambujole,", "Hanga walweze zango ali", "Lize lia Chilamwina"]}, {"type": "verse", "num": 3, "lines": ["Nyi kachi kusolo kupwa", "Kafunga ka Siyono", "Nyi kulweza athu eswe", "Jila ya ulamwino", "Uli kolweze kulemba,", "Munehene yawana;", "Pwako mukwa kushishika", "Wononokena shimbi."]}, {"type": "verse", "num": 4, "lines": ["Muze eswe mutu kafwa", "Mutukaku tambieka;", "Nyi umwe kanda alinyenga;", "Chishi nyi chakuhana.", "Ukilikite nyi thachi", "Moko je kumilimo,", "Kumbulula mwe haliapwa!", "Mwene ngutume yami."]}]}, {"numero": 149, "titulo": "HOLENU", "blocos": [{"type": "verse", "num": 1, "lines": ["Mwene! Kalunga hafuza,", "Etu kole nyi woma;", "Tala yo milima kwilu,", "Chilamwina muthulo!", "Tukwase kutuna toko?", "Kuchi unapombo,", "Jina tuhu nyi kupuka", "Te himutu shimbama."]}, {"type": "chorus", "lines": ["Makimba mangwononokena:", "Holenu!", "Chipwe kulunga matenuka", "Chipwe we woma unahiana,", "Meya kechi kushimbamisa,", "Wato unendela Mwene wa Mwilu,", "Yeswe muyi ngwononokena", "Ho…lenu!", "Holenu!", "Shimbu yeswe nakunu lamwina!", "Ho…lenu!"]}, {"type": "verse", "num": 2, "lines": ["Mwene chinyengo ngunevu", "Kungu nambe kutoka;", "Mbunge yinalipikala,", "Tweya ungupulule,", "Yipi kuyina ngufuku;", "Ngu chize kama yo,", "Nguna toko, nguna toko,", "Ngu kwase kama Mwene!"]}, {"type": "verse", "num": 3, "lines": ["Mwene kalunga hahola,", "Sambukila hiyeza;", "Mba himungu sehejela,", "Chipwe woma nawa kha,", "Ngu twame hamwe nyi Mwene!", "Wa malilu nyi hashi,", "Chocho mungu kazauka,", "Nguka hete muzuzu."]}]}, {"numero": 150, "titulo": "KWESWE MANGUTUMA MUNGUYA", "blocos": [{"type": "verse", "num": 1, "lines": ["Kweswe mangutuma Yesu", "Nguye ngwononoke;", "Chipwe kusuku nyi usoko,", "China ngutambe kuya,", "Nyi mangu sanyika nyi zango", "Mangu songwela kanawa,", "Mungu kamba ngwami Mwene wami;", "Kweswe mamba Munguya."]}, {"type": "chorus", "lines": ["Kweswe maba Mwene nguye,", "Chipwe te ku milundu", "Ngwambujole yeswe mamba Mwene;", "Nguye ngumu lingile."]}, {"type": "verse", "num": 2, "lines": ["Kazanga nwambujole sango,", "Lipema kuli ahu eswe,", "Ana zange kuli lamwina,", "Yiye matu lamwina,", "Nyi te Mwene mangu songwela,", "Kweswe Aye mangutuma,", "Ami chichi ka hola kama ko kha", "Ngu kambujole sango."]}, {"type": "verse", "num": 3, "lines": ["Mande ja Mwene eswe hanahi,", "Changu tamba kuya nyi kwacha,", "Kweswako kuze kuli milimo,", "Koko changu tamba kuya;", "Ngu na jikijila Chilamwina,", "Zango lienyi nguna livu,", "Nguna zange kulingila Mwene", "Nguka linge upale."]}]}, {"numero": 151, "titulo": "YAKO UKASAKE", "blocos": [{"type": "verse", "num": 1, "lines": ["Kafuga kana tambieka,", "Makojoloka mupuya,", "Mafupa ana maphanga,", "Kana zange kwalamwina."]}, {"type": "chorus", "lines": ["Anehe!Anehe!", "Mapanga jami anehe!", "Anehe!Anehe!", "Nguna zange nguawahise."]}, {"type": "verse", "num": 2, "lines": ["Yiya kasolo kukwasa,", "Kusaka ana mapanga,", "A katwale kuli yesu,", "Ku meya a mwono nyi pangu."]}, {"type": "verse", "num": 3, "lines": ["Lamba liahiana mupuya,", "Mumatapalo wo mafwa,", "Maphanga jami anehe,", "Nguna zange kwawahisa."]}]}, {"numero": 152, "titulo": "YENU AKWEZE JENYI", "blocos": [{"type": "verse", "num": 1, "lines": ["Kristu Mwanangana, ya waze alelu", "Kanazange kuhana kuli eswe,", "Enwe akweze yenu nyi kawashi,", "Njisenu waze nwalakenyanga."]}, {"type": "chorus", "lines": ["Yenu akweze, Jenyi tambukenu ko!", "Kristu maka kuchisa akwa zala!"]}, {"type": "verse", "num": 2, "lines": ["O chipwe te kanuzangile, yenu,", "Nuka lakenye nyi zango lienu!", "Pwenu nyi hamu chipue te manwamba,", "Yenu nyi zango nuka lakenye."]}, {"type": "verse", "num": 3, "lines": ["Kristu kananutumu mumajila,", "Nehenu yilema tupuputa,", "Yenu akweze Jenyi tambukenu ko!", "Kana zange eswe tukalie ko."]}]}, {"numero": 153, "titulo": "TULAMWINENU UMUWIKA UMUWIKA", "blocos": [{"type": "verse", "num": 1, "lines": ["Nyi tuna zange yesu", "Tufupe anatoko,", "Tuyenu nyi lie zango,", "Nyi kulakenya umwe."]}, {"type": "chorus", "lines": ["Tulamwine waze ali", "He hakamwihi nyi yetu", "Nyi lie zango lienyi", "Tumufulielenu", "Ndo ku usulilo,", "Tulamwine umwe umwe,", "Kanda tuvulama umwe,", "Akwa ufulielo ambujole", "Hanga alikonyekene."]}, {"type": "verse", "num": 2, "lines": ["anji analungajala", "Hakamwihi nyi yetu", "Kanyingikine yesu", "Ngwo yiye chilamwina."]}, {"type": "verse", "num": 3, "lines": ["tuye tuka hanjike", "Nyi masepa a yesu", "Shimbu kanda a chifwa", "Aka tambule pangu."]}, {"type": "verse", "num": 4, "lines": ["Lingenu twatwalile", "Maliji akwa shili", "Hanga mba tukeseke", "Chiseke chamwe Mwene."]}]}, {"numero": 154, "titulo": "KALAYI SHIKA CHITAVWI", "blocos": [{"type": "verse", "num": 1, "lines": ["Kalayi shikila kweswe", "Chitavwi cha ulamwino!", "Mweswe yoze malinyonga", "Maka tambula fweto."]}, {"type": "chorus", "lines": ["Kuyifuchi yeswe achivwe", "Mu membo nyi kalunga,", "We mutambi wa maliji", "Akulamwina athu."]}, {"type": "verse", "num": 2, "lines": ["Kushikila kwe kumilundu", "Mumi hwahwa woma kha!", "Mu mathungu ambujola", "Sango ja Mwene wethu."]}, {"type": "verse", "num": 3, "lines": ["Shikila mu matapalo", "Musesa lia majila", "Zambi meta akwashili", "Ahinge ulamwino."]}, {"type": "verse", "num": 4, "lines": ["Ambujola Sango jaha,", "Aye kuchiwanyino", "Eswe ali nyi chinyengo", "Tweyenu eswe kuno."]}]}, {"numero": 155, "titulo": "LAMWINA HA SHIMBU", "blocos": [{"type": "verse", "num": 1, "lines": ["Lamwina ha shimbu!Yena ndumbwami!", "Waze anahephuka nyi yizezo", "Tala chize anapu keshi thachi!", "Tweya walamwine kuluhinda wo."]}, {"type": "chorus", "lines": ["Lamwina ha shimbu! Lamwina ha shimbu!", "Nyi kawashi tweya walamwine", "Lamwina ha shimbu! Lamwina ha shimbu!", "Tweya walamwine."]}, {"type": "verse", "num": 2, "lines": ["Lamwina ha shimbu! Talako ndumbwe", "Muze ali muluchisa nyi lamba?", "Tununu twa akwa khole anafupu", "Kanjisa mwono wenyi muluyinda,"]}, {"type": "verse", "num": 3, "lines": ["Lamwina ha shimbu! Lihane mweswe", "Mbata maliji a Zambi, aulamwino,", "Muli Kristu, Longeshi, tulimike", "Shimbu yinapalika, two ukwase."]}, {"type": "verse", "num": 4, "lines": ["Hapwila Chifuchi muchika sula", "Ali mumilima kumaka nonga", "Lamwina ha shimbu! Temwina pangu", "Pangu lia ulamwino wa miaka yeswe!"]}]}, {"numero": 156, "titulo": "MUSONO KWASA UMWE", "blocos": [{"type": "verse", "num": 1, "lines": ["Talatala hakamwihi uli", "Musono kwasa umwe!", "Yoze walisulangana nenyi", "Kwasa kama umwe!"]}, {"type": "chorus", "lines": ["Musono kwa ko umwe, umwe", "Mulingile yipema, yize yipema", "Hichika luvundo, solola chiseke", "Musono kwasa ko umwe!"]}, {"type": "verse", "num": 2, "lines": ["Anji afunga maliji a zango", "Kwasa kama umwe!", "Chipwe te che chawana chikehe", "Kwasa kama umwe!"]}, {"type": "verse", "num": 3, "lines": ["Amwe yiteli yo yinaleme", "Musono kwasa umwe", "Malimbuka masala nyi lamba", "Kwasa kama umwe!"]}, {"type": "verse", "num": 4, "lines": ["Mu mwono uno anji jinahu", "Kwasa kama umwe!", "Anji anafupu ulamwino", "Kwasa kama umwe!"]}]}, {"numero": 157, "titulo": "MATHONGONOSHI AHENYAMA", "blocos": [{"type": "verse", "num": 1, "lines": ["Chiseke nakwivwa hakunyonga mwilu", "Mungu kaya hakuhwa jita", "Muze mungu kaheta kuli mwe Yesu", "Ngukapwe nyi mathongonoshi?"]}, {"type": "chorus", "lines": ["Chipangula thongonoshi makangwaha", "Tangwa kuchili katemuka nawa", "Zambi mangu twala ku-usoma wamwilu", "Ha chipangula thongonoshi!"]}, {"type": "verse", "num": 2, "lines": ["Ha ulemu wa Yesu ngulembe ngukumbe", "Nguka songwele athu mwilu", "Chipangula muchika henyama", "Ha usulilo changutamba kupwako"]}, {"type": "verse", "num": 3, "lines": ["Chiseke mutukevwa hakumumona", "Ku molu Jenyi mutuhalisa", "Chihunda cha mwilu mungu kawahilila", "Chipangula cha mathongonoshi?"]}]}, {"numero": 158, "titulo": "YESWE AHANO KUYISHI KUSHIMBULA", "blocos": [{"type": "verse", "num": 1, "lines": ["Yeswe hano kuyishi chihela", "Nyi umwe makatwama hano", "Hindu mutu wahilila", "Mutuka twama nyi Zambi", "Mutuka twama nyi Zambi."]}, {"type": "verse", "num": 2, "lines": ["Yeswe hano kuyishi chihena", "Tunafupu mwono wa mwilu", "Muze mutuka hinduka", "Mu Yelusaleme yaha", "Mu Yelusaleme yaha."]}, {"type": "verse", "num": 3, "lines": ["Cho chiseke zuwo lia zango!", "Ngeji makawahilila", "Nyi te maphulwa nguli no!", "Kachi te mungu humuka", "Kachi te hinahumuka."]}, {"type": "verse", "num": 4, "lines": ["Chazangile kulinyenga", "Zambi matambwisa shimbu", "Shimbu-ami ngunamuzange", "Mwilu munguka hwimina", "Mwilu munguka hwimina."]}]}, {"numero": 159, "titulo": "SWANA YA WANANGANA", "blocos": [{"type": "verse", "num": 1, "lines": ["Yena Swana ya usoma wa mwilu", "Kanda unongwoka hakamwihi?", "Hinduka kawashi ukwate kumata", "Tala hanga ukahase kukumba."]}, {"type": "verse", "num": 2, "lines": ["A Swana kanda ukokoloka", "Mumu kuwa zangile kuhetesa?", "Hinduka washi sandungi heza!", "Tala Chifuchi himuchisula!"]}, {"type": "verse", "num": 3, "lines": ["Mianangana kanalulieka jita", "Kulilemieka muchika sula ko", "Panjika lundhunjila wajiminyau!", "Mwana wa Usoma, kanda upomba nawa!"]}, {"type": "verse", "num": 4, "lines": ["Kanda ulaluka nyi chiseke cha hashi", "Mumu nyi kawashi kumu chihwa", "Pathula malenge anakukase", "Zombokela kuli Kristu, akukwase!"]}, {"type": "verse", "num": 5, "lines": ["Mufuliele ukawane uhenya", "Hethula mutwe, pwako nyi ufulielo!", "Ku chivumbuko hichawa khulu", "Mwana wa Soma kololoka kwimba!"]}]}, {"numero": 160, "titulo": "CHIHUNDA CHA UHENYA", "blocos": [{"type": "verse", "num": 1, "lines": ["E ana ja Siyono,", "Lemesenu Yesu;", "Halisenu mwimbilenu,", "Halisenu mwimbilenu,", "Fungenu je shimbi,", "Fungenu je shimbi"]}, {"type": "chorus", "lines": ["Siyono nyi yethu, limbo lilemu lia uhenya", "Chochene Chifuchi cha akwa", "Ufulielo wa Kristu Yesu"]}, {"type": "verse", "num": 2, "lines": ["Waze ali muchifuchi", "Kahalishile Zambi", "Welo enu ana ja Zambi", "Welo enu ana ja Zambi", "Halisenu Mwene", "Halisenu Mwene"]}, {"type": "verse", "num": 3, "lines": ["Mulundu wa Siyono", "Mukwiza pangu linji", "Mutuzala nyi chiseke", "Mutuzala nyi chiseke", "Chiseke cha hashi", "Chiseke cha hashi"]}, {"type": "verse", "num": 4, "lines": ["Eze amu lemese", "Waze ana jenyi", "Katukenu nukafupe", "Katukenu nukafupe", "Limbo lia Siyono", "Limbo lia Siyono"]}]}, {"numero": 161, "titulo": "NGUNANYINGIKA CHILAMWINA KWALI", "blocos": [{"type": "verse", "num": 1, "lines": ["Chilamwina kwali nyi mwono", "Aye wakumbile kufwa", "Hanayi mwilu chilamwina", "Yatu lakenya ulamwino"]}, {"type": "chorus", "lines": ["Hashi muhaka njindwoka", "Chishi kalindujoka ho", "Kumungu kaya nyi Longeshi", "Kuzuwo lia Tata mwilu", "Mungu katwama nyi Longeshi", "Maha Tata ndo ku miaka."]}, {"type": "verse", "num": 2, "lines": ["Nguna fuliela Chilamwina", "Yangu konekena shili", "Lamba linji angu mwenene", "Manyinga yangutusula"]}, {"type": "verse", "num": 3, "lines": ["Nguna komoka zango liacho", "Yesu akwate nyi yami", "Hakulamwina mukwa shili", "Yamufwila ha mutondo"]}, {"type": "verse", "num": 4, "lines": ["Yesu kumeza haliapwila", "Atambule athu Jenyi", "Akatwale limbo lipema", "Mahinga no ndo kumiaka."]}]}, {"numero": 162, "titulo": "ZUWO LIA MIAKA YESWE", "blocos": [{"type": "verse", "num": 1, "lines": ["Akwethu! Embenu miaso mu ungeji uno", "Hapwila muthuya kuzuwo!", "Mu uka henyama ulamwino wethu", "Hapwila muthuya kuzuwo."]}, {"type": "chorus", "lines": ["Hapwila lume!", "Hapwila lume!", "Mutukapwa kuzuwo", "Muze muthu hichika", "Chifuchi chino", "Ethu mutukaya kuzuwo."]}, {"type": "verse", "num": 2, "lines": ["Tulingenu chize chili hakwoko liethu", "Hapwila muthuya kuzuwo", "Tangwa nyi tangwa, Zambi mathulamwina", "Hapwila muthuya kuzuwo."]}, {"type": "verse", "num": 3, "lines": ["Tukwasenu waze anahono thachi", "Hapwila muthuya kuzuwo!", "Cheseko chethu cheche uhindukilo", "Hapwila muthuya kuzuwo!"]}, {"type": "verse", "num": 4, "lines": ["Kuli kuhwima, nyi kupuluka upi", "Hapwila muthuya kuzuwo!", "Misongo kulila kuchishiko nawa", "Hapwila muthuya kuzuwo!"]}]}, {"numero": 163, "titulo": "HAKAMWIHI NYI ZUWO", "blocos": [{"type": "verse", "num": 1, "lines": ["Kunyima lia milundu limbo lia mwilu", "Limbo lize lipema tunatale", "Jathuwa nyi kukanduka nyi kwenda", "Tatuyenu kanda tunyenganyana."]}, {"type": "chorus", "lines": ["Hehi nyi zuwo! Hehi nyi zuwo!", "Tala lie pangu linatulahula!", "Lie pangu lia uwahiso lili tho", "Mutu kalimwena kumeso a Yesu", "Mwe mupangu Lienyi hehi nyi Yiye", "Hakamwihi nyi zuwo."]}, {"type": "verse", "num": 2, "lines": ["Maprofeta kunima hana chambe ngwo", "Limbo lize lia ulu yahenyama!", "Kuze tuna mono lie pangu linji", "Nyi yipanga nyi mazuwo auhenya."]}, {"type": "verse", "num": 3, "lines": ["Limbo liacho kumumu kanjila wika", "Waze anafungu je shimbi Jenyi", "Nyi makanwa jethu kumuthu kemba", "Miaso yipema kuli mwanangana."]}, {"type": "verse", "num": 4, "lines": ["Tusendo twami nyi mandumbu thuyenu", "Chifuchi chize kuchishi luyinda", "Fuliela ku sango lia Yehovwa", "Aye makanu tambula nyi zango."]}]}, {"numero": 164, "titulo": "WANDE UPEMA WA ENDENE", "blocos": [{"type": "verse", "num": 1, "lines": ["Wande upema wa-Endene", "Wazango nyi pangu!", "Chiseke kuli akwa yinyengo", "Cho chanambe Yesu."]}, {"type": "chorus", "lines": ["Wande upema wa-Endene", "Mbala ya –akwa chiseke!", "Muze mungwivwa usona", "Chifuchi chami…Chocho!"]}, {"type": "verse", "num": 2, "lines": ["Hapwila kuzanga chethu", "Makachihetesa", "Kutuchi kevwa woma", "Yinyengo nyi lamba."]}, {"type": "verse", "num": 3, "lines": ["Muchitwamo cha mwilu", "Mwe muthu kembila", "Miaso yakusehejela", "Ya ukonekeno!"]}]}, {"numero": 165, "titulo": "CHIFUCHI CHIPEMA CHA ZANGO", "blocos": [{"type": "verse", "num": 1, "lines": ["Nguye Chifuchi cha mwilu", "Nyi kuwaha chinji nguye", "Ngufupe chihela chipema", "Chize munguka hwimina."]}, {"type": "chorus", "lines": ["Che Chifuchi chinahiana", "Chize akuzanga Mwene", "Musali lia mwe kalunga", "Yoze munguka zauka", "Ku ngenge yaulu ya miaka", "Ya mwilu yize yipema"]}, {"type": "verse", "num": 2, "lines": ["Mnguya hamwe nyi Mwene", "Ku upi makangu funga", "Mbunge yami to nyi zango", "Ngufuliele ngulamwine."]}, {"type": "verse", "num": 3, "lines": ["Chifuchi chinenene mwilu", "Makembila mo ye miaso", "Mbunga yize muyikakumba", "Miaso yize yaulamwino."]}]}, {"numero": 166, "titulo": "AKO KUKUSHI UFUKU", "blocos": [{"type": "verse", "num": 1, "lines": ["Chifuchi cha yalume", "Kanana wa mwilu", "Tuna chitwaminyina", "Kukushi ufuku."]}, {"type": "chorus", "lines": ["Zambi ami makangusa", "Mwono ushi yikola", "Kwalula matangwa kha", "Kukushi ufuku"]}, {"type": "verse", "num": 2, "lines": ["Yipakha yo yalawe", "Kanana wa mwilu", "Ufuku ku ushiko", "Yikolo ya ulu."]}, {"type": "verse", "num": 3, "lines": ["Yikolo yo yawashi", "Kanana wa mwilu", "Kuli lwiji wa mwono", "Kukushi ufuku"]}, {"type": "verse", "num": 4, "lines": ["Kechi kazanga tangwa", "Kanana wa mwilu", "Mwono wakuli Yesu", "Kukushi ufuku."]}]}, {"numero": 167, "titulo": "SHIMBU HA SHIMBU", "blocos": [{"type": "verse", "num": 1, "lines": ["Kristu hatukula hakulusu", "Nguli muwanangana wa pangu", "Nguzale nyi chawana cha Yesu", "Shimbu yeswe, Mwene masongwela."]}, {"type": "chorus", "lines": ["Shimbu yeswe Mwene masongwela", "Shimbu yeswe mangwaha chawana", "Huma lienyi, muli ngwaha thachi", "Shimbu yeswe nguli nyi Mwene"]}, {"type": "verse", "num": 2, "lines": ["Hamwe nyi Kristu mutwasa jita", "Ngu chinde shili nyi mwe luchisa", "Nguzundule pendelo lia Mwene", "Shimbu yeswe ngupwe chitakame."]}, {"type": "verse", "num": 3, "lines": ["Hamwe nyi Kristu kutulamwina", "Ngweseke hanga angulamwine", "Hanga avulamine akwa chinyengo", "Shimbu yeswe mangukonekena."]}, {"type": "verse", "num": 4, "lines": ["Ku luyinda wami mangukwasa", "Kuli satana mangupulula", "Shimbu yeswe kweswe mungwendela", "Kristu longeshi kumangu funga."]}]}, {"numero": 168, "titulo": "JINA LIAMI LIOLIO?", "blocos": [{"type": "verse", "num": 1, "lines": ["Upite wahashi se wamokomoko", "Kumunguya kuze se chichi kafwa nawa", "We mukanda wa mwono wa usonekene", "Ngwambulwile longeshi, jina liami liolio?"]}, {"type": "chorus", "lines": ["Jina liami mwilu Huna ngosoneka?", "Mumukanda wa mwono Huna ngosoneka?"]}, {"type": "verse", "num": 2, "lines": ["Shili yami yangwoka ngwe masekeseke", "Mba Yesu yasolola zango hali yami", "Yeza angulamwine yamwanga manyinga", "Yangu lakenya Yuma yaku miaka yeswe."]}, {"type": "verse", "num": 3, "lines": ["Chihunda chahiana chitoma nyi pangu", "Limbo lia-akwa usandu afuliela Yesu", "Mumukanjila wika, akwa kushishika", "Ali nyi majina jo kuli chilamwina."]}]}, {"numero": 169, "titulo": "USOPESO", "blocos": [{"type": "verse", "num": 1, "lines": ["Ngaji hana pakula mikanda", "Nyi yetu mutukapwa ho", "Ha usopeso uze wa mwilu", "Yitanga muyi-kasoloka?"]}, {"type": "chorus", "lines": ["Nyi yetu mutu kapwa ko?", "Uchela uka mu-ukapwa ko?", "Kutoka tuna twaminyina", "Nyi makatukonekena?"]}, {"type": "verse", "num": 2, "lines": ["Usopeso utangu kuli afu", "Mba tuka suleko yethu", "Nyi ye yitanga yethu yeswe", "Koko muyika solokela."]}, {"type": "verse", "num": 3, "lines": ["Yiya mba makapwa ha usopeso?", "Akamone shili yethu?", "Makayimana che kuyiyula", "Kukuchi kapwa keke nawa."]}]}, {"numero": 170, "titulo": "HANAKU PEZALISA YI-UHONA", "blocos": [{"type": "verse", "num": 1, "lines": ["Shinginyeka milonga yetu", "Ngaji mayisopa", "Tuka tome ngwe ulu to", "Nyi ulu yize yipi."]}, {"type": "chorus", "lines": ["Ku chipezaliso cha Mwene", "Hakupezala", "Ku liji lia Mwene wethu", "Ku unahono."]}, {"type": "verse", "num": 2, "lines": ["kumutu kevwa maliji", "Ngwo mukweze mupema?", "Nyi makatuhisa nawa", "Ngwo uli muthu mupi?"]}, {"type": "verse", "num": 3, "lines": ["Tupanjikenu Spiritu", "Kanda tukokoloka", "Shimbu kanda nwivwa liji", "Haku twenyeka chethu!"]}]}, {"numero": 171, "titulo": "YAKO YENA? NGUYE YAMI?", "blocos": [{"type": "verse", "num": 1, "lines": ["Yiya maya nyi Mwene Yesu", "Muze mwilu? Muze mwilu?", "Yiya makapwa nyi chawana?", "Yako? Nguye?", "Yako? Nguye?", "Yiya makeseka lie zango,", "Kusuku chinyengo nyi yikola", "Hamwe nyi Kristu Chilamwina?", "Yako? Nguye?", "Yako? Nguye?"]}, {"type": "verse", "num": 2, "lines": ["Muka hichika lie kulusu", "Muze mwilu? Muze mwilu?", "Ukatambule chipangula", "Yako? Nguye?", "Yako? Nguye?", "Yako Yesu ukamumone,", "Yako ukevwe liji Lienyi,", "Nyi chiseke chahiana mwilu,", "Yako? Nguye?", "Yako? Nguye?"]}, {"type": "verse", "num": 3, "lines": ["Yiya makanjila mokomoko", "Muze mwilu?Muze mwilu?", "Mamba ngwo muhela wakuhi?", "Yako? Nguye?", "Yako? Nguye?", "Yiya makamana mu lamba,", "Nyi kwivwa kha liji lia mwilu?", "Makavwisa umwe chinyengo?", "Yako? Nguye?", "Yako? Nguye?"]}]}, {"numero": 172, "titulo": "MUZE MAKEMBA CHITAVWI", "blocos": [{"type": "verse", "num": 1, "lines": ["Muze mwaka mu usula mutukevwa", "Chitavwi", "Uhenya wa mwana Phanga mwuilu to;", "Muze khule eswe mali kungulwila", "Hasali,", "Hamwe nyi yami kumungu kapwa ko."]}, {"type": "chorus", "lines": ["Muze ma…sanyika…ko", "Nyi maji…na maka atanga,", "Nyi yena…makusanyika,", "Hamwe nyi yami, kumungu kapwako."]}, {"type": "verse", "num": 2, "lines": ["Muze mutwivwa mutambi afu muli", "Kristu no,", "Ha uhenya unji maka hinduka;", "Waze atongwele Mwene hikuli", "Kungulula,", "Hamwe nyi yami kumungu kapwa ko."]}, {"type": "verse", "num": 3, "lines": ["Mwene tumu lingilenu mwalwa nyi", "Ufuku pwi,", "Twambujole sango Lienyi lia zango;", "Muze mwono mu usula milimo", "Hiyahwa pe", "Fweto kuli Mwene tuka tambule."]}]}, {"numero": 173, "titulo": "HAKAMWIHI NYI LWIJI MUTOMA", "blocos": [{"type": "verse", "num": 1, "lines": ["Kuli lwiji mutoma tho", "Maka thunga akwa usandu,", "Wapalika ku chitwamo", "Chiseke cha akwa-ufulielo."]}, {"type": "chorus", "lines": ["Cho chiseke mutukevwa,", "Mumu lia Mwene wetu Yesu,", "Muhtu kapwa miaka yeswe", "Hamwe nyi Yesu Chilamwina."]}, {"type": "verse", "num": 2, "lines": ["Shimbu kanda tuheta ko,", "Kusesa lia lwiji wacho,", "Ululi nyi kulemesa", "Nyi yetu mutukayiwana."]}, {"type": "verse", "num": 3, "lines": ["Ha ufulielo tuwane", "Ululi nyi kwononoka", "Cha Yesu, hanatufila.", "Hanga akatulamwine."]}, {"type": "verse", "num": 4, "lines": ["Mutumona lwiji wacho,", "Ungeji mba himu-uhwa,", "Mumakanwa mutukemba,", "Uhaliso wa miaka yeswe."]}]}, {"numero": 174, "titulo": "MESO NYI MESO", "blocos": [{"type": "verse", "num": 1, "lines": ["Ku meso Jenyi ngukapwe,", "Kwa Kristu, cho chiseke!", "Muze kuwaha hichoka,", "Shimbu yeswe kumumona?"]}, {"type": "chorus", "lines": ["Mungu kamumona Yeu,", "Muze meza mu uhenya.", "Meso nyi meso mu-uhenya", "Yesu nguka mumone."]}, {"type": "verse", "num": 2, "lines": ["Nguna mumwena kusuku,", "Kunyima lia chipwiko,", "Kunguna chizange, chinji", "Hakumuwana mwilu."]}, {"type": "verse", "num": 3, "lines": ["Ha kuka twama nyi Kristu", "Kuze kushi yikola;", "Hitwapuluka ku upi,", "Nyi zango matusweka!"]}, {"type": "verse", "num": 4, "lines": ["Meso nyi meso, chiseke", "Chenacho mutchikapwa!", "Hakumona huma Lienyi", "Wangu mwenene lamba."]}]}, {"numero": 175, "titulo": "YESWE KUWAHA", "blocos": [{"type": "verse", "num": 1, "lines": ["Chipwe tumone luyinda-hano hashi,", "Tangwa limwe masala", "Hanga tukaye Chifuchi cha mwilu,", "Kuze yeswe kuwaha."]}, {"type": "chorus", "lines": ["Mutuka mona Yesu,", "Nyi sambukila Yenyi", "Tuka twame Nenyi,", "Akatufunge", "Nyi chiseke chahiana."]}, {"type": "verse", "num": 2, "lines": ["Luchisa wahiana mu mwono uno;", "Tangwa limwe masala;", "Mba tukapwe nyi chiseke chahiana,", "Kuze yeswe kuwaha."]}, {"type": "verse", "num": 3, "lines": ["Tenu kukumba Yesu makatwaha,", "Muze tangwa muliza;", "Muze jita muyihwa, sambukila", "Kuze yeswe kuwaha."]}, {"type": "verse", "num": 4, "lines": ["Eswe malamwina makanyingika,", "Tangwa limwe mumalilu;", "Makawahilila matangwa eswe", "Kuze yeswe kuwaha."]}]}, {"numero": 176, "titulo": "MUNGU KAMUMONA", "blocos": [{"type": "verse", "num": 1, "lines": ["Muze mungu heta kusongo lia", "mwono uno,", "Mujimba wami ku uchi kafwa kha,", "Mwe Chilamwina chami kumungu", "Kamumona;", "Masehejela nyi zango lia mwilu."]}, {"type": "chorus", "lines": ["Munguka mumona yeu,", "Ku lumbu Lienyi kwe mungu kapwa.", "Munguka mumona yeu,", "Nyi yito Yenyi yiyi hamoko."]}, {"type": "verse", "num": 2, "lines": ["Kuwaha mungukevwa hakumumona", "yeu,", "mungu kapwa Nenyi ku miaka", "Yeswe!", "Cho chiseke mungukevwa hakunjila", "Mwilu", "Yesu Yiye mungu lianga kumona."]}, {"type": "verse", "num": 3, "lines": ["Twiulukenu akwetu aliangile kufwa,", "Chinyengo twakwivwa ha usona nyi", "Muze mutuliwana tuchi kalisa nawa", "Yesu Yiye mungu lianga kumona."]}, {"type": "verse", "num": 4, "lines": ["Hakukanjila kumapito jacho a mwilu,", "Nyi luyinda nyi missongo hiyawa;", "Eswe analilamwina miaso yipema", "memba,", "Yesu Yiye mungu lianga kumona."]}]}, {"numero": 177, "titulo": "HA KUSULA CHISEKE", "blocos": [{"type": "verse", "num": 1, "lines": ["Hakuhwa milimo chiseke,", "Walithachikila Kristu,", "Umutwalile athu anji", "Mwe mu yelusaleme!"]}, {"type": "chorus", "lines": ["Ku…waha muchi kapwa ko,", "Chi…seke chimwe chahiana;", "Kuwaha! Nyi zango linji,", "Mwilu hamwe nyi Mwene."]}, {"type": "verse", "num": 2, "lines": ["Mutukemba miaso yipema;", "Yakuhalisa Yehovwa", "Miaka yeswe makevwa", "Mwe mu Yelusaleme."]}, {"type": "verse", "num": 3, "lines": ["Chiseke muchika hiana,", "Mazuwo apema makapwa ko;", "Yesu makapwa nyi yetu", "Mwe mu Yelusaleme."]}]}, {"numero": 178, "titulo": "UWAHILILO WAHIANA", "blocos": [{"type": "verse", "num": 1, "lines": ["Sakwila euluka", "Tangwa nyi tangwa nguli", "Haka mwihi nyi zuwo mwilu", "Hanga nguka tunge mo."]}, {"type": "chorus", "lines": ["Muze shimbu,", "Ha shimbu te;", "Nguli hakamwihi nyi zuwo", "Hanga nguka thunge mo."]}, {"type": "verse", "num": 2, "lines": ["Hapwila Munguya", "Kuze kukushi yikola,", "Mungu kapwa nyi chiseke", "Hamwe nyi Kristu, Mwene."]}, {"type": "verse", "num": 3, "lines": ["Muze mungu kaheta", "Mungu kawahilila;", "Ngukahwime nyi sambukila", "Muchifuchi chipema."]}, {"type": "verse", "num": 4, "lines": ["Linga ungu pwise", "Ngwononokene Mwene,", "Ndo muze mungu kaya", "Kuzuwo lia zango Lie."]}]}, {"numero": 179, "titulo": "CHIFUCHI CHA CHISEKE", "blocos": [{"type": "verse", "num": 1, "lines": ["Nguna mono Chifuchi chipema", "Muze mungu kapwa shimbu yeswe;", "Mwatwama mazuwo apema,", "Yesu ayile nyi kululieka.", "Ngukapwe, ngukapwe,", "Chifuchi muchiza cha mwilu,", "Ngukaye, ngukaye,", "Muchifuchi cha mwilu muchiza."]}, {"type": "verse", "num": 2, "lines": ["Kumungu kembilamo miaso", "Yipema ya Chilamwina chami;", "Mungukapwa mwono wa chiseke", "Luyinda nyi chinyengo hiyahwa.", "Ngukembe, ngukembe,", "Chifuchi muchiza cha mwilu.", "Ngukembe, ngukembe,", "Muchifuchi muchiza mwilu."]}, {"type": "verse", "num": 3, "lines": ["Chifuchi chino muchikasala,", "Munguya ngukawahile Yesu;", "Mu chihunda cha ulu yipema,", "Tununu twakuwaha mungwivwa.", "Chiseke, kuwaha,", "Chifuchi chipema muchiza,", "Chiseke, kuwaha,", "Chifuchi chipema cha mwilu."]}]}, {"numero": 180, "titulo": "MUZE SOMA MAKEJILA ATHU JENYI", "blocos": [{"type": "verse", "num": 1, "lines": ["Yino ye chimbu yakucha,", "Hakanunu ka miaka.", "Muze Soma manda mbwechi", "Akamanune shili,", "Afu muze makahinduka;", "Makamana kuli Zambi,", "Hanga akatambule fweto", "Muze Mwene makeza."]}, {"type": "verse", "num": 2, "lines": ["Chiseke cha akwa ululi!", "Ahichikile shili,", "Meso jo makatemuka,", "Mumu hana fuliela,", "Ako kufwa kuchishiko,", "Kuli mono wa miaka,", "Maka njila muyikolo", "Mumu hakumba shili."]}, {"type": "verse", "num": 3, "lines": ["Makacha ye mbuto yetu,", "Matambula mihuko,", "Waze mahichika shili,", "Maka tambula fweto,", "Mwilu makawahilila,", "Kechi kalila nawa,", "Mumu hatambula mwono,", "Kuli Soma ya Mwilu."]}, {"type": "verse", "num": 4, "lines": ["Mutukamona masepa,", "Afwile hano hashi,", "Waze atoma mu mbunge,", "Ali nyi Chilamwina", "Kechi kanjila mu shili.", "Maka twama nyi Zambi,", "Makatwama nyi chiseke,", "Muze maka tambula."]}]}, {"numero": 181, "titulo": "YIYE MAKACHILUMBUNUNA", "blocos": [{"type": "verse", "num": 1, "lines": ["Yeswe yangu jingilika,", "Mba lie lamba nyi luyinda;", "Yikola kuli yina kathuka,", "Mangu kachinyingika."]}, {"type": "chorus", "lines": ["Tanwa Chilamwina meza;", "Lienalio makangwambulwila;", "Ngulamwine kumisongo,", "Mba mungu kachinyingika."]}, {"type": "verse", "num": 2, "lines": ["Chanyingikine zango liacho", "Tato wechele Mwanenyi.", "Ha kulusu angulamwine,", "Mungu kachinyingika."]}, {"type": "verse", "num": 3, "lines": ["Kumisongo kuluyinda,", "Nguna mono kwoko Lienyi;", "Angu songwele mu milima,", "Mungu kachinyingika."]}]}, {"numero": 182, "titulo": "MALONGESHI JA UPALE", "blocos": [{"type": "verse", "num": 1, "lines": ["Malongeshi a upale akalamwine,", "Nyi zango kulinga milimo", "Mumazuwo."]}, {"type": "chorus", "lines": ["Mwe longeshi ya upale keshi kuchina!", "Mwe longeshi ya upale-ambujole", "Kristu!", "Shishika kulithachika nyi Yesu-ukumbe.", "Mwe longeshi ya upale chipwe ndo", "Kufwa."]}, {"type": "verse", "num": 2, "lines": ["Akweze nyi makulwana, kilikitenu", "Kanda tulondelela-akwetu nyi milalu!"]}, {"type": "verse", "num": 3, "lines": ["Anamalunga anamapwo nyi chihanda", "cho!", "Chakutwala lino sango ndo kumahondo."]}, {"type": "verse", "num": 4, "lines": ["Tulingenu, nyi talenu, ndo Yesu", "meza,", "mba tukevwe ngwo kapinji mupema", "njila."]}]}, {"numero": 183, "titulo": "ANA KA KWONONOKA", "blocos": [{"type": "verse", "num": 1, "lines": ["Enwe ana katukenu, nyi lie kulusu!", "Lithachikenu nyi-akwa khole", "Ja Mwene Yesu"]}, {"type": "chorus", "lines": ["Enu ana nwafuliela ononokenu,", "Kuli Yesu!", "Nujikiza nyi je shimbi", "Ja Chilamwina."]}, {"type": "verse", "num": 2, "lines": ["Talenu-akwakunuzwelesa,", "To nyi-ufwathulo;", "Tulinunge! Tulithachike", "Nyi hamu lieswe!"]}, {"type": "verse", "num": 3, "lines": ["Kundamenu ko nyi hamu,", "Hamwe nyi Yesu;", "Mbimbiliya yinusongwele,", "Mu pangu lia mwilu."]}]}, {"numero": 184, "titulo": "CHISEKE WIKA", "blocos": [{"type": "verse", "num": 1, "lines": ["Yipwe mbunge ya chiseke", "Shimbu yeswe yakuhalisa,", "Mumu Tata wa mumalilu", "Kakutulweza zango."]}, {"type": "chorus", "lines": ["Nyi chiseke, nyi chiseke,", "Mwono wa mukwa kufuliela;", "Nyi chiseke chize chahiana", "Aye matulamwina!"]}, {"type": "verse", "num": 2, "lines": ["Zambi kumatu pulwila", "Matukwata nyi kwoko Lienyi;", "Chawana chenyi cha miaka", "Ha lamba matukwasa."]}, {"type": "verse", "num": 3, "lines": ["Maka funga akwa ululi,", "Mujila ya pangu Lienyi,", "Kumutu kamuwayila", "Yesu yoze twazanga."]}]}, {"numero": 185, "titulo": "ZANGO LIA KUTUWAHISA", "blocos": [{"type": "verse", "num": 1, "lines": ["Zango liatuwahisa,", "Lia neha chiseke,", "Nyi kuhetesa ye shimbi", "Liakuneha thachi."]}, {"type": "chorus", "lines": ["Zambi mupema; etu tuli anenyi,", "Zambi mupema, zanga zango,", "Zango liatuwahisa,", "Lianeha chiseke", "Nyi kuhetesa ye shimbi", "Mulineha unene."]}, {"type": "verse", "num": 2, "lines": ["Chifuchi cha chinyengo", "Chazala missongo;", "Hanga tufupe akuetu", "Twafumbwile Mwene"]}, {"type": "verse", "num": 3, "lines": ["Muze mwono wetu te", "Mu-ukahwa hashi", "Tangwa mutu kaya mwilu,", "Tuka halise Zambi."]}]}, {"numero": 186, "titulo": "CHIMENEMENE", "blocos": [{"type": "verse", "num": 1, "lines": ["Muze mukucha chimene,", "Mungu nyonga Yena Zambi,", "Nguhetule meso jami", "Hijanguhwa mwono wa lamba,", "Unatela kuli Zambi", "Mujimba wami weswe una kuzange."]}, {"type": "verse", "num": 2, "lines": ["Mupuya yize yisuku mwazala tho", "mavu,", "Mushi meya chipwe tapalo, nawa,", "Nguji lia thachi ngunazange hano;", "Unene nyi uhenya, nayimwene", "mutembele."]}, {"type": "verse", "num": 3, "lines": ["Ena ukwete keke yahiana yeswe,", "Keshika kanwa liami, mulikulemesa,", "Mwono wami weswe munguku-", "chichimieka;", "Mwilu mungu kaku sanyika,", "ngutambule."]}]}, {"numero": 187, "titulo": "CHIMENEMENE", "blocos": [{"type": "verse", "num": 1, "lines": ["Chimenemene ngufupe", "Jila ya Chilamwina;", "Nguka ule ngano Jenyi", "Ha zango nyi ku lamba"]}, {"type": "chorus", "lines": ["Kanguzanga, kangu zanga,", "Yesu kakungu zanga;", "Ngwiuluke ha ngongota;", "Kumungu kamuzanga."]}, {"type": "verse", "num": 2, "lines": ["Chipwe nguli mwe kanuke,", "Nguzeyele liji Lie,", "Ngukaule jila Yenyi,", "Chichi kwivwa woma kha."]}, {"type": "verse", "num": 3, "lines": ["Mukwa thachi ngupulule", "Ku upi mangu kwasa;", "Ngu chinyine kuli Yena", "Aye mangu lamwina."]}]}, {"numero": 188, "titulo": "TUTEMWINYINE MULI YESU", "blocos": [{"type": "verse", "num": 1, "lines": ["Zambi maha twanuke,", "Kuze ma-asongwela,", "Chiteli cha uhenya;", "Kutemukina Yesu", "Tutemuke ngwe themo", "Ngwe pangu lia Zambi,", "Nyi kuchiza milima", "Yatujingilika."]}, {"type": "chorus", "lines": ["Tuli pangu likehe,", "Lie pangu lipema;", "Nyi kumasesa kweswe", "Kutemukina Yesu."]}, {"type": "verse", "num": 2, "lines": ["Nyi malelwa kanala", "Kanafuku pangu;", "Mwono wachinyengo,", "Kulusu yinaleme.", "Mu lie pangu lipema,", "Tulinge milimo", "Yakuhana chiseke", "Mu mbunge nyi mbunge."]}, {"type": "verse", "num": 3, "lines": ["Kuyuka achi chinene;", "Tutemukine Yesu", "Nyi kwenyeka milima", "Hanga pangu lize.", "Nyi manyonga apema", "Tulinge nyi zango;", "Hanga tupwe misayo", "Mba yitwe woma kha."]}]}, {"numero": 189, "titulo": "KACHIHANDA KE", "blocos": [{"type": "verse", "num": 1, "lines": ["Kristu hana tutumu ngwe pangu", "Hanga tutwale akwa shili mwilu.", "Achi che kuyuka Aye atuhele;", "Ami nyi kami nyi yena nyi ke."]}, {"type": "verse", "num": 2, "lines": ["Chifuchi chazala nyi milima,", "Ha pangu lietu, milima muyihwa,", "Pangu lia mwilu, Kristu atuhele,", "Ami nyi liami nyi yena nyi lie."]}, {"type": "verse", "num": 3, "lines": ["Upale wakanuke mweswawo", "Wakuzanga Yesu nyi kwononoka;", "Tutemune pangu, lize atuhele,", "Ami nyi liami nyi yena nyi lie."]}]}, {"numero": 190, "titulo": "MOKO APEMA", "blocos": [{"type": "verse", "num": 1, "lines": ["Moko jami nguli no", "Ngukwate ye Mbimbiliya;", "Meso jami nguli no", "Nguye nguli longese."]}, {"type": "chorus", "lines": ["Apema apema e moko", "Malingila kuli Zambi;", "Apema apema e meso", "Muze matala mwilu."]}, {"type": "verse", "num": 2, "lines": ["Meso jami nguli no", "Nguhase kumona yinji", "Moko jami nguli no", "Ngulinge yuma yinji."]}, {"type": "verse", "num": 3, "lines": ["Moko jami nguli no", "Malingila kuli Yesu;", "Meso jami nguli no", "Ngutale kuli Yesu."]}]}, {"numero": 191, "titulo": "MEZA YA MWENE", "blocos": [{"type": "verse", "num": 1, "lines": ["Yesu, Mwene, twakuzanga!", "Tuna lilulieka,", "Khule eswe hamuwika,", "Mujimba umuwika;", "Tununge a Spiritu", "Ha zango nyi keke.", "Tulinunge nyi Yena;", "Tupwe nyi chiseke."]}, {"type": "verse", "num": 2, "lines": ["Tuka twame ku meza Ye,", "Yize watusela hano", "Yakwi-uluka Yena,", "Mwene wetu Yesu,", "Hakulusu ndo mu-uhenya", "Chipema tuku-kaule-", "Mu ngano ja uhenya", "Ja Yoze watukulile."]}, {"type": "verse", "num": 3, "lines": ["Halisenu! Wayilenu!", "Mbunge yimuwika,", "Twimbenu yimuwika", "Twimbenu nyi chiseke,", "Nyi mwono kusakwila", "Uhenya We wahiana,", "A Kristu, Chilamwina!", "Mutwe-Wachikungulwila", "Uli shima lia zango!"]}]}, {"numero": 192, "titulo": "KULINUNGA CHILEMU", "blocos": [{"type": "verse", "num": 1, "lines": ["Chaku tuwahisa", "Kuli kata chetu!", "Se chize cha kutununga,", "Kuli Mwene wetu."]}, {"type": "verse", "num": 2, "lines": ["Ku meso ja Tata,", "Twa kulemba kama:", "Mba yipi hanji yipema;", "Twa kuyivwa hamwe."]}, {"type": "verse", "num": 3, "lines": ["Se twa kuli kwasa,", "Nyi mutwivwa lamba;", "Nyi kachi umwe malila", "Eswe twaku chivwa"]}, {"type": "verse", "num": 4, "lines": ["Nyi mutuli shika,", "Chinyengo twakwivwa;", "Te mba mutu kaliwana", "Mwilu tuka twame."]}]}, {"numero": 193, "titulo": "ZANGO MUZUWO", "blocos": [{"type": "verse", "num": 1, "lines": ["Yeswe kuyi napeme,", "Zango muzuwo;", "Upeme kuyi temo", "Zango muzuwo,", "Sambukila nyi zango", "Yisasu muyenyeka,", "Sambukila yipema,", "Zango muzuwo."]}, {"type": "chorus", "lines": ["Nyi zango, nyi zango,", "Yikola kha; nyi chinyengo.", "Zango muzuwo."]}, {"type": "verse", "num": 2, "lines": ["Zuwo lili chiseke,", "Zango muzuwo;", "Ukwa nyi ye yipi kha", "Zango muzuwo;", "Yitemo yamu wande,", "Muyi ngwimbila miaso,", "Nyi kuhana lie zango,", "Zango muzuwo."]}, {"type": "verse", "num": 3, "lines": ["Lilu kulina sehe,", "Zango muzuwo;", "Chifuchi chinamono", "Zango muzuwo", "Nyi lwiji malinyenga", "Nyi kwimba cha tujila,", "Yeswe chiseke wika.", "Zango muzuwo."]}, {"type": "verse", "num": 4, "lines": ["Yesu ngupwe wa yena", "Zango muzuwo;", "Hanga ngulilelese,", "Hanga nguzange chinji;", "Ufulielo nguhwime.", "Chiteli kuli soma", "Nguzange shimbi Jenyi", "Zango muzuwo."]}]}, {"numero": 194, "titulo": "KU POMBA MULI KRISTU", "blocos": [{"type": "verse", "num": 1, "lines": ["Ku pomba muli mwe Kristu,", "Thulo keshi ku tatama", "Ku hwima cha miaka yeswe;", "Tu kapuluke ku lamba."]}, {"type": "verse", "num": 2, "lines": ["Ku pomba muli mwe Kristu,", "Ku hinduka nyi chiseke;", "Mba Aye akatu mbate;", "Nyi chiseke chinji mwilu."]}, {"type": "verse", "num": 3, "lines": ["Ku pomba muli mwe Kristu;", "Tu chine ku upi weswe;", "Ku hichika ye yizezo,", "Mba ukapwe nyi we mwono."]}, {"type": "verse", "num": 4, "lines": ["Mukwetu pomba nyi Kristu;", "Mukapwa nyi sambukila;", "Uchi kapwa nyi yizezo,", "Haku kanjila mo mwilu."]}]}, {"numero": 195, "titulo": "KULI YESU TE CHIMWE?", "blocos": [{"type": "verse", "num": 1, "lines": ["Mwene Yesu kuna nyingika", "Se hashi nguna pinji", "Mbunge yami yato nyi lamba?", "Kulinyenga chami wivwa?"]}, {"type": "chorus", "lines": ["Yesu kaku mona yeswe", "Muze nguli nyi lamba.", "Ku upi utenu nyi ungalwe,", "Se Yesu mangu kwasa."]}, {"type": "verse", "num": 2, "lines": ["Mwene Yesu kuna nyingika", "Nguli wamokomoko.", "Kwenda mupangu lia kulusu?", "Chilamwina kuma ngwivwa?"]}, {"type": "verse", "num": 3, "lines": ["Mwene Yesu kuna nyingika", "Chipwe te manguzeza?", "Satana mangwiya ufulielo,", "Mukangu konekena?"]}, {"type": "verse", "num": 4, "lines": ["Mwene Yesu kuna nyingika", "Kufwa muchi ngwenyeka?", "Ngu shike wawa wa akwetu", "Yesu kuma kechi kevwa?"]}]}, {"numero": 196, "titulo": "KUSHI KULISHIKA", "blocos": [{"type": "verse", "num": 1, "lines": ["Nyi kachi mutu zanga akwetu", "Muyiza ye shimbu,", "Ha ola ya lamba mamba ngwo", "Salenu kanawa."]}, {"type": "chorus", "lines": ["Ku kushi kuli shika,", "Ku kushi kuli shika.", "Ku Chifuchi chize chaha", "Kushi kulishika."]}, {"type": "verse", "num": 2, "lines": ["Kuwaha ha kumona akwetu", "Muze maya mwilu,", "Muze Yesu makeza hano,", "Mba mu tukamona."]}, {"type": "verse", "num": 3, "lines": ["Muze kumushi kuli shika,", "Ngwe te hano hashi,", "Se sambukila kuli waze", "Maka lilamwina."]}]}, {"numero": 197, "titulo": "ZAMBI ANUFUNGE", "blocos": [{"type": "verse", "num": 1, "lines": ["Zambi apwe hamwe nyi yenu,", "Endele halumbu lienu,", "Anukwase yenu eswe,", "Anufunge nyi thachi Jenyi."]}, {"type": "chorus", "lines": ["Unene Wenyi nyi zango Lienyi,", "Mutuka takana nyi Yesu;", "Nyi thachi Jenyi nyi zango Lienyi,", "Zambi apwe hamwe nyi yenu."]}, {"type": "verse", "num": 2, "lines": ["Anufunge nyi zango Lienyi,", "Anulembejeke kama,", "Kukahete kuli akwenu;", "Anufunge nyi zango Lienyi."]}, {"type": "verse", "num": 3, "lines": ["Zambi anufunge ku yipi,", "Muze munu mona lamba,", "Kuli mika nyi yahashi.", "Zambi anufunge ku yipi."]}, {"type": "verse", "num": 4, "lines": ["Anufunge numu halise,", "Nyi chiseke Chenyi chaha,", "Kumilimo ya ya uhenya,", "Anufunge numu halise."]}]}, {"numero": 198, "titulo": "KUKUMBA NYI YESU", "blocos": [{"type": "verse", "num": 1, "lines": ["Uhenya hiwasolola", "Wa Yesu Mwanangana,", "Makevwa shimbi Jenyi;", "Yilayi yakwiza Chenyi,", "Yeswe hiyasoloka", "Yesu hakumba kaneza."]}, {"type": "chorus", "lines": ["Uhenya, uhenya! Aleluya!", "Uhenya, uhenya! Aleluya!", "Uhenya, uhenya! Aleluya!", "Yesu hakumba kaneza."]}, {"type": "verse", "num": 2, "lines": ["Chitavwi cha-akwa ufulielo,", "Ku jita hicha shika.", "Kristu kulutwe lia athu Jenyi,", "Mbunga hayitambula,", "Mukwa khole himachina,", "Uli wamwoka naye", "Yesu hakumba keneza."]}, {"type": "verse", "num": 3, "lines": ["Muze te hamuhingisa,", "Mavungu masopesa;", "Anene nyi waze akehe", "Ngaji himasopesa,", "Khule eswe waze hakumba,", "Himemba nyi chiseke", "Yesu hakumba kaneza."]}]}, {"numero": 199, "titulo": "ZAMBI KAKANGANA", "blocos": [{"type": "verse", "num": 1, "lines": ["A Zambi Yena wika, watela uhaliso,", "Yena ku miaka yeswe, tukakuhalise!", "He hashi watangile, watanga e malilu", "Milimo wayimana nyi Moko Lie Mwe", "Zambi."]}, {"type": "verse", "num": 2, "lines": ["Mwe Soma yama Soma, unene We", "wahina", "Ulemu We wahiana, ku ushi", "Kwalumuka", "Angelo mawayila mu Mbala Ye ya", "mwilu,", "athu Je kana kwichi hanga wavwile", "keke."]}, {"type": "verse", "num": 3, "lines": ["Yuma yingahi, yingahi, walinga nyi", "unene We,", "nyi yikomeso Ye, nguna kuhalisa,", "yena Lukhepwe wami, Mwe", "mwanangana Soma", "kechi kungwonga nawa, ngupwe mu", "Usoma We."]}]}, {"numero": 200, "titulo": "YESU, UCHINYINO WAMI", "blocos": [{"type": "verse", "num": 1, "lines": ["Yesu wazanga Chilamwina chami,", "Nakumu komoka chinji;", "Muchi swamo cha liwe, mangu", "sweka, mapha chiseke cha miaka."]}, {"type": "chorus", "lines": ["Muchi swamo cha liwe mangu sweka.", "Muphuya mwalwa wahiana;", "Wakungu sweka nyi zango lia Yena;", "Ngufuke kama kwoko Lie e e …", "Ngufuke kama kwoko Lie e e …"]}, {"type": "verse", "num": 2, "lines": ["Muchi wazango Chilamwina chami,", "Nguchize yinyengo yinji;", "Mangwaha thachi, mangutakamisa,", "Mba hanga nguli thachike."]}, {"type": "verse", "num": 3, "lines": ["Nguzalise nyi uwahiso unji.", "Nguku halise nyi miaso;", "Hakwimba munguku halisa Yesu,", "Chilamwina mukwa uthu."]}, {"type": "verse", "num": 4, "lines": ["Hakusula ngu hinduke nyi uhenya,", "Yesu mangu sambilila!", "Mungu kapwa nyi chiseke cha miaka,", "Nyi njimbi waze ahiana."]}]}, {"numero": 201, "titulo": "KALAYI, KWASALA CHINGAHI?", "blocos": [{"type": "verse", "num": 1, "lines": ["Kalayi, shimbu yika mba", "Tangwa muli thuthuka?", "Ufuku hindu unene", "Nyi hanji himukucha?", "Ngeji hima laula,", "Hakuthuthuka tangwa!", "Zala mba utale tale,", "Tangwa linathuhuka."]}, {"type": "verse", "num": 2, "lines": ["Kalayi tala lie pangu", "Liatemwina jila ye,", "Yilayi yinatulweze", "Shimbu yina palika", "Akwa usandu waze afwile,", "Mahinduka nyi mwono,", "Nyi matwi jo kumakevwa", "Chithavi cha ulamwino."]}, {"type": "verse", "num": 3, "lines": ["Kalayi walweza pangu", "Mwaka wa sambukila;", "Kololoka nyi chiseke,", "Chihete ku mihwahwa!", "Ngeji, ami ngunamono", "Mulimbo pangu liacho;", "Matapalo muli ulu", "Mwazala muo uhenya."]}, {"type": "verse", "num": 4, "lines": ["Kalayi tala Chifuchi,", "Mihuko nyi yitemo", "Tala Soma um-uhenya,", "Lwiji ngwe katalilo", "Evwa tulialia kuwaha!", "Animbi maswalale.", "Ngeji evwa cho kuwaha", "Hapwila muheta mo."]}]}, {"numero": 202, "titulo": "KUTWAMINYINA NYI KUTALATALA", "blocos": [{"type": "verse", "num": 1, "lines": ["Twa nyingikine muze meza", "Chimene nyi ha ufuku", "Hanji meza ku shimbu yimwe;", "Haku thuhuka cha tangwa.", "Mwene kana twambe tufunge,", "Lie pangu lie litemuke;", "Yesu muze makatuwana", "Kutuna mutalatala."]}, {"type": "chorus", "lines": ["Kutala tala nyi kukanyama,", "Nyi kukanyama;", "Kutunamu twaminyina."]}, {"type": "verse", "num": 2, "lines": ["Kunguna nyongo keke Yenyi", "Handando ya we ukule;", "Ya hichika uhenya Wenyi", "Mweza yatumwena lamba", "Se hana tuvwila chiseke.", "Muze maka mona khule", "Kutwaminyina shimbu yeswe", "Kutuna mutwaminyina."]}, {"type": "verse", "num": 3, "lines": ["Yesu mwe Chilamwina chami", "Kanyingika zango liami", "Mungu kapwa kulumbu Lienyi!", "Mungu kevwa liji Lienyi!", "Nyi kuli mwono wa thu amwe", "Akuvwila woma Yena,", "Amy nguli sepa lia Yena,", "Kunguna kutwaminyina."]}]}, {"numero": 203, "titulo": "CHIZE YESU ANGUZANGA", "blocos": [{"type": "verse", "num": 1, "lines": ["Mungu nwambulwila Yuma ya", "Longeshi!", "Chize natambwile pangu lia mwono;", "Kristu Yiye wangwalumwine lume;", "Kukushi mukwo walifwa ngwe Yiye"]}, {"type": "chorus", "lines": ["Mungufunga Longeshi yami,", "Zango keke Yenyi yahina", "Nyi umwe mahasa kutuchiza shili", "Kakungu zanga chinji!"]}, {"type": "verse", "num": 2, "lines": ["Mwono kuwazala weswe nyi shili,", "Ku luyinda nyi misongo mu mbunge,", "Aye yangu kwata nyi kwoko lia keke", "Yangwaha sambukila Yenyi yinji."]}, {"type": "verse", "num": 3, "lines": ["Tangwa ha tangwa kakwiza kuli", "Yami", "Hanga angu lweze lie zango Lienyi;", "Nakuzanga kulinyingika chahiana,", "Lie zango Lieny kulishi kweseka."]}, {"type": "verse", "num": 4, "lines": ["Zango liami haliapwila ngumuzange,", "Ngwambujole chize angulamwinyine", "Kwimba zango Lienyi lize liahiana", "Nguna tale Zambi mwono mu-usula."]}]}, {"numero": 204, "titulo": "KRISTU MAKAKWASA", "blocos": [{"type": "verse", "num": 1, "lines": ["Nyi molu jami mujinguwa,", "Kuli milima;", "Nyi ungeji mu –unguhwisa,", "Kristu mangukwasa."]}, {"type": "chorus", "lines": ["Mangu kwasa,", "Makangu funga;", "Hakulusu yangu lamwina", "Nguli mwe nyi We."]}, {"type": "verse", "num": 2, "lines": ["Nyi makimba machikimisa,", "Kali nyi yami;", "Mangu pulula phundu,", "Kristu mangukwasa."]}, {"type": "verse", "num": 3, "lines": ["Nguli nyi woma wakulutwe,", "Kristu mangu kwasa;", "Muze tangwa lipi muliza,", "Kristu mangu kwasa."]}, {"type": "verse", "num": 4, "lines": ["Chisanyiko Che cha phundu,", "Mungu kaheta;", "Ami chichi kahona kuya,", "Kwe kuma hietu."]}]}, {"numero": 205, "titulo": "MBUNGE YALAMBA", "blocos": [{"type": "verse", "num": 1, "lines": ["Mbunge yina nenganyana,", "Kristu mayihuzulula,", "Sambukila ukonekeno,", "Kuli Yiye mauyitambula."]}, {"type": "chorus", "lines": ["Tweya kawashi kuli Chilamwina,", "Kanda wivwa mwongo nyi woma?", "Tweya, tweya, kuma kwaha uhwimino."]}, {"type": "verse", "num": 2, "lines": ["Yikola yinji unevu", "Yakathuka ku shili ye?", "Tweya washi kuli Yesu", "Makwaha mwono wa miaka."]}, {"type": "verse", "num": 3, "lines": ["Tweya kuli Chilamwina,", "Chipwe uli nyi shili ye;", "Tweya Aye mukwa zango,", "Makwaha unene wawana."]}, {"type": "verse", "num": 4, "lines": ["Tweya kawashi kuli Kristu,", "Kana zange akulamwine;", "Kana zange upeme we,", "Jikijila kuli Yiye."]}]}, {"numero": 206, "titulo": "JILA JA KUHALISA", "blocos": [{"type": "verse", "num": 1, "lines": ["Tweyenu hanga nungwivwe", "Kungu nembila Kristu;", "Chilamwina chami phundu,", "Yeza nyi kungulamwina!", "Mwe Mwana Phanga wa phundu,", "Mwe wangu tuswile,", "Nyi e manyinga Jenyi", "Yangu kosa ye mbunge."]}, {"type": "verse", "num": 2, "lines": ["Kumunguka twama Nenyi,", "Mungu kamuhalisa,", "Ha yize hanalingi;", "Mwene wami nyi Soma", "Hindu chipwe upi", "Mungu shimbamisa", "Hindu kumu ngukemba,", "Se Yiye makawenyeka."]}, {"type": "verse", "num": 3, "lines": ["Hakukaula jila", "Yina twala mwilu,", "Kristu mungu kembila", "Yiye mwono wami!", "Muze upi mu-ukanguhwa,", "Kuzuwo lia usandu,", "Shimbu yeswe Kristu mwe", "Mungu kahalisa."]}]}, {"numero": 207, "titulo": "TALA HAKULUSU UKAWANE MWONO", "blocos": [{"type": "verse", "num": 1, "lines": ["Mwono hakutala hakulusu,", "Yesu ngwenyi; Tala Yiye;", "Upite wa hashi nyi chimwe,", "Upite uli he hakulusu."]}, {"type": "chorus", "lines": ["Khachi muhulikila", "B.T. khachi muhulikila,", "Nyi kutala Ngongota", "B.T. nyi kutala Ngongota,", "Ulamwino wawana,", "B.T. ulamwino wawana,", "Hulikila Ngongota."]}, {"type": "verse", "num": 2, "lines": ["Muze namwene mwe Chilamwina,", "Huma Lienyi to nyi keke;", "Muze yeseko muyingwiza,", "Kulusu hehali-ukonekeno."]}, {"type": "verse", "num": 3, "lines": ["Hakutala Yesu hakulusu;", "Ngwi-uluke Zambi yilakenyo,", "Nyi umwe menda keshi pangu", "Mujila yakuya mu malilu."]}]}, {"numero": 208, "titulo": "NGUKEMBE ZANGO LIA ZAMBI", "blocos": [{"type": "verse", "num": 1, "lines": ["Ngukembe zango lia Zambi,", "Zango Lienyi hali yami,", "Mumu wejile mwilu", "Yafila hali yami."]}, {"type": "chorus", "lines": ["Mungu kemba nyi lie zango,", "Kujichinkanguhwa kama;", "Kufwa Chenyi mba yangukula,", "Mungu kemba zango Lienyi."]}, {"type": "verse", "num": 2, "lines": ["Shimbu kanda nguchilila,", "Yesu yalianga kungwivwa;", "Shimbu kanda nguchilemba", "Ha lamba Aye yalemba."]}, {"type": "verse", "num": 3, "lines": ["Mba kuchi makangu zanga", "Nyi chalingile nyi chimwe?", "Nguna zange se kumwita,", "Ngu mwehe ye mbunge yami."]}]}, {"numero": 209, "titulo": "YESU YIYE CHILAMWINA", "blocos": [{"type": "verse", "num": 1, "lines": ["Kristu Yiye Chilamwina,", "Ku kushi nawa mukwo,", "Hana tufila nyi zango,", "Kuli Yiye kuli mwono."]}, {"type": "chorus", "lines": ["Yesu Yiye Chilamwina,", "Yiye mwe Chitaka nyishi.", "Mwe Yiye watufilile", "Hindu kali nyi mwono."]}, {"type": "verse", "num": 2, "lines": ["Akwa usandu ashishika", "Chatamba kwasa Vumbi;", "Yesu, Soma yamasoma,", "Tumuwayilenu eswe."]}, {"type": "verse", "num": 3, "lines": ["Tulembenu kuli Zambi,", "Yiye wika mahasa", "Kutu kwasa kwe ku lamba;", "Zambi mapulula nyi-enyi."]}]}, {"numero": 210, "titulo": "NALILONGESA USWAMINO UPEMA", "blocos": [{"type": "verse", "num": 1, "lines": ["Nalilongesele jila,", "Yakufuliela Yesu;", "Yingu wana uhwimino", "Natambula pangu Lie.", "Nanwine Shima litoma,", "Yingweseka zango Lie;", "Yiye wapwa thachi jami"]}, {"type": "chorus", "lines": ["Ngutwame muli Mwene,", "B.T. Ngutwame muli Mwene", "Ngutwame muli Mwene.", "Ngufuliele zango Lie;", "B.T. Ngufuliele zango Lie;", "Ngufuliele zango Lie;", "Ngusweke…Ngusweke kama", "B.T. ungusweke,", "Nyi moko Je, zango Lie."]}, {"type": "verse", "num": 2, "lines": ["Hungu nafu hakulusu,", "Kristu kali nyi yami;", "Kulithachika hichawa,", "Uhenya Kristu, uhenya!", "We mwono wami weswe", "Nauhana kuli Yesu;", "Manyinga Jenyi alemu", "Mangu funga mu pangu."]}, {"type": "verse", "num": 3, "lines": ["Kuhanjika nyi mana,", "Kulinga nyi unene We;", "Kuenda mujila yipema,", "Yiye atwame muli yami;", "Yiye uchinyino wami,", "Shima lia chiseke Yiye,", "Mafungu nyi malamwina,", "Kujita makukwasa."]}]}, {"numero": 211, "titulo": "UKONEKENO, SAMBUKILA NYI UNENE", "blocos": [{"type": "verse", "num": 1, "lines": ["Nyi tuna zange chiseke,", "Zambi matwaha cho,", "Nyi kupwa nyi uwayiso,", "Wa e maliji Jenyi."]}, {"type": "chorus", "lines": ["Sambukila nyi keke", "Ya zango nyi chawana,", "Kristu shima lia chiseke;", "Aleluya maya kuli Yiye!"]}, {"type": "verse", "num": 2, "lines": ["Nguli nyi chawana Chenyi,", "Hanga nguka kumbe;", "Spiritu nguli nayo", "Yingu chize shili."]}, {"type": "verse", "num": 3, "lines": ["Lie Spiritu likolo", "Muli kangu kwasa", "Ye mbunge yami yichili", "Nyi zuwo kusuku."]}, {"type": "verse", "num": 4, "lines": ["Nyi we ufulielo chashi", "Nyi che kutambula,", "Kuli Kristu Tata mata,", "Kutwaha usoma"]}]}, {"numero": 212, "titulo": "YESU MAKUMBULULA", "blocos": [{"type": "verse", "num": 1, "lines": ["Kulemba che unachinyongo", "Ngwe Yesu kana kuvulama?", "Tala mwilu zuwo lia akwa ulamwino,", "Kulemba che kana chivu."]}, {"type": "chorus", "lines": ["Mwilu kanevu kulemba che,", "Aye kavulamine kwita,", "Mukahanjika nyi Kristu,", "Yesu mwe makumbulula."]}, {"type": "verse", "num": 2, "lines": ["Chipwe wevwile ngwe Yakumba,", "Angelo makwambulwila,", "Fuliela ngwe Yesu Kristu hashi nyi", "Lilu", "Kuchitwamo meva kulemba che."]}, {"type": "verse", "num": 3, "lines": ["Aye kakwivwa kulemba cheswe,", "Keshi kulelesa nyi chimwe;", "Mafunga maphanga Jenyi nyi zango", "Kakwiva mutambi nawa ukehe."]}]}, {"numero": 213, "titulo": "ZANGO KULIALITELE", "blocos": [{"type": "verse", "num": 1, "lines": ["Unevu lie zango kulia litele,", "Lia Zambi akwete nyi yena?", "Ha zango Lienyi yatwaha Mwanenyi", "Akwa ululi makaya."]}, {"type": "chorus", "lines": ["Tako…", "B.T. tako ku zango lia Mwene,", "Tako…", "B.T. tako ku zango lia Mwene,", "Nyi chawana kana kusanyika,", "Tako ku lie zango Lienyi."]}, {"type": "verse", "num": 2, "lines": ["Kristu katambikile akwa ulemu,", "Chipwe waze akwa ululi;", "Nyi yiswale alelu nyi akwa shili,", "Yatuma nyi akwa sanyika."]}, {"type": "verse", "num": 3, "lines": ["Mwe muthu kahashile kuheta ko", "Ku meso a Zambi wahiana;", "Mumu shili yenyi yahiana kwoka,", "Yina muvumu kuya ko."]}, {"type": "verse", "num": 4, "lines": ["Manyinga a Yesu mathu tomesa,", "Milonga yakwa –ufulielo;", "Yachiza shili yatulweza jila,", "Kumatu songwela mwilu."]}]}, {"numero": 214, "titulo": "MUTWIZA KUCHA", "blocos": [{"type": "verse", "num": 1, "lines": ["Kuwenu ye mbuto liji lia mwe Tata", "Kuwenu chimene ndo ufuku pwi,", "Tuli kolwezenu mwaka wa che kucha", "Mutwiza kuyuka hakucha chetu."]}, {"type": "chorus", "lines": ["Eswe mutukacha. Eswe mutukacha.", "Nyi chiseke chinji. Eswe mutukacha."]}, {"type": "verse", "num": 2, "lines": ["Kuwenu nyi mwalwa, chipwe", "nyi muvwili,", "kanda nuchina vula, chipwe we", "mwalwa", "nyi milimo hiyahwa mba tuka", "hwime,", "mutwiza kuyuka hakucha chetu."]}, {"type": "verse", "num": 3, "lines": ["Kuwenu ye mbuto, chipwe nyi", "masoji,", "mwene kuma kwasa milimo Yenyi.", "Kulila nyi chahwa maka tutambula,", "Mutwiza kuyuka ha ulamwino."]}]}, {"numero": 215, "titulo": "KUYA KU SHIKOLA YA SAMBATA", "blocos": [{"type": "verse", "num": 1, "lines": ["Tambukenu ko tukwatenu mata,", "Pendelo lia Mwene tuli nyinyise;", "Twasenu nyi Vumbi hajina Lienyi;", "Kanda tuhilukila kunyima!"]}, {"type": "chorus", "lines": ["Halisenu…Halisenu", "B.T. Halisenu …Halisenu,", "Aswane…Afumane", "B.T. Afumane…Afumane,", "Mwene…Mwene", "B.T. Mwene…Mwene,", "Hano hashi nyi mwilu", "Tulinunge nyi athu ja Yesu,", "Ufulielo twendele mu pangu", "lia mwilu;", "usoma muwiza lamba hiliahwa,", "kanda tuya kunyima."]}, {"type": "verse", "num": 2, "lines": ["Nguna zange shikola yasambata,", "Nguhase kulithathika nyi mata;", "Muwande Wenyi mutuli thachika,", "Kanda tuya kunyima."]}, {"type": "verse", "num": 3, "lines": ["Kulimika chahwa tuwahilile,", "Luyinda wetu kechi kaheta ko;", "Ku Shiyono kuli chiseke chinji,", "Kanda tuya kunyima."]}]}, {"numero": 216, "titulo": "KUSHIKOLA YA SAMBATA", "blocos": [{"type": "verse", "num": 1, "lines": ["Mujina Lie tuputuke,", "Shikwola yino a Mwene!", "Tuna kwichi nyi zango Lie,", "Tweya upwe Kasongo ketu."]}, {"type": "chorus", "lines": ["Sambata jeswe twakwizaza,", "Ku shikola Ye a Yesu.", "Tweya Mwene utu longese.", "Mujila Ye ya pangu."]}, {"type": "verse", "num": 2, "lines": ["Shikola yacho yatu longesa,", "Kuzeyela shimbi Je;", "Yina twambe hanga tupwe", "Akwa-kushishika ndo kufwa."]}, {"type": "verse", "num": 3, "lines": ["Tu longese kama Yesu,", "Kwononokena shimbi Je;", "Kutuna kutwaminyina", "Hanga utuwahise."]}]}, {"numero": 217, "titulo": "HA SHIMBU YA SAMBATA", "blocos": [{"type": "verse", "num": 1, "lines": ["Tweyenu ku Sambata kawashi,", "Tujikize nyi thachi,", "Nyi zango lia kulilongesa,", "Tuyenu hamwe nyi Yesu."]}, {"type": "verse", "num": 2, "lines": ["Longeshi munene Kristu,", "Watuzangile chinji,", "Hakulusu kana tulweze", "Umwene mwene nyi zango."]}, {"type": "verse", "num": 3, "lines": ["Lemesenu zango liacho,", "Mwene atuhele;", "Nyi mbunge kulikehesa", "Tuye jila ya mwilu."]}, {"type": "verse", "num": 4, "lines": ["Muze mutu kalilongesa,", "Mu mbongo nyi kulila;", "Mutuka njila mushikola.", "Mwene matusongwela."]}]}, {"numero": 218, "titulo": "LIEZA KANAWA TANGWA LIA SAMBATA", "blocos": [{"type": "verse", "num": 1, "lines": ["Hilieza chochene,", "Tangwa lia Mwene,", "Hanga litwi-ulwise", "Yitanga Yenyi, zango Lienyi.", "Muchifuchi nyi yizezo yipi", "Chindulula mbunge jetu", "Chindulula mbunge jetu."]}, {"type": "verse", "num": 2, "lines": ["Tweya Thuminyi ya Mwilu,", "Tungulula ye mbunge", "Ndo etu mutupwa", "Nyi ungunu We", "Tuchize kama shingo lieswe!", "Tufungile ha kwoko Lie", "Tufungile ha kwoko Lie."]}, {"type": "verse", "num": 3, "lines": ["Tweya nyi unene We,", "Twambe yipema wene", "Kwasa umwe ha umwe", "Hanga mu zango Lie", "Afupe ulamwino muli Yena", "Twehe kama ulamwino We!", "Twehe kama ulamwino We!"]}]}, {"numero": 219, "titulo": "TWEYA SHIPIRITU YAZANGO", "blocos": [{"type": "verse", "num": 1, "lines": ["Tweya Shipiritu Ya zango", "Mwe liembe wa Mwilu,", "Twehe che chivukuminya", "Cha shima lia mwono", "Cha shima lia mwono."]}, {"type": "verse", "num": 2, "lines": ["Hetula je mbunge jetu,", "Mutchifuchi chipi;", "Twehe chawana chipema", "Tukwononokene", "Tukwononokene"]}, {"type": "verse", "num": 3, "lines": ["Twalela tukonekene,", "Tulamwine ku-upi;", "Tulongese shimbi Je", "Lie liji lia Mwilu.", "Lie liji lia Mwilu."]}]}, {"numero": 220, "titulo": "CHIWANYINO CHA MWENE", "blocos": [{"type": "verse", "num": 1, "lines": ["Mandumbu hitwa kunguluka", "Kumeza ya Mwene.", "Hatuzalisa nyi zango", "Lia mwilu lia Mwene,", "Yinyingi yize twamona", "Upeme wa miaka yeswe", "Nyi zango tunalihana", "Shili yize twalinga."]}, {"type": "verse", "num": 2, "lines": ["Shili yaneha hashi", "Ufwe nyi kwenyeka", "Zango lia Yesu linji", "Yatulamwina ku upinji.", "Tuna sakwila tuli eswe", "Yesu hakutuila;", "Yitanga yetu yeswe,", "Twayisa hakulusu."]}, {"type": "verse", "num": 3, "lines": ["Yakunyima nyi yinyengo-", "Yatoka hakulusu;", "Etu hapwila chiseke", "Uwahililo kuli Zambi.", "Tunasakwila nyi miaso-", "Tuna vumbika Mwene-", "Ha keke Yenyi nyi yetu", "Nyi zango lia miaka yeswe."]}]}, {"numero": 221, "titulo": "MWENE YENA UNATUSANYIKA", "blocos": [{"type": "verse", "num": 1, "lines": ["Mwene, Yena una tusanyika,", "Twi-uluke chiwanyino Che,", "Twahichika milimo yeswe", "Hanga tupwe nyi Yena.", "Kuyuka chetu Mwene", "Yinyingi ya ufwe", "Ha kulitakana cha zango."]}, {"type": "verse", "num": 2, "lines": ["Mujimba we wakulemeka,", "Una twehe ulamwino", "Mbolo watuhele hanga,", "Tulinunge nyi", "Musenge wa yinyengo;", "Waunwine Yena Yesu", "Hakulusu watuhele musenge upema."]}, {"type": "verse", "num": 3, "lines": ["Nyi milimo hiyahwa,", "Ha ufwe ukalu,", "Wazulwile jila ku", "Mwono wa miaka", "Hi yitanga ko wika", "Twakunyingikina Yena!", "Tuna nyingika mbunge", "Ye yazango."]}]}, {"numero": 222, "titulo": "TWEYA USONGWELE CHIWANYINO", "blocos": [{"type": "verse", "num": 1, "lines": ["Meza ha yala a Chilamwina,", "Tweya wisongwele!", "Palula mbolo uhane vinyu", "Yinyingi, ya Yena Yesu."]}]}, {"numero": 223, "titulo": "MBIMBILIYA KUCHI YINAMBE?", "blocos": [{"type": "verse", "num": 1, "lines": ["Mbimbilia kuchi yinambe?", "Liji lilemu kuli yami", "Chichi kujikijila longeso lia athu", "Zambi kuchi ana nwambulwila?"]}, {"type": "chorus", "lines": ["Mbimbiliya kuchi yinambe?", "Fupenu kuyi nyingika;", "Kumi lia shimbi fungenu jeswe", "Yesu haliapwila meza!"]}, {"type": "verse", "num": 2, "lines": ["Akehe azanga shimbi ja Zambi,", "Akehe anajifungu;", "Amwe kazanga kuji thuthulula", "Kuchiza ko ye Sambata."]}, {"type": "verse", "num": 3, "lines": ["Muze makeza kuchi munukamba?", "Yenwe kunwajifungile;", "Makanuwana kununa sambe?", "Kumbululenu musono."]}]}, {"numero": 224, "titulo": "SHINA HO KUONONOKA", "blocos": [{"type": "verse", "num": 1, "lines": ["Kuononoka shinaho kuhiana itapo,", "Shinaho shimbu yeswe kufunga", "Je shimbi."]}, {"type": "chorus", "lines": ["Kuli Zambi, nyi ufulielo tuyenu", "Ku je shimbi, tuononokenu.", "Keshika kounonoka shinaho itapo,", "Shinaho shimbu yeswe kufunga", "je shimbi."]}, {"type": "verse", "num": 2, "lines": ["Yenue nuakuamba ngwo, shimbi", "jishi ulemu", "ononokenu yisonyeko nwiuluke."]}, {"type": "verse", "num": 3, "lines": ["Uwahiso wika,wa akufunga shimbi,", "Nyi chimwe nawa mutchikumba", "Kuononoka."]}]}, {"numero": 225, "titulo": "SHIMBI JA MWENE WAMI", "blocos": [{"type": "verse", "num": 1, "lines": ["Jilemu nawa jipema,", "Je shimbi ja Mwene wami;", "Ja kwalumuna we mwono,", "Mukwa shili te matoka."]}, {"type": "chorus", "lines": ["B.T. Cha Mwene …", "S.C. Cha Mwene che kulongesa", "B.T. China …zala nyi yiyulo", "S.C. China …zala nyi yiyulo…", "Eswe: Chinazala nyi je shimbi", "Mujitu kanyamisa."]}, {"type": "verse", "num": 2, "lines": ["Kulongesa cha Yehova,", "Cha ululi chipema;", "Chinapu ngwe katalilo,", "Ngumwene ho upi wami"]}, {"type": "chorus", "lines": ["B.T. Ngwe tangwa…", "S.C. Jinatu tangwa munyima,", "B.T. Je shimbi…Ja Mwene,", "S.C. Je shimbi…Ja Mwene,", "Eswe; jitemwine mitwe yetu", "Nyi lie pangu lia Mwilu."]}]}, {"numero": 226, "titulo": "UFULIELO KUKUMBA", "blocos": [{"type": "verse", "num": 1, "lines": ["Tujita twa Yesu Mwene", "Laulenu kawashi!", "Ufuku uneza milima pwi", "Tuli thachikenu.", "Lithachikenu nyi akwa khole", "Kanda nukokoloka", "Ufulielo che kukumba", "Tukumbe Satana."]}, {"type": "chorus", "lines": ["Ufulelo kukumba", "Ufulielo ukwete unene,", "Ufulielo che kukumba", "Ukakumbe Satana."]}, {"type": "verse", "num": 2, "lines": ["Mushi lia pendelo lietu", "Lie zango lia Zambi,", "Twendenu mu jila ayi,", "Yakutwala mwilu,", "Akwa ufulielo asandu", "Hakumba Satana;", "Ufulielo che kukumba,", "Tupwe nyi sambukila."]}, {"type": "verse", "num": 3, "lines": ["Tuli nyi akwa khole hano,", "Kana chikimisa,", "Tuhichike yeswe hano,", "Tulithachikenu,", "Nyi lukepwe wa ulamwino", "Yesu maka twaha", "Tutayizenu nyi mbunge", "Makatulamwina."]}, {"type": "verse", "num": 4, "lines": ["Mweswe makumba nyi ufulielo", "Kumakamujika,", "Maka mwaha jina liaha", "Mamukonekena, nyi mbunge ja", "Ufulielo", "Jato nyi lie zango, tuka kumbe", "Nyi ufulielo, maka twaha", "Mwene."]}]}, {"numero": 227, "titulo": "LONGESHI YAMI MUPEMA", "blocos": [{"type": "verse", "num": 1, "lines": ["Longeshi mupema, Soma ya Yeswe,", "Ena Muthu, Zambi, Kristu Yesu.", "Mukuhalisa, nyi kukulingila", "Uli uhenya wami nyi Kristu."]}, {"type": "verse", "num": 2, "lines": ["Yitemo yamuyambu cho kupema,", "Yepemese mathungu!", "Kristu kanuhiana, Aye mupema,", "Mukwa uthu, shimbu yeswe."]}, {"type": "verse", "num": 3, "lines": ["Tangwa cho kupema nyi kakweji!", "Kuhenyama chenu kuchishi shimbu!", "Liahenyama, liatemuka. Lipema.", "Ndo kuli Yesu, Soma wahiana!", "Améne!"]}]}, {"numero": 228, "titulo": "YESU MWE YESWE KULI YAMI", "blocos": [{"type": "verse", "num": 1, "lines": ["Yesu mwe yeswe kuli yami", "Mwono wa chiseke;", "Thachi ja lukhanda wami", "Nyi nanyenganyana ndo Yiye,", "Pundu keshi kunguvulama", "Yiye wanguvisa chiseke", "Kristu yami."]}, {"type": "verse", "num": 2, "lines": ["Yesu mwe yeswe kuli yami", "Sepa ha lie lamba;", "Kakungwaha we uwahiso,", "Kakupa we unji.", "Kakungwa vula nyi mwalwa", "Mungupwa nyi mbuto yinji", "Vula, mwalwa nyi lie pangu,", "Kristu yami."]}, {"type": "verse", "num": 3, "lines": ["Yesu mwe yeswe kuli yami.", "Ndo ngumuzeyele", "Sepa liami munene", "Chalikalile ye.", "Kwenda nyi Yiye cho chiseke", "Mujila yipema nguli", "Nyi Yesu nguli mu pangu", "Kristu yami."]}, {"type": "verse", "num": 4, "lines": ["Yesu mwe yeswe kuli yami;", "Mwe mapa chiseke", "Yiye ujikijilo wami,", "Cha honene sambukila.", "Kupwa kwe kulumbu Lienyi", "Kulenga chami cha miaka", "Nguka puluke ku-upi", "Kristu yami."]}]}, {"numero": 229, "titulo": "KRISTU WIKA YIYE PANGU", "blocos": [{"type": "verse", "num": 1, "lines": ["Angelo memba miaso;", "Kristu Yiye pangu;", "Uhenya Soma Pangu!", "Kristu Yiye pangu."]}, {"type": "chorus", "lines": ["Twendenu mu pangu, lilemu", "Lina temwina Mwilu nyi hashi;", "Kuli waha pangu lia Yesu!", "Kristu Yiye lie Pangu."]}, {"type": "verse", "num": 2, "lines": ["Muswanisenu mavungu!", "Kristu Yiye lie Pangu;", "Tumwimbilenu miaso,", "Kristu Yiye lie Pangu."]}, {"type": "verse", "num": 3, "lines": ["Muwayilenu nyi thachi,", "Kristu Yiye lie Pangu;", "Yiye Chilamwina chetu,", "Kristu Yiye lie Pangu."]}, {"type": "verse", "num": 4, "lines": ["Uhenya vulie Mwanangana!", "Kristu Yiye Pangu;", "Hana kumbu Satana,", "Kristu wika lie pangu."]}]}, {"numero": 230, "titulo": "TWAMA NYI YAMI CHILAMWINA", "blocos": [{"type": "verse", "num": 1, "lines": ["Mwe Chilamwina nazanga", "Nguvile kama kheke Ye;", "Lelwa lia hashi nyi limwe", "Muli nguchiza pangu lia mwilu."]}, {"type": "verse", "num": 2, "lines": ["Muze muka hinduka mu ufwe", "Ngukapwe kulutwe Lie;", "Hakuputuka milimo yami,", "Ngusongwele nyi ngupulule."]}, {"type": "verse", "num": 3, "lines": ["Tweya ungwehe unene We", "Mba nguka hase kukumba", "Kusongwela cha mukwa kwonga;", "Pwako nyi yami Chilamwina."]}]}, {"numero": 231, "titulo": "NGUSONGWELE LONGESHI YAMI", "blocos": [{"type": "verse", "num": 1, "lines": ["Ngusongwele, Longeshi yami", "Nyi kwoko Lie", "Ha chocho kanda uhona", "Kungu pulula!", "Chichi kuhasa kwenda,", "Nyi chishi nyi Yena;", "A Yesu pwako shimbu yeswe", "Luthemo wami!"]}, {"type": "verse", "num": 2, "lines": ["Ku chawana Che jingilika", "Mbunge yami", "Yehe sambukila kuluyinda", "Mba nguka hwime muli Yena", "Haka mwihi nyi kulusu,", "Kanda ungu handununa", "Kuli Yena Yesu."]}, {"type": "verse", "num": 3, "lines": ["Nyi muze kulithachika", "Chinene hichapwa,", "Uka ngusongwele, Longeshi yami", "Nyi kwoko Lie,", "Nyi kanda ungwehuka", "Ha kupulula Che."]}]}, {"numero": 232, "titulo": "HINGU NAFU HAKULUSU", "blocos": [{"type": "verse", "num": 1, "lines": ["Hingu naku fila hakulusu,", "Mukwa shili!", "Manyinga hana mwangana,", "Yikola nevwile.", "Nafilile hakulusu,", "Chenacho Ami nakawile", "Nakuchijile milima,", "Yika wangu lingila?"]}, {"type": "verse", "num": 2, "lines": ["Himokomoko ko", "Nahichikile Usoma", "Chasumbakenyene uhenya,", "Haze ha kulusu.", "Zuwo liasalile mwilu", "Napwile mwe chilambala;", "Kanda upwa nyi tuliongelo,", "Yika wangu lingila?"]}, {"type": "verse", "num": 3, "lines": ["Lamba liokele naye!", "Lize naku mwenene,", "Kukushilimwe likwo,", "Lize nahongelele", "Ufwe naulelesele,", "Hanga mba nguku lamwine", "Kulamba shimbi ya miaka;", "Yika wangu lingila?"]}]}, {"numero": 233, "titulo": "CHESEKO", "blocos": [{"type": "verse", "num": 1, "lines": ["Eswe ya woma anambe", "Yili mujila nguli;", "Kamwene pangu zwalala", "Mujila muze nguli"]}, {"type": "chorus", "lines": ["Yesu ku mangusongwela,", "Heza apwe nyi yami", "Chifuchi cha to nyi khole,", "Chahashile kwenda wika."]}, {"type": "verse", "num": 2, "lines": ["Mahanjika yamahuza,", "Nyi yeseko yikalu;", "Yesu kuma kangufunga", "Makangu lembejeka."]}, {"type": "verse", "num": 3, "lines": ["Nguli nyi zango likehe,", "Mulingu vulumwisa;", "Ukwaso Wenyi wa mwilu,", "Mba hanga ngukakumbe."]}]}, {"numero": 234, "titulo": "KRISTU ENDESE WATO WAMI", "blocos": [{"type": "verse", "num": 1, "lines": ["Kristu endesa wato,", "Kalunga matenuka,", "Kakutenuka chinji,", "Mashindamisa wato", "Tweya Yesu utwendese,", "Songwela wato wami."]}, {"type": "verse", "num": 2, "lines": ["Kuwa kulembejeka", "Ngwe naye hali mwana,", "Tweya kalunga ahole,", "Kana tenuka chinji,", "Tweya Kristu usongwele,", "Songwela wato wami."]}, {"type": "verse", "num": 3, "lines": ["Himutu heta kuzuzu,", "Hindu kanatenuka,", "Kumu ngwivwa chiseke", "Mungwivwa Yesu mamba;", "Njila ngeji mukwa lamba,", "Mu-uhwimino wa Mwene."]}]}, {"numero": 235, "titulo": "ZANGO LIAHIANA", "blocos": [{"type": "verse", "num": 1, "lines": ["Wangu fupile yami,", "Yesu mwe Kafunga;", "Yangu wana mulamba!", "Yangukula nyi zango;", "Angelo mwilu embile,", "Hakusolola zango lio."]}, {"type": "chorus", "lines": ["Lie zango liahiana!", "Nyi ndando yinene!", "Yesu afetele hakulusu,", "Yangu lweza zango liahiana!"]}, {"type": "verse", "num": 2, "lines": ["Yilonda yami yinji,", "Yesu yangu kwata;", "Mba yangu lweza ngwenyi", "Hiwapwa nyi Wami!", "Alio liji lia chiseke", "Nguye nyi ye sambukila!"]}, {"type": "verse", "num": 3, "lines": ["Yesu –yangulweza je mbandu", "Mumu hali yami,", "Chipangula cha mbimbo,", "Yamusa hakulusu,", "Chika angu mwene nacho,", "Amwenene lamba liacho!"]}, {"type": "verse", "num": 4, "lines": ["Shimbu yina palika,", "Nguli nyi sambukila", "Nguna mutwaminyina", "Hanga angu wahise!", "Yesu muze mangwijila,", "Mungu katwama ndo miaka!"]}]}, {"numero": 236, "titulo": "HAKUJIKA TEMBELE", "blocos": [{"type": "verse", "num": 1, "lines": ["Tuhalisenu Zambi nyi miaso", "Ha uwahiso Aye ana twehe Anenyi,", "Mumu mutuyihana kuli Mwene;", "Tembele yino ha Vumbi nyi kuhalisa."]}, {"type": "chorus", "lines": ["Halisenu nyi miaso ya zango", "Halisenu, linungenu nwimbe", "Twimbenu uhaliso wa Yesu", "Chilamwina.", "Ha uwahiso anahana kuli eswe."]}, {"type": "verse", "num": 2, "lines": ["Ngwe luthemo una temwina milima,", "Una lweze ngeji unende mukalunga;", "Muzuwo pangu lia Mwilu linatu,", "Ha ulamwino wa-akwa kutoka."]}, {"type": "verse", "num": 3, "lines": ["Muno, afuliela kaneza akuwayile,", "Kuwayila Mwene chipema lume;", "Mutwaha thachi jikuase,", "Eswe kaneza akuwayile"]}]}, {"numero": 237, "titulo": "TEMBELE YIKWO NAWA", "blocos": [{"type": "verse", "num": 1, "lines": ["Zambi musono kutuna putuka", "Chinyingi cha kwambujola zango Lie;", "Tembele muyisongwela mwilu,", "Uhaliso woke!"]}, {"type": "chorus", "lines": ["Uhenya wa Zambi, uhenya wa Zambi!", "Ana Je akwimbile!", "Uhenya wa Zambi, uhenya wa Zambi!", "Uhenya wa kwilu!"]}, {"type": "verse", "num": 2, "lines": ["Zuwo lia Vumbi, chinyingi cha", "Pangu", "Tutambwile mo ulamwino", "Wa sango anehene Mwene Yesu", "Nyi keke yahiana!"]}, {"type": "verse", "num": 3, "lines": ["Taka lize lia umwene mwene", "Lia lie zango lie nyi kuzanga Che;", "Muno akwa shili kumakevwa", "Mba upale wo uka."]}, {"type": "verse", "num": 4, "lines": ["Zuwo lino lipwe lia kulembela,", "Chihela cha Mwene Zambi,", "Kujila cha mwilu nyi ukonekeno,", "Mwono wa sambukila!"]}]}, {"numero": 238, "titulo": "UFUKU WA SAMBUKILA", "blocos": [{"type": "verse", "num": 1, "lines": ["Sambukila nyi lie zango", "Yeswe yangu jingilika;", "Ku mbele asemukine,", "Soma wa sambukila", "Mwe Chilamwina,", "Yesu Mwene wetu."]}, {"type": "verse", "num": 2, "lines": ["Uhenya wa Zambi, kuli, Zambi.", "Kanembi angelo mwilu,", "Sango ja ukonekeno", "Chawana cha ulamwino", "Cheseko cha zango,", "Yesu matwaha."]}, {"type": "verse", "num": 3, "lines": ["Soma ya zango, nyi sambukila", "Watangile Chifuchi", "Tweyenu hanga tumwite", "Hanga atusongwele", "Chifuchi cha pangu,", "Yesu Mwene wethu."]}]}, {"numero": 239, "titulo": "MWASO UKULU", "blocos": [{"type": "verse", "num": 1, "lines": ["Twevanga ko miaso yipema", "Ha muchima ufuku", "Yakwimba kanawa nyi angelo", "Mujimbi ja kwilu", "Hashi chiseke kuli athu", "Makololoka Soma", "Hashi yeswe kulungunga", "Hakwivwa angelo."]}, {"type": "verse", "num": 2, "lines": ["Tala tala makoke kwilu", "Nyi maphulwa akwazulula", "Miaso tunayivu muthethela", "Kwambulula cha kwilu", "Kumilundu nyi ku mihwahwa", "Nyi kuthu takanyisa eswe", "Mapwa ha shimbu yaluvundo", "Nyi mwaso wa chiseke."]}, {"type": "verse", "num": 3, "lines": ["Ku miteto, kupinda, nyi missongo", "Lamba muchifuchi chino", "Miaso yineza kuli yetu", "Tununu no kanayi", "Mbunga yinazwele hakachi", "Kevile ndo liji lia zango,", "Holenu, afu, ndombo hano,", "Chilamwina hasemuka."]}]}, {"numero": 240, "titulo": "CHISHIMA CHA MAVUNGU", "blocos": [{"type": "verse", "num": 1, "lines": ["Tuli nyi chimwe chishima cha", "Mavungu", "Chishima cha to nyi sambukila;", "Mu milima wangwendesele", "Yoze musono Soma Yesu", "Yoze musono Soma Yesu"]}, {"type": "chorus", "lines": ["Chochene milima hiyapwa chimene", "Amu tangwa hilia temuka", "Chenacho, Kristu mahinga hano", "Mu wanangana wa pangu nyi zango"]}, {"type": "verse", "num": 2, "lines": ["Tuli nyi miaso yipema ya mavungu", "Nyi kwakungulwila kuli Mwene", "Nyi kupupa njiza jajita", "Nyi mata kakwanongesa"]}, {"type": "verse", "num": 3, "lines": ["Hindu tuli nyi Chilamwina wa", "mavungu", "nyi lamba hanafu hakulusu", "hanga athu eswe", "achine milima eze ku pangu", "achine milima eze ku pangu."]}]}, {"numero": 241, "titulo": "KULINUNGA CHA MWONO", "blocos": [{"type": "verse", "num": 1, "lines": ["Athu a-ali wanunge a Mwene;", "Athu a-ali nyi mbunge nawa já-ali", "Hanga akalizangeumwe nyi mukwo.", "Ku sambukila, eswe awahilile."]}, {"type": "chorus", "lines": ["Mwene, wahisa kulinunga achi.", "Hana chawana nyi kwa wahisa;", "Chiseke, ufulielo, kulihana;", "A ali wazange miaka yeswe."]}, {"type": "verse", "num": 2, "lines": ["Zuwo likwo nawa lia mwono,", "Wa ndako ya ufulielo nyi yitanga", "Ya mwono wakuwaha kulinunga nyi", "zango", "chikwete thachi, kulimbata chipema."]}, {"type": "verse", "num": 3, "lines": ["Mwene, walulieka chiseke", "Athu Je atwama hano hashi", "Kulinunga chacho cha uwahililo,", "Chizavu cha ana Je,", "Tuna sakwila, Uhenya!"]}]}, {"numero": 242, "titulo": "NGUNAZANGE KUYA KUZUWO", "blocos": [{"type": "verse", "num": 1, "lines": ["Ngunazange nguye kuzuwo", "Ngukatwame hamwe nyi mama,", "Mupema, kahomboka kakuhanjika", "Nyi uthu, nakumuzanga muze", "Mahanjika nyi zango,", "Kakungunehena chiseke mu mbunge."]}, {"type": "chorus", "lines": ["Hakuheta kuzuwo likulu cho chiseke", "Haku twama hakamwihi nyi mwe", "mama", "chiseke chika mutukevwa nyi mwe", "mama", "nguka mulweze lie zango liami!"]}, {"type": "verse", "num": 2, "lines": ["Mama hinguna mulilisa matangwa", "anji!", "Hinguna mumwesa lamba nyi", "Yinyengo.", "Mba hinanyingika yize angulingilile!", "Mungu mwita we ukonekeno."]}, {"type": "verse", "num": 3, "lines": ["Che chiseke mungu kevwa", "hakutwama nenyi", "Ngukamulweze athu mba aka wahilile;", "Nguka muzange mba neye aka wahilile.", "Nazanga mama nyi mwiva chiseke."]}]}, {"numero": 243, "titulo": "KUTWAMINA NYI MWONO YESU", "blocos": [{"type": "verse", "num": 1, "lines": ["Kutwama muli Yesu mwono upema,", "Kumuwahila muchifuchi mahuza,", "Tayiza linga chize atuma", "Jila ya chiseke chamwenemwene."]}, {"type": "chorus", "lines": ["Chilamwina chami mupema", "Nguli hane kuli Yena", "Hi unalingi chitapo", "Hakulusu, hali yetu nyi yami;", "Yena wika Mwene wami,", "Mungukwaha mbunge yami,", "Twama muli yami, a Yesu", "Nyi yami muli Yena."]}, {"type": "verse", "num": 2, "lines": ["Kutwama muli Yesu wangufilile,", "Wamwene lamba lia kulusu", "Zango lize nakumutayiza", "Ngumu kaule mungano nyi zango"]}, {"type": "verse", "num": 3, "lines": ["Kutwama nyi Yesu kweswe nguli;", "Ngulinge yeswe mamba mujina", "Lienyi.", "Pundu ku lamba yihungumiona", "Ku kulusu chichi kulinyenga."]}, {"type": "verse", "num": 4, "lines": ["Kutwama nyi Yesu Chilamwina", "chami", "Ngwendele mu pangu lia zango;", "Ngutwale anatoko ku ulamwino,", "Kupwa nyi mwono we mucheseko."]}]}, {"numero": 244, "titulo": "KUSAKWILA", "blocos": [{"type": "verse", "num": 1, "lines": ["Muze mungwi uluka zuwo", "liami litangu", "wo usona mungwiva mu mbunge", "yami", "nyi yeswe yize hiuna ngulingila yo.", "Kuli yena mama mungu sakwila,", "Ha ufuku mungu lemba nyi kwita,", "Muhela wami mu ulingumba nyi", "zango", "kulemba che nyi kwimba che", "chipema", "Chakunguhuzulula ku yikola", "Kuli yena mama mungu sakwila", "Amama yena zango liami!", "Hali yami wevwa lamba linji nyi yikola", "Keshika nakuzanga chinji,", "Hamuhela mungu susuminya hanga", "Nguhole,", "Wakwimba miaso yahuhumuka,", "Chichi kuvulama unene we unji", "Kulemba che chajika.", "Kuli yena mama mungu sakwila", "A mama zango liami", "Hali yami wevwa lamba linji nyi", "Yikola", "Keshika nakuzanga chinji."]}]}, {"numero": 245, "titulo": "KUMILIMO YA TATA", "blocos": [{"type": "verse", "num": 1, "lines": ["Kuwaha ku milimo ya mwe Yesu,", "Chiseke ami nawahilila", "Ku molu Jenyi nguse ko mwono", "Wami", "Nyi Yesu nawahilila!"]}, {"type": "chorus", "lines": ["Ku milimo ya Soma", "Yawana yami nguhane!", "Nguli nyi chiseke, cho kuwaha", "Cha Mwanangana."]}, {"type": "verse", "num": 2, "lines": ["Wanuke wami weswe kaunyingika", "Chiseke mangu wahisa", "Pangu lia Tangwa muchizulie", "mungwimba,", "ku milimo ya Soma."]}, {"type": "verse", "num": 3, "lines": ["Kuli Yena hinguna lilakenya", "Chiseke mangu wahisa", "Upite weswe ngu uhane chiseke", "Ku milimo ya Soma."]}]}, {"numero": 246, "titulo": "KUMBATA", "blocos": [{"type": "verse", "num": 1, "lines": ["Malamwina yoze matayiza liji Lienyi", "Kuliwana chipema chazango cha athu Je", "Hiwapwa muli akwa kulimbata", "Chawana chize chinatela."]}, {"type": "verse", "num": 2, "lines": ["Mu zango lize unendesa eswe", "hamwe", "mwono wa miaka mu upalika usandu", "nyi zango,", "kulinunga mu woma wa Zambi."]}, {"type": "verse", "num": 3, "lines": ["Tweya uhinge zuwo lio upwe", "Mwanangana", "Teulwila mbunge jo ku shimbi Ye", "ashishike.", "Alamwinenu kuyizezo yo;", "Wawahise nawa ku lamba."]}]}, {"numero": 247, "titulo": "KRISTU HAYA NYI KULULIEKELA YIHELA", "blocos": [{"type": "verse", "num": 1, "lines": ["Kristu halulieka yihela", "Mwilu kuzuwo lia Tata,", "Kuze haliapwila mutuheta", "Kuze shili kuyishiko", "Mwe mwilu, mwe mwilu,", "Kristu halulieka yihela", "Mwe mwilu, mwe mwilu;", "Mwilu, kwe kuzuwo lia Tata."]}, {"type": "verse", "num": 2, "lines": ["Kumutukapwa ko nyi Yesu,", "Nyi zango Lienyi lia miaka yeswe,", "Ku mazuwo waze apangu", "Ku sambukila ya Mwene wetu", "Mwe mwilu, mwe mwilu,", "Ku mutukapwa nyi Yesu", "Mwe mwilu, mwe mwilu,", "Kuzango Lienyi lia miaka."]}, {"type": "verse", "num": 3, "lines": ["Zuwo lia chiseke lia mwilu", "Upi kuchi kaheta ko", "Uhenya, usandu nyi chiseke", "Akwa ululi makanjila.", "Mwe mwilu, mwe mwilu,", "Ku mutukapwa nyi Yesu", "Mwe mwilu, mwe mwilu,", "Zowo lia chiseke lia mwilu."]}]}, {"numero": 248, "titulo": "KUSWAMA MULI KRISTU", "blocos": [{"type": "verse", "num": 1, "lines": ["Tweyenu akwa shili, ku", "Chitwamo cha Mwene", "Kristu maka nusweka", "Nyi munwiza kuli Yiye."]}, {"type": "chorus", "lines": ["Kristu makulamwina, yena", "Yena mukwa shili", "Kristu makulamwina,", "A Yena mukwa shili."]}, {"type": "verse", "num": 2, "lines": ["Wa mwangine manyinga je,", "Hanga utwazulwile", "Jila muyi tusongwela", "A Yena mukwa shili."]}, {"type": "verse", "num": 3, "lines": ["Yesu mwono, Yiye pangu,", "Chilamwina cha hashi,", "Yiye Yesu, a mukwa shili,", "Nyi mwiza kuli Yiye."]}, {"type": "verse", "num": 4, "lines": ["Tweyenu eswe, tweyenu,", "Nuli nunge nyi Kristu,", "Manukonekena eswe", "Nuka-ule pangu."]}]}, {"numero": 249, "titulo": "MBOLO YA MWONO", "blocos": [{"type": "verse", "num": 1, "lines": ["Yena wahele akwetu mbolo", "kukalunga", "two ngwehe yo, Yesu two ngwehe", "yo!", "Mungu yiwana mu maliji Je", "Mbolo ya ululi yingu tekule."]}, {"type": "verse", "num": 2, "lines": ["E! Ndo nyi yami mungu wahisa", "Ulumbunwiso wa lie zango Lie.", "Atata angwaha sakwila hayino mbolo,", "Sango lia ulamwino wa mwilu."]}, {"type": "verse", "num": 3, "lines": ["Ulamwino kuli yoze mata,", "Mungu zeyela kwe ku maliji Je.", "Nguli mwe mulelu two ngupulule", "Ndo mungu heta muzuwo lia mwilu."]}]}, {"numero": 250, "titulo": "LIPEMA PANGU LIA ZAMBI", "blocos": [{"type": "verse", "num": 1, "lines": ["Pangu lia uhenya wa Zambi,", "Lia zalisa to mbunge!", "Lia temuka kuhiana tangwa:", "Kristu nguli nenyi lume."]}, {"type": "chorus", "lines": ["Pangu lipema, pangu lia uhenya", "Pangu lia zango, tenu pangu", "Pangu lia uhenya, pangu lia mwilu,", "Lina kathuka mwe mwilu", "Kuli mukwa ufulielo wika;", "Pangu lipema lia Zambi."]}, {"type": "verse", "num": 2, "lines": ["Chiseke kuhalisa Yiye,", "Ukwete pangu lia Mwilu,", "Sambukila ya Mwilu yiye,", "Chawana Zambi ahana."]}, {"type": "verse", "num": 3, "lines": ["Mwono waha upema ahana,", "Akwete akwa Yesu;", "Au makaula Yesu haka mwihi", "Kuli Yiye nawana thachi."]}, {"type": "verse", "num": 4, "lines": ["Kutala mwono nyi ukule,", "Maka wana mukwa shili,", "Kutayiza Kristu, Pangu,", "Chawana cha Zambi wa zango."]}]}, {"numero": 251, "titulo": "MIASO YIPEMA", "blocos": [{"type": "verse", "num": 1, "lines": ["Miaso cho kuwaha anembi mwilu!", "Mwana chimwangi hahiluka!", "Kusuku tato hamusambilila", "Mwana yono aye azangile."]}, {"type": "chorus", "lines": ["Uhenya, uhenya, angelo memba!", "Uhenya, uhenya, tulialia mashika!", "Miaso ya usandu uhenya wa Zambi,", "Mumu umwe halilamwina!"]}, {"type": "verse", "num": 2, "lines": ["Ye miaso yipema anembi mwilu!", "Mumu liakushikisa umwe!", "Mukwa phami heza kuli Zambi yenyi", "Hahichika Chifuchi nyi shili."]}, {"type": "verse", "num": 3, "lines": ["Enwe nwalumuka, musono sehenu!", "Nyi kutakama ngwe angelo.", "Yenu nyi kawashi nukachambujole", "Ngwo halamwina mukwa shili."]}]}, {"numero": 252, "titulo": "YESU KASONGO KETU", "blocos": [{"type": "verse", "num": 1, "lines": ["Akweze ambujolenu pendelo", "lia Mwene", "lize Yesu asele muvungu lhino!", "Yenu eswe hanga Kristu aka-", "Nulamwine", "Hamwe nyi Yiye nuka kumbe yipi."]}, {"type": "chorus", "lines": ["Tuyenu nyi Yesu, kanda twivwa woma", "Tuyenu ku jita tupwenu nyi thachi!", "Nyi hamo lieswe tuyenu, ku-upi!", "Yesu mwe unapu kasongo ketu."]}, {"type": "verse", "num": 2, "lines": ["Twanuke ambujolenu Yesu", "Hanakumbu", "Munukapwa eswe kulumbu Lienyi!", "Liluliekenu eswe kanda nwivwa woma", "Tusendo tuyenu tulithachike."]}, {"type": "verse", "num": 3, "lines": ["Mweswewo mezako makevwa liji", "Lienyi", "Yesu manwaha thachi jakukumba!", "Masepha tuzeyenu hanga tushishike", "Yipangula makatwaha yamiaka."]}]}, {"numero": 253, "titulo": "NGULINGE NGWE DANYIYELE", "blocos": [{"type": "verse", "num": 1, "lines": ["Life kama ndumwami,", "Ngwe Ndanyiyele!", "Jikiza kulithachika", "Nyi Satana mupi."]}, {"type": "chorus", "lines": ["Linga ngwe Ndanyiyele!", "Wayila Zambi,", "Hakachi ka api, apema,", "Ukaye mwilu."]}, {"type": "verse", "num": 2, "lines": ["Aye wahamukine", "Yavumbika Soma!", "Kalikalile Yesu", "Yesu nyi Shimbi."]}, {"type": "verse", "num": 3, "lines": ["Kanda ulipikala;", "Hichika woma!", "Upi weswe mu-uchina", "Nyi wapwa nyi hamu!"]}, {"type": "verse", "num": 4, "lines": ["Nyi wafuliela Mwene,", "Milima pangu;", "Kwe kulutwe mukumba", "Mu jina lia Yesu."]}]}, {"numero": 254, "titulo": "KUKWAMBULWILA YESU", "blocos": [{"type": "verse", "num": 1, "lines": ["Yesu mungu mwambulwila yeswe", "Yize yili mu mbunge yami;", "Ye shili yami nyi lamba liami,", "Ndo Yeye wika mayiyula."]}, {"type": "chorus", "lines": ["Yena mwe Yesu, nakuzanga,", "Nguku lweze lie lamba liami;", "Ye shili, yami nyi lamba liami,", "Ndo Yiye wika mayiyula."]}, {"type": "verse", "num": 2, "lines": ["Yesu mungu mwambulwila yeswe;", "Yiye mwe sepa una hiana.", "Nyi mungu lemba, kuma mangwivwa;", "Ku lamba liami mayiyula."]}, {"type": "verse", "num": 3, "lines": ["Nyi mangu zeza kuchinatela", "Umwe Chikwashi mangu kwasa;", "Ndo Yesu, wika wakukumba,", "Yiye mahasa kungu pulwila."]}, {"type": "verse", "num": 4, "lines": ["Mujila yipi mangu zangisa,", "Angutwale mo ngupwe mupi;", "Alioze Yesu Yiye mupema,", "Yiye makwasa ngupuluke."]}]}, {"numero": 255, "titulo": "KUTHUMBA NYI KUCHA", "blocos": [{"type": "verse", "num": 1, "lines": ["Mbuto ana kongo hashi", "Muyisoka muyima mihuko", "Yitanga yetu e maliji", "Muyima milima haji pangu."]}, {"type": "chorus", "lines": ["Akweze yika nunachi?", "Ufwe nyi hanji mwono!", "Mihuko yize munucha", "Ku yeswe yize nwakuwile."]}, {"type": "verse", "num": 2, "lines": ["Ku mbuto yipi hanamwange,", "Macha shingano lume", "Tiliku ya ndjimi mupema", "Macha uwahiso upema."]}, {"type": "verse", "num": 3, "lines": ["Nyi kachi mukuwa musunya,", "Ufwe wamiaka mukawana;", "Alioze nyi Shipiritu mwenda", "Chiseke mu mwono wa miaka."]}, {"type": "verse", "num": 4, "lines": ["Mbuto yipema lima kanawa", "Uhomboloji nyi liji lia zango", "Mukawahilila shimbu yeswe", "Nyi Kristu Yesu Mwene."]}]}, {"numero": 256, "titulo": "ZAMBI MANGUKWASA", "blocos": [{"type": "verse", "num": 1, "lines": ["Kulamba linji, khole nyi yikola", "Hakungu kunjika nyi milima ya woma", "Nyi kupwa phundu ngwami kukumba", "muchiza", "chilakenyo chajika:", "“Zambi yami makangwaha”", "“Zambi yami makangwaha”", "“Zambi yami makangwaha”", "Chilakenyo chajika", "“Zambi yami makangwaha”"]}, {"type": "verse", "num": 2, "lines": ["Tujila a mwilu Zambi kakwatekula,", "Nyi zango lieswe kakufunga nyi-Enyi", "Kuli akwa kushishika chipema chichi-", "kahona", "wo umwenemwene:", "“Zambi yami makangwaha”", "“Zambi yami makangwaha”", "“Zambi yami makangwaha”", "Wo umwenemwene:", "“Zambi yami makangwaha”."]}, {"type": "verse", "num": 3, "lines": ["Nyi Satana mazanga kutuchikimisa", "Nyi woma wakutwiya ufulielo,", "Kechi kuhasa, ngwetu hiwetu nyi", "wambwika", "chilaknyo chajika", "“Zambi yami makangwaha”", "“Zambi yami makangwaha”", "“Zambi yami makangwaha”", "Chilakenyo chajika:", "“Zambi yami makangwaha”."]}, {"type": "verse", "num": 4, "lines": ["Thachi jetu Aye mahasa kujiwezela;", "Yesu matukwasa nyi kutwaha", "kukumba;", "kuli mukwa khole mupi makatusweka;", "nyi kutanda cheswe;", "“Zambi yami makangwaha”", "“Zambi yami makangwaha”", "“Zambi yami makangwaha”", "Nyi kutanda cheswe;", "“Zambi yami makangwaha”."]}, {"type": "verse", "num": 5, "lines": ["Ha ola yakusulako muze ufe", "hiwaheta,", "liji lia Mwene mulikatuvisa chiseke;", "chipwe mu ufwe hindu mungukemba", "nyi kujikiza phundu:", "“Zambi yami makangwaha”", "“Zambi yami makangwaha”", "“Zambi yami makangwaha”", "Nyi kujikiza phundu;", "“Zambi yami makangwaha”."]}]}, {"numero": 257, "titulo": "ZUWO", "blocos": [{"type": "verse", "num": 1, "lines": ["Zambi twehe zango muzuwo lietu", "Tuna liumbu kuvumbi Lienu,", "Nyi sambukila muyikalumbama", "Nyi zango litoma tho."]}, {"type": "verse", "num": 2, "lines": ["Mwe mu usoko wetu wazuwo.", "Ufulielo upwe thachi nyi pangu,", "Pwisa hano chitamba cisandu,", "Kuli Yena Zambi nyi Yesu."]}, {"type": "verse", "num": 3, "lines": ["Kuzuwo lia miaka yeswe,", "Mwilu kuchi mungu kapwa!", "Kuze mungu kemba uhaliso;", "Nyi zuwo liami nawa."]}]}, {"numero": 258, "titulo": "JINA LIA YESU LIAKUNEHA CHISEKE", "blocos": [{"type": "verse", "num": 1, "lines": ["Jina lia Yesu chiseke;", "Liakuneha sambukila", "Mwono nyi uwahililo", "Yesu nakuzanga"]}, {"type": "chorus", "lines": ["Kristu jina lilemu!", "Kristu mwe Chilamwina!", "Kristu kafunga Mupema,", "Nguli nyi we wa miaka!"]}, {"type": "verse", "num": 2, "lines": ["Ku mbunge yami a Chilamwina,", "Kwazala yikola yinji,", "Useko thachi nyi mwono", "Yesu ami nakuzanga."]}, {"type": "verse", "num": 3, "lines": ["Hinalela nyi yizezo,", "Kwoko Lie lingu takamise,", "Nguliumbe hanga ngulembe,", "Yesu ami nakuzanga."]}, {"type": "verse", "num": 4, "lines": ["Yesu Jina Lie lifumane,", "Wazanga yize yipema,", "Uli Kafunga wa mwilu", "Yesu ami nakuzanga."]}]}, {"numero": 259, "titulo": "ALULA UWAHISO", "blocos": [{"type": "verse", "num": 1, "lines": ["Nyi mu mwono himwanjila luyinda,", "Nyi chinyengo mwalula watokesa,", "Alula nawa yiwape Yenyi yinji,", "Mukakomoka yize Zambi alinga."]}, {"type": "chorus", "lines": ["Alula uwahiso ungahi", "Uze Zambi hana kwehe wo;", "Umwe, umwe, alula kanawa,", "Mukakomoka Zambi hana kwehe"]}, {"type": "verse", "num": 2, "lines": ["Ye yikola nyi chinyengo unevu?", "Kulusu unevu kulina leme?", "Alula yiwape kanda ukhakhajana,", "Mwimba mwaso matangwa", "papalika."]}, {"type": "verse", "num": 3, "lines": ["Muze mumona upite wa akwenu,", "Euluka uze akulakenyene;", "Upite wa hashi uchi kulanda", "Zuwo lia mwilu muze mukatwama."]}, {"type": "verse", "num": 4, "lines": ["Kuzwela che chinaleme nyi chilelu", "Kanda uhonga Zambi kwilu kwali;", "Aye makukwasa ku upi weswe,", "Makulimbejeka ndo kwe kusongo."]}]}, {"numero": 260, "titulo": "KANDA UTAYIZA", "blocos": [{"type": "verse", "num": 1, "lines": ["Kanda utayiza yinyengo", "Mukachi ka mbunge ye;", "Jikijila mwe Longeshi,", "Mukaula nyi thachi"]}, {"type": "chorus", "lines": ["Kanda utayiza", "Kanda utayiza", "Yikola hanji chinyengo", "Yikajime zango lie!", "Kanda uchikima", "Chipwe kulihana!", "Kulamba lie euluka", "Kristu mwe Chilamwina che."]}, {"type": "verse", "num": 2, "lines": ["Hanji mukwiza yinyengo", "Muyi kunehena woma,", "Kanda uvulama Kristu", "Chikwashi che munene."]}, {"type": "verse", "num": 3, "lines": ["Hichika yinyengo yeswe,", "Chipwe kukhakhajana", "Sambukila nyi chiseke", "Makakwaha Mwene We."]}]}, {"numero": 261, "titulo": "CHISHINA CHA THACHI", "blocos": [{"type": "verse", "num": 1, "lines": ["Chishina cha jika liji lie lisandu,", "Kulimika cha akwa ufulielo nyi", "lamba!", "Yilakenyo yinji nyi kulihumikiza,", "Yiya mayihana nyi hi Mwene ko?", "Yiya mayihana nyi hi Mwene ko?"]}, {"type": "verse", "num": 2, "lines": ["Nyi makusanyika upalike mu meya,", "Musuku autenu nyi luyinda nyi lamba", "Kanda uchikima hamwe nyi yena", "Mungu kapwa,", "Ku uhenya wamiaka muyikahwa,", "Ku uhenya wamiaka muyikahwa."]}, {"type": "verse", "num": 3, "lines": ["Nyi jila ye ndusu ha milengi", "ya kahia", "Ha kahia kalekwoka kanda wivwa", "woma!", "Kahia mukocha wika yiswaswa", "Ulu mukahia ulemu muliokesa", "Ulu mukahia ulemu muliokesa."]}, {"type": "verse", "num": 4, "lines": ["Eswe mafuphila muli Yami uhwimino", "Jikijila mu manyinga a Mwana Zambi", "Chichi kalikala jamina kusambukila", "Hapwila mujila muwahililo wa mwilu", "Hapwila mujila muwahililo wa mwilu."]}]}, {"numero": 262, "titulo": "KULEMBA CHA KULIHANA", "blocos": [{"type": "verse", "num": 1, "lines": ["Ulemu unji unangwehe, ukwa", "unji upi", "Ngulihumikize kulamba, nyi", "kulitomesa,", "Ufulielo unji muli Longeshi, kuli", "thumbika chinji", "kuwaha chinji hakumulingila,", "kusakwila chinji hakulemba."]}, {"type": "verse", "num": 2, "lines": ["Ngupwise mukwa ululi, mukwa", "mana a Mwene", "Ngukajikize mu milimo, nyi thachi", "Jindji", "Nyi kululama ku mwono, chinyengo", "haku vulumuna;", "Mwana wakwononoka, phundu", "Kuzanga."]}, {"type": "verse", "num": 3, "lines": ["Ngutomese chinji, Musandu muli", "Yesu,", "Ngutumine chinji, sambukila yinji", "ha kulusu,", "katalatala chipema, milimo yinji hano", "hina zanga malilu, mwono unji muli", "yena."]}]}, {"numero": 263, "titulo": "TWEYENU YENU AKWA YINYENGO", "blocos": [{"type": "verse", "num": 1, "lines": ["Mwono hijakuhwa Zambi Tata", "Chihomboloji", "Ha keke Yenyi zango, kali nyi", "Unene", "Wakuku pulula ku upi akwehe", "uwahililo", "Kanda ushimbula Yesu makusweka."]}, {"type": "verse", "num": 2, "lines": ["A ndumwami woma we unji", "Mba euluka Zambi wakukupulula;", "Aye makupulula kukulinyenga che,", "Yiye wika mauka yikola ye."]}, {"type": "verse", "num": 3, "lines": ["Munyonga chinji ku mwono we", "Fupa Chilamwina che Yesu Kristu;", "Aye nyi zango linji, kana kusanyika", "Kristu makwasa kumbata kulusu lie."]}, {"type": "verse", "num": 4, "lines": ["Tala! Kristu matulembejeka!", "Mumu kuyinyengo Zambi mathuthusula", "Kakutekula nyi-Enyi;", "Aye katuzanga matupulula."]}]}, {"numero": 264, "titulo": "NJISA PANGU LIA MWILU", "blocos": [{"type": "verse", "num": 1, "lines": ["Musono ena unazange ulamwino?", "Zango lie liakulichiza milima?", "Azululu lie pito lia mbunge ye!", "Njisa pangu lia mwilu."]}, {"type": "chorus", "lines": ["Njisa pangu lia mwilu!", "Njisa pangu lia mwilu!", "Azulula lie pito lia mbunge ye.", "Njisa pangu lia mwilu."]}, {"type": "verse", "num": 2, "lines": ["Kristu pangu lia mwilu unazange", "Nyi mumwanga ye milima ya shili,", "Nyi mutemwina jila ye nyi mbunge!", "Njisa pangu lia mwilu."]}, {"type": "verse", "num": 3, "lines": ["Chiseke chinji hakwenda mu pangu?", "Muyi neha mwono nyi sambukila!", "Tayizako Chilamwina che Yesu!", "Njisa pangu lia mwilu."]}]}, {"numero": 265, "titulo": "ZAMBI MAKA KUFUNGA", "blocos": [{"type": "verse", "num": 1, "lines": ["Ena mbunge yina nenganyana,", "Zambi makufunga;", "Makufuka kwoko Lienyi,", "Muli kakufunga."]}, {"type": "chorus", "lines": ["Zambi makufunga", "Tangwa nyi tangwa makwaha;", "Chochene nyi makufunga,", "Zambi maku kwasa."]}, {"type": "verse", "num": 2, "lines": ["Ku yikola nyi yeseko,", "Zambi maku kwasa;", "Makukwasa mapulula,", "Mba maka kufunga."]}, {"type": "verse", "num": 3, "lines": ["Zambi meseka ufulielo", "Hindu maakukwasa;", "Zango lie kumaliokesa,", "Yiye maka kufunga"]}, {"type": "verse", "num": 4, "lines": ["Cheswe mufupa makwaha,", "Yiye makufunga a!", "Makukwata nyi moko Jenyi", "Mumu maka kufunga."]}]}, {"numero": 266, "titulo": "YENA HIJAKUHWA TWEYA", "blocos": [{"type": "verse", "num": 1, "lines": ["Tweya mwono hijakwa uli nyi ikola", "Sako ha moko ja mwene yihungumiona", "Kuli Kristu lamba lie", "Mwenamo ena muwanyina uhwimino."]}, {"type": "verse", "num": 2, "lines": ["Yinyengo nyi chikhulikhuli yilweze", "Mwene;", "Kanda nwivwa oma kumunehena", "yeswe;", "Upi mu ukwenyeka maku uka wo", "yesu kana zange kukukolesa."]}, {"type": "verse", "num": 3, "lines": ["Nyi hiwata kulembejeka achi", "Twala lusango wasambukila nyi", "ukonekeno", "Ku miono ya yinyengo anapinji nyi", "misongo;", "Neha akwa yinyengo kwiliato ya", "Mwene."]}]}, {"numero": 267, "titulo": "HAKAMWIHI NYI ZAMBI", "blocos": [{"type": "verse", "num": 1, "lines": ["Kuli sambukila yinji", "Haka mwihi nyi Zambi", "Shili kuyishiko nawa", "Haka mwihi nyi Zambi."]}, {"type": "chorus", "lines": ["Yesu Chilamwina chami,", "Ye mbolo ya mwilu.", "Ngukwate kama mu kwoko", "Nyi mbunge ya Zambi."]}, {"type": "verse", "num": 2, "lines": ["Kuli chiseke nyi pangu", "Haka mwihi nyi Zambi", "Nguwane ko mwene Yesu", "Haka mwihi nyi Zambi."]}, {"type": "verse", "num": 3, "lines": ["Nguwane ko uhwimino", "Hakamwihi nyi Zambi", "Ngu tambule ulamwino", "Haka mwihi nyi Zambi."]}]}, {"numero": 268, "titulo": "USONA", "blocos": [{"type": "verse", "num": 1, "lines": ["Chifuchi chipema kusuku,", "Nanenganyana;", "Ngnevu usona wa Yesu;", "Shimbu yika nguye?", "Tujila, yitemo yipema,", "Yangulalula.", "Milalu ya hashi nyi chimwe;", "Chazangile hashi."]}, {"type": "verse", "num": 2, "lines": ["Yesu hana ngwehe chilakenyo,", "Mangwijila;", "Mbunge kuyinali phupwisa,", "Nguhumuke nguye.", "Shili yami yoka naye,", "Yangu layisa,", "Manyinga Je angutomese,", "Hanga nguye Mwilu."]}, {"type": "verse", "num": 3, "lines": ["Mwana malilila ku mahio,", "Nguye kwami;", "Kajila matutumbila chaswa,", "Nguhumukine mwilu.", "Kwiza Chenyi umwenemwene,", "Kwiji lie tangwa", "Nguna mutwaminyina lume;", "Ngukaye Nenyi mwilu."]}]}, {"numero": 269, "titulo": "TANGWA HILIATOKA", "blocos": [{"type": "verse", "num": 1, "lines": ["Tangwa muze mulitoka.", "Ufuku hiweza;", "Yizulie hiya kundama", "Tunayimono."]}, {"type": "verse", "num": 2, "lines": ["Akwa kwenda hijahwa,", "Twehe uhwimino a Tata;", "Hakufunga Che Yena,", "Woma wakuhi."]}, {"type": "verse", "num": 3, "lines": ["Hashimbu ya ufuku,", "Tufuke maphulwa Je;", "Mwangelo We angufunge", "Ndo mukucha kweswe."]}]}, {"numero": 270, "titulo": "TWEYA KULI YESU", "blocos": [{"type": "verse", "num": 1, "lines": ["Yesu ku-uhenya, nyi uzalo wa ululi,", "KanapuYiye hako liami;", "Mahakwila nyi kulamwina.", "Nyi yena haku lamwina?"]}, {"type": "chorus", "lines": ["Tweya kuli Yesu!", "Tweya kuli Yesu!", "Maku wahisa", "Muwana kulusu!"]}, {"type": "verse", "num": 2, "lines": ["Nguli ye sambukila ngwe lwiji;", "Sambukila ya shima lia Mwilu;", "Zambi hangwaha yo, hakutayiza", "Yesu.", "Kanda uchipwa nyi sambukila ya", "Mwilu?"]}, {"type": "verse", "num": 3, "lines": ["Uzalo utoma hinaukosa.", "Mu manyinga atoma a Khule yami;", "Akwa-ufulielo a Kristu, Zambi", "makula;", "Nyi yena nawa nyi wafuliela!"]}, {"type": "verse", "num": 4, "lines": ["Zuwo nguli nalio nyi waze ana-", "lamwina,", "Kristu ana ngululiekela mu limbo lia", "Zambi;", "Ku muchi ufwe, chinyengo nyi yikola.", "Nyi yena mukapwa nyi zuwo Mwilu."]}]}, {"numero": 271, "titulo": "UHENYA WAHIANA", "blocos": [{"type": "verse", "num": 1, "lines": ["Hingu nevu lufuma wa limbo,", "Liathunga mukachi ka pangu,", "Angelo nyi uhenya wa Soma,", "Memba miaso, ya Kristu Yesu,", "Mungwivwa chiseke", "Ku meso ja Soma", "Ngukapwe nyi uhenya wahiana", "Hakumona waze nalamwinyine!"]}, {"type": "verse", "num": 2, "lines": ["Hingunevu Chifuchi chipema.", "Cha mingulunga nyi mihwahwa,", "Cha usaki yitemo yipema.", "Nyi lwiji mukachi kawande:", "Mwono wa miaka yeswe", "Kukumba nyi chiseke!", "Sambukila yinji mangu kevwa", "Hakumona waze nalamwinyine!"]}, {"type": "verse", "num": 3, "lines": ["Chiseke cha mihuko nyi yitemo,", "Nyi mazuwo ja olu yipema.", "Chiseke kuchishi ye yikola", "Makevwa waze anguhichikile", "Welo ami mungukevwa", "Chiseke chahina", "Muze Kristu maka ngutayiza", "Nguka mone waze nalamwinyine."]}]}, {"numero": 272, "titulo": "SAMBUKILA YESWE", "blocos": [{"type": "verse", "num": 1, "lines": ["Sambukila yipema", "Chifuchi cha milima pwi", "Yesu hangukosa pe", "Ku tununu twa shili."]}, {"type": "verse", "num": 2, "lines": ["Sambukila yipema.", "Ku kuli tachika", "Alioze muli Yesu", "Kumulingila uhwimino."]}, {"type": "verse", "num": 3, "lines": ["Sambukila yipema", "Nyi kusuku nguli no", "Alioze kwali umwe.", "Au matufunga mwe Zambi."]}, {"type": "verse", "num": 4, "lines": ["Hikwahwa lume", "Kulinyenga hichahwa", "Sambukila wika yiliko", "Hamwe nyi Mwene. Amen."]}]}, {"numero": 273, "titulo": "HWIMA NYI SAMBUKILA", "blocos": [{"type": "verse", "num": 1, "lines": ["Hwima nyi sambukila mu upeme", "khulu.", "Ngufunge a Tata ku yeswe muyiza,", "Aye nyi limwe tangwa aliongele", "Yika tunalilila upi wa hashi,", "Hwima nyi sambukila."]}, {"type": "verse", "num": 2, "lines": ["Milimo ye muchifuchi hiyahwa,", "Kwilu mukapwa nyi chipangula", "chipema", "Hiwatusuka nyi ayo nyi kumisongo", "Kuze muka hwimina woma kha", "Hwima nyi sambukila."]}, {"type": "verse", "num": 3, "lines": ["Hwima nyi sambukila wawawa sepa", "Ndo muze Yesu makatwijila;", "Akwetu kuwaha! Kuyuka chika!", "Hwima mu sambukila."]}]}, {"numero": 274, "titulo": "KUWAHA CHINJI", "blocos": [{"type": "verse", "num": 1, "lines": ["Chipwe kachitope lusona,", "Mwene ngwenyi evenu!", "Je shimbi ja chiseke", "Kajalumwine."]}, {"type": "chorus", "lines": ["Kawaha chinji,", "Kawaha chinji,", "Wakufunga shimbi,", "Kawaha chinji, kawaha chinji.", "Maka kusanyika?", "Yoze mahalisa shimbi, ha zango", "Yoze mafunga nyi zango", "Mahalisa Mwene Yesu", "Ma mwaha chawana."]}, {"type": "verse", "num": 2, "lines": ["Mafunga je shimbi Jenyi", "Mendela mu pangu;", "Makendela mu tapalo lia-olu,", "Maka mona Yesu."]}, {"type": "verse", "num": 3, "lines": ["Mukapwa ko nawa nyi yena?", "Ku chiseke chacho?", "Funga nawa je shimbi Jenyi,", "Mufuliele wika."]}]}, {"numero": 275, "titulo": "KULINUNGA NYI KWOKO LIENYI", "blocos": [{"type": "verse", "num": 1, "lines": ["Matangwa api waze chamwene,", "Huma lia mwe Chilamwina;", "Ufuku mungu mona lie pangu,", "Tulinunge nyi, kwoko Lie."]}, {"type": "chorus", "lines": ["Kulinunga nyi kwoko Lie!", "Kulinunga nyi kwoko Lie!", "Kuli unene mu-ukumba yizezo", "Tulinunge nyi kwoko Lie."]}, {"type": "verse", "num": 2, "lines": ["Nyi mujinguhwa ungeji uno,", "Mukwiza chimwe chizezo,", "Mungwivwa thachi mujingu kwasa", "Kulinunga nyi kwoko Lie."]}, {"type": "verse", "num": 3, "lines": ["Nyi kachi ye jila muyila pwi,", "Chamwene jila Munguya,", "Thachi mujiza nyi ufulielo,", "Kulinunga nyi kwoko Lie."]}, {"type": "verse", "num": 4, "lines": ["Muze ha shimbu yakusula ko,", "Muyikeza hali yami,", "Mbunge muyili humikiza", "Kulinunga nyi kwoko Lie."]}]}, {"numero": 276, "titulo": "KECHI KUNGUHICHIKA", "blocos": [{"type": "verse", "num": 1, "lines": ["Muchifuchi chino", "Chichi kuhasa kwenda;", "Chaha shile kulifunga,", "Munguya nyi Yesu,", "Maya nyi yami,", "Kazanga kungu lamwina;", "Aye kana lilakenya", "Kechi kangu hichika."]}, {"type": "chorus", "lines": ["Kechi kangu hichika!", "Kechi kangu hichika!", "Mumu kana lilakenya", "Kechikangu hichika. (ka-ali)"]}, {"type": "verse", "num": 2, "lines": ["Akwa khole ngulino", "Menyeka mwono wami;", "Nyi mungweseka kwenda wika,", "Yika mungu linga?", "Nyi Yesu mangu kwasa,", "Munguya nyi sambukila,", "Aye kana lilakenya!", "Kechi kangu hichika!"]}, {"type": "verse", "num": 3, "lines": ["Ku yinyengo ya mwono,", "Ku yikola nyi lamba.", "Ku milimo ya tangwa,", "Nyi mukwiza yizezo", "Kristu nyi yami ali,", "Angulamwine.", "Mumu kana lilakenya,", "Kechi kangu hichika!"]}]}, {"numero": 277, "titulo": "KULEMBA CHAMI", "blocos": [{"type": "verse", "num": 1, "lines": ["Ngu kwite, a Yesu, mungulemba,", "Yena unamono mwe mu mbunge,", "Nguneza ngu Wayile", "Chawana ngunechi;", "Hanga unguwahise,", "Zambi yami!"]}, {"type": "verse", "num": 2, "lines": ["Ngu kwite, a Yesu, hakulemba,", "Shili nguli nayo,", "Ngukonekene;", "Pwako Mwene wami", "Nhguli mukwa shili,", "Nguwehe ha zango Lie", "Ukonekeno!"]}, {"type": "verse", "num": 3, "lines": ["Ngu kwite, a Yesu hakulemba,", "Yena waku kwasa ha lie lamba;", "Tweya ngu lembejeke!", "Unguzalise yena,", "Hanga ngujikize,", "Mwene wami!"]}, {"type": "verse", "num": 4, "lines": ["Eva, kulemba achi,", "Chilamwina!", "Cha uhomboloji,", "Nguna kulembe;", "Uli Hako liami,", "Mwanangana Chilamwina,", "Mungu yuka!"]}]}, {"numero": 278, "titulo": "KUTAMBWISA SAMBATA", "blocos": [{"type": "verse", "num": 1, "lines": ["Kuchi munguli sangala yami", "Ha tangwa lia Mwene", "Hali yetu ana Jenyi", "Hituna hichika yeswe kunyima", "Muze tangwa mulinjila lieswe", "Tufupenu Zambi tumuhalise."]}, {"type": "verse", "num": 2, "lines": ["Nguna wahilila musono ngunayi", "Ku shikwola ya Mwene", "Kuze Munguya ngukatwame nyi", "Zambi", "Mungu kemba uhaliso Wenyi", "Chingoloshi mungu talatala", "Milimo ya Zambi yami", "Munguka mona uhenya unji", "Muyitulweza zango Lienyi."]}, {"type": "verse", "num": 3, "lines": ["Muze mulitoka tangwa", "Zango mulizala mbunge", "Kuli Zambi Munguya nyi uhaliso", "Nyi kusakwila chinji", "Mungu mushika nyi usona", "Ha tangwa lia Mwene", "Mumu hatangwa eswe Je", "Sambata ye yahina."]}]}, {"numero": 279, "titulo": "NGU UKE MESO MBA", "blocos": [{"type": "verse", "num": 1, "lines": ["Ngu uke meso mba ngumone", "Upeme uze mukangwaha;", "Nguse hamoko unene We", "Ngukasulule mba ngupuluke", "Mba nguhole kulungunga", "Ndo mukangu kumbulula", "Ngujikule ngwehe pangu", "Yesu mupema…"]}, {"type": "verse", "num": 2, "lines": ["Ngujikule matwi hanga ngwivwe", "Ye yipema yize mungwaha", "Ngumone upite uze mwopa", "Mba nguhole kulungunga", "Ndo mukangu kumbulula", "Ngujikule ngwehe pangu", "Yesu mupema…"]}, {"type": "verse", "num": 3, "lines": ["Ngupakule lie kanwa mba ngwimbe", "Maliji aha a mwono", "Ngutusule we mwono mba ngwende", "Ngutwale sambukila kuli athu", "Mba nguhole kulungunga", "Ndo mukangu kumbulula", "Ngujikule ngwehe pangu", "Yesu mupema…"]}]}, {"numero": 280, "titulo": "KULEMBA SHIMBU YESWE", "blocos": [{"type": "verse", "num": 1, "lines": ["Kutala kuli Zambi chimene", "Nyi hakuzunduka cha tangwa.", "Kuhanjika Nenyi chingoloshi", "Ena lemba ye shimbu yeswe."]}, {"type": "verse", "num": 2, "lines": ["Chimene makukumbulula", "Nyi hakuzunduka cha Tangwa.", "Makukumbulula chingoloshi.", "Maka kwaha sambukila."]}, {"type": "verse", "num": 3, "lines": ["Yesu nyi meza hatchimene", "Nyi hakuzunduka cha Tangwa.", "Yesu nyi meza chingoloshi,", "Uli phundu mwilu mwoya?"]}]}, {"numero": 281, "titulo": "HAPWILA MUKA CHINYINGIKA", "blocos": [{"type": "verse", "num": 1, "lines": ["Yiteli ya mwono yinaleme?", "Malelwa kana kujikinyina?", "Mwene kuku lamwina yika", "Kasula mukatchinyingika."]}, {"type": "chorus", "lines": ["Akwetu mba munu katchinyingika", "Chochene mba mukanyingika!", "Chiteli yika chinachina kulela,", "Kumu chikaku lumbunuka."]}, {"type": "verse", "num": 2, "lines": ["Ulinenyi ketchi kuhasa kwivwa", "Miteto ya mwe mu mbunge ye?", "Jikijila sepa lie wa phundu,", "Yesu mevwa che kulemba che."]}, {"type": "verse", "num": 3, "lines": ["Muze mukaheta mwe mulimbo", "Ungeji we mu-ukasula", "Mukamona ngwe kwoko lienyi lie", "Lia songwela ye yiliato ye."]}]}, {"numero": 282, "titulo": "KULEMBA CHA CHINGOLOSHI", "blocos": [{"type": "verse", "num": 1, "lines": ["Uwape wa chingoloshi", "Wize mba hanga tupombe,", "Tuna litayila kuhona,", "Tupulule kama."]}, {"type": "verse", "num": 2, "lines": ["Nyi akwa khole matujinga,", "Matukonga mivu yo,", "Angelo Je kumatufunga,", "Mba mutusehejela."]}, {"type": "verse", "num": 3, "lines": ["Nyi kwatoka kweza tchishika", "Ena haka mwihi tuli nenyi;", "Kanda jikuhwa hi utwetche", "Ha moko ja Satana."]}, {"type": "verse", "num": 4, "lines": ["Auno ufuku nyi hinafwa", "Hiwa twaha thulo ayena", "Hikweza uhenya We", "Mba himutu hinduka."]}]}, {"numero": 283, "titulo": "KRISTU KECHI KUSWILIKA KWIZA", "blocos": [{"type": "verse", "num": 1, "lines": ["Kristu mwilu kumeza,", "Watushikile ngwenyi mungwiza;", "Chiseke chinji nyi we uhenya,", "Muze Yesu makeza!"]}, {"type": "chorus", "lines": ["Kristu kumeza; kumeza nawa,", "Kristu kumeza nawa!", "Chiseke chinji nyi we uhenya,", "Muze Yesu makeza!"]}, {"type": "verse", "num": 2, "lines": ["Hapwila afu mahinduka,", "Alizangile makaliwana.", "Eswe nyi chiseke maya mwilu,", "Muze Yesu makeza."]}, {"type": "verse", "num": 3, "lines": ["Chifuchi muchikapema,", "Mumu Satana makamu kasa,", "Yeswe yipi kumuyi sala,", "Muze Yesu makeza."]}, {"type": "verse", "num": 4, "lines": ["Kristu kechi kashimbula", "Yiya makapwa ha kwiza Chenyi!", "Chiseke chinji hakuya Nenyi,", "Muze Yesu makeza."]}]}, {"numero": 284, "titulo": "YIHUHUMUKE", "blocos": [{"type": "verse", "num": 1, "lines": ["Yinyengo kuhanjika muyizulie,", "Shimbu tunayi kuzuwo;", "Khuma yizulie yahiana muyitufuka.", "Twi-uluke umwenemwene Wenyi."]}, {"type": "chorus", "lines": ["Hali pangu milima muyichina", "Ku pangu lia tangwa chihuhumuke.", "Tala kutangwa miteto yitepuluke,", "Muze mungumona pangu mujila."]}, {"type": "verse", "num": 2, "lines": ["Pangu lia ululi mulitemuna mujila", "Chizulie tuna chimono chinayi", "Tuyenu kulutwe nyi kutala Yiye", "Mutumona chizulie hichaya."]}, {"type": "verse", "num": 3, "lines": ["Nyi mbunge ye yinachikima", "Euluka pangu lia sala kunyima", "Tala kuli Kristu mumu jinakuhu", "Pangu Lienyi mulikutemwina."]}, {"type": "verse", "num": 4, "lines": ["Tuyenu eswe tukaule Kristu", "Yiye pangu lia Tangwa mulitemuka", "Muyizulie ya mwono uno", "Malamwina,", "Nyi hamu tukaulenu Yesu."]}]}, {"numero": 285, "titulo": "NGUSONGWELE CHILAMWINA CHAMI", "blocos": [{"type": "verse", "num": 1, "lines": ["Ngutwale Chilamwina,", "Shimbu yeswe ngu twale;", "Pundu ngunajikiza,", "Ngwende kama nyi Yena."]}, {"type": "chorus", "lines": ["Ngu songwele", "Chilamwina ngu twale;", "Nyi zango nyi keke ye", "Chilamwina ngutwale."]}, {"type": "verse", "num": 2, "lines": ["Nyi kukujikijila,", "Hiwa ngukwashila ho.", "Ngutwale Chilamwina", "Chifuchi cha mahuza!"]}, {"type": "verse", "num": 3, "lines": ["Yena mungu songwela,", "Ndo mwono mu-usula,", "Yesu makangwijila", "Nguka twame mu pangu."]}]}, {"numero": 286, "titulo": "NGUNA FULIELA", "blocos": [{"type": "verse", "num": 1, "lines": ["Zambi nguna kwehe moko", "Mumu Yena wika,", "Chiswamo muhasa kungusweka", "Ha uno ufuku nguli."]}, {"type": "chorus", "lines": ["Yesu nguna kufuliela", "Mumu lia kulusu", "Manyinga yangu mwanganyina", "Mangunjisa mwilu."]}, {"type": "verse", "num": 2, "lines": ["Kristu nguna mufuliela", "Mungupwa nyi yeswe;", "Mungwendela mujila ye,", "Ngupwe nyi unene We."]}, {"type": "verse", "num": 3, "lines": ["A Yesu kaputhu ketu", "Yena nguna tale!", "Nguvwile kama keke ye", "Nguka wahilile."]}]}, {"numero": 287, "titulo": "YESU HAKU LAMWINA", "blocos": [{"type": "verse", "num": 1, "lines": ["Hangulamwina Yesu Kristu", "Nguli nyi sambukila yinji;", "Kulinunga nyi Yiye", "Yinyengo yeswe hiyahwa", "Yangwaha umwenemwene.", "Ha ulamwino wami", "Changwaha zango linji", "Chiseke chahiana yeswe."]}, {"type": "chorus", "lines": ["Kristu hangulamwina", "Chiseke nguli nacho;", "Nguli nunge Nenyi,", "Yinyengo yeswe hiyahwa."]}, {"type": "verse", "num": 2, "lines": ["Kristu Yiye mwono wami", "Shima lia zango", "Machiza upi weswe", "Yinyengo nyi missongo", "Chipwe mangweseka", "Muchingupwila chashi", "Chipwe mukulila", "Makusumuna soji lieswe."]}, {"type": "verse", "num": 3, "lines": ["Mungu palika ufuku", "Nyi Yiye woma kha?", "Ndo kuthuhuka tangwa", "Mwalwa tangwa lieswe", "Chiseke chinji ngunevu", "Hakumuhulikila", "Mu uhenya nyi Yesu.", "Mulimbo lia henyama"]}]}, {"numero": 288, "titulo": "MUSHI LIA MAPULWA JENYI", "blocos": [{"type": "verse", "num": 1, "lines": ["Mu maphulwa Jenyi nguna hwimina", "Chipwe ufuku nguna jikiza;", "Mu maphulwa Jenyi nguna swame", "Hangupulula hinapwa Mwanenyi."]}, {"type": "chorus", "lines": ["Ngukahwime ngukawime,", "Mushi lia maphulwa Jenyi", "Mu uhwimino Wenyi nguka wane", "Sambukila ya shimbu yeswe."]}, {"type": "verse", "num": 2, "lines": ["Mu mapulwa Jenyi mungu", "chinyina", "Mbunge yami yikawimine mo;", "Chifuchi kucha ngulamwinyine", "Maphulwa Jenyi maka ngupulula."]}, {"type": "verse", "num": 3, "lines": ["Mu maphulwa Jenyi yilakenyo", "Mwe mungu tenga mu-uchinyino;", "Ukevwe Yesu hangupulula", "Nyi chimwe muchinguvisa woma."]}]}, {"numero": 289, "titulo": "KUTANGA CHIMENE", "blocos": [{"type": "verse", "num": 1, "lines": ["Chimenemene chipwe lilu linaholo", "Linambulula kuhola cha tangwa,", "Tala lemba, a mbunge yikehe", "Ukumbe yihungumiona ye."]}, {"type": "chorus", "lines": ["Chimenemene, lemba lume,", "Kulayilila lemba."]}, {"type": "verse", "num": 2, "lines": ["Lie tangwa lieswe echenu kuzwela,", "Muchikwika liji lia Mwene", "Liselenu kulemba, likalenu jita", "Twama nyi Mwene musambukila."]}, {"type": "verse", "num": 3, "lines": ["Hakusulisa milimo ya tangwa", "Euluka uwahiso wa kwilu", "Chiseke, yinyengo yilweze Mwene.", "Sako lamba lieswe Yiye."]}, {"type": "verse", "num": 4, "lines": ["kanda uhola lemba shimbu yeswe,", "Tala mukwa khole kaholele.", "Ndo kuli nunga nyi Kristu wika", "Chocho mukwa kufwa maya mwilu."]}]}, {"numero": 290, "titulo": "KULINGA", "blocos": [{"type": "verse", "num": 1, "lines": ["Hapwila Yesu nanyingika;", "Mumu ha zango Lie,", "Mumu Ena hiwa ngulamwina!", "Hanga nguku halise."]}, {"type": "chorus", "lines": ["Yesu Yena Chilamwina chami,", "Mumu nguli nyi sambukila;", "Yesu Yena mungu halisa!", "Yena wangwaha yeswe."]}, {"type": "verse", "num": 2, "lines": ["Chishi kuwana uhwimino,", "Mumu nguli nyi che chimwe;", "Alioze Kristu yangwi-uluka,", "Yangu lamwina chawana."]}, {"type": "verse", "num": 3, "lines": ["Akwetu tumu halisenu.", "Chilamwina munene;", "Kristu Yiye watwaha yeswe,", "Chipwe tuli akwa shili."]}, {"type": "verse", "num": 4, "lines": ["Yena wika mungu halisa,", "Kristu, Mwene wami;", "Mwanangana nawa Profeta,", "Chilamwina cha hashi."]}]}, {"numero": 291, "titulo": "KULEMBA CHA CHINGOLOSHI", "blocos": [{"type": "verse", "num": 1, "lines": ["Nyi kachi nasanga umwe mukhuta,", "Nyi namuphiangula mujila yipema,", "Nyi nendelanga mujila yipi,", "Mwene, ngu konekene!"]}, {"type": "verse", "num": 2, "lines": ["Nyi nahanjikanga yimwe yipi;", "Nyi nawa naminanga umwe kulia,", "Hakwivwa woma ngwami muchihwa,", "Mwene, ngu konekene!"]}, {"type": "verse", "num": 3, "lines": ["Nyi napwanga muthu umwe mupi,", "Nyi kachi nafupanga uchinyino,", "Shimbu liakupwa swalale mupema,", "Mwene, ngu konekene!"]}, {"type": "verse", "num": 4, "lines": ["Ngu konekene ku upi wami,", "Nali tayila nyi uze wasala,", "Ngu funge kama kuli athu Je,", "A Mwene, amem!"]}]}, {"numero": 292, "titulo": "UFULIELO HA WIULUKA", "blocos": [{"type": "verse", "num": 1, "lines": ["Zambi kana lakenya kuhana yinji", "Kuli yoze meta nyi ufulielo;", "Kumbulwilo nyi mamujikijila.", "Yesu matala ufulielo."]}, {"type": "chorus", "lines": ["Yesu matala ufulielo we;", "Yesu makwaha yize alilakenya,", "Mamona mwe mu mbunge", "Mba mevwa che kulemba;", "Yesu mafeta ufulielo."]}, {"type": "verse", "num": 2, "lines": ["Zambi mahana kuli yoze mafuliela", "Kuma mwaha yeswe yize mamwita;", "Yeswe mamu lakenya mamwaha yo!", "Yesu mafeta ufulielo."]}, {"type": "verse", "num": 3, "lines": ["Zambi hanalingi yiphuphu yinji,", "Kuli yoze mweswe mamufuliela;", "Yoze kechi kukhakhajana mamwaha", "Yesu mafeta ufulielo."]}, {"type": "verse", "num": 4, "lines": ["Tutayize yilakenyo ya Zambi,", "Kechi kasaula lie Jina Lienyi;", "Makahetesa yilakenyo Yenyi", "Yesu mafeta ufulielo."]}]}, {"numero": 293, "titulo": "SENU CHIPANGULA SOMA YA MASOMA", "blocos": [{"type": "verse", "num": 1, "lines": ["Kasongo mukwa uhenya,", "Yesu yiye mwe Mwene,", "Yali thachika yakumba", "Apwe mwe Chilamwina."]}, {"type": "chorus", "lines": ["Musenu che chipangula;", "Mwe Mwanangana ya masoma!", "Musenu cho yenu khule;", "Musenu Mwanangana!"]}, {"type": "verse", "num": 2, "lines": ["Tweyenu eswe tumuse,", "Chilamwina mahasa!", "Musenu ha unene Wenyi,", "Soma ya sambukila."]}, {"type": "verse", "num": 3, "lines": ["Ayundeya yalikala,", "Yatongola umwe weka!", "Angelo, akwa usandu,", "Kafunga shimbi Jenyi."]}, {"type": "verse", "num": 4, "lines": ["Tusakwilenu nyi thachi;", "Mumu Yesu hakumba,", "Hatambula wanangana,", "Yiye Soma ya pangu!"]}]}, {"numero": 294, "titulo": "ZANGO LIA YESU", "blocos": [{"type": "verse", "num": 1, "lines": ["Mutu kamoka zango lia Yesu,", "Zango liacho keshi kulitesa!", "Kristu nyi lamba watufwilile,", "Angulamwine ku-ufwe wami"]}, {"type": "chorus", "lines": ["Kristu Longeshi wejile,", "Wejilile yami mupi;", "Kristu, Longeshi wejile,", "Hanga angu lamwine."]}, {"type": "verse", "num": 2, "lines": ["Chichi kuhasa kukhakhajana,", "Ha zango liacho kulialitele!", "Wanehene ye sambukila,", "Kutusa mu-usoma wa pangu."]}, {"type": "verse", "num": 3, "lines": ["Kristu, longeshi Zambi ya Mwilu,", "Wangu kulile nyi keke Yenyi;", "Yangwazulwila jila ya Mwilu,", "Yangu pwisa Mwanenyi wa zango."]}, {"type": "verse", "num": 4, "lines": ["Ngulihane kuli Mwene Yesu,", "Hanga ngwambujole zango Lienyi;", "Wangu kulile ku-ufwe upi,", "Nguna zange Chilamwina chami."]}]}, {"numero": 295, "titulo": "TWAMA MULI YAMI", "blocos": [{"type": "verse", "num": 1, "lines": ["Utu wazango Lienyi", "Heza hatufupa", "Tumu sakwilenu", "Mungu lihana lume", "Tayiza Mwene wami", "Mukwa shili likwize", "Kokoloka wahilila", "Nyi chiseke chinji."]}, {"type": "verse", "num": 2, "lines": ["Ngwivwe Yesu wami", "Kwimba chino", "Hinalela nguli mupi", "Ku mbunge yami", "Nguhalise jina Lie", "Nyi kulifumanyisa,", "Tuku fumanyise", "Twama muli yami."]}, {"type": "verse", "num": 3, "lines": ["Nguwezele sambukila", "Cha zango lipema", "Hanga nguwayile,", "Mbunge yimuwika", "Ngulamwine anji", "Ngwende mu pangu", "Nyi kuzanga ana Je,", "Twama muli yami."]}, {"type": "verse", "num": 4, "lines": ["Chize chene nguli amwene", "Ngwize kuli yena", "Muchifuchi chipi", "Hanga napemene", "Muze mungu kumona", "Mungu mona huma lie", "Nyi zango nguku wayile", "Chilamwina chami."]}]}, {"numero": 296, "titulo": "KWIMBA CHA AKWA ULAMWINO", "blocos": [{"type": "verse", "num": 1, "lines": ["Miaso yipema tunevu,", "Muthethela cho kuwaha!", "Kwimba cha-akwa ulamwino", "Masa kwila kuli Yesu."]}, {"type": "chorus", "lines": ["Evwa miaso yakukumba,", "Mwe mujila ya uhenya,", "Mambujola ya ukule", "Yesu nyi zango Lienyi!", "Memba miaso ya ukule", "Yesu nyi zango Lienyi!"]}, {"type": "verse", "num": 2, "lines": ["Yiye Zambi watuzanga,", "Twatokele mu shili:", "Yatulamwina nyi unene", "Ku shingano lia miaka."]}, {"type": "verse", "num": 3, "lines": ["Zambi kumanu tayiza", "Yenwe yingulungulu!", "Chilamwina mwe mupema", "Kuli akwa shili eswe."]}, {"type": "verse", "num": 4, "lines": ["Tweyenu ku keke Yenyi!", "Kuyishi lie sulilo", "Ku mutambi wa Mwilu!", "Tambulenu ulamwino!"]}]}, {"numero": 297, "titulo": "HAKAMWIHI NYI ZUWO", "blocos": [{"type": "verse", "num": 1, "lines": ["Tangwa lize muli njila", "Chingoloshi hicheza,", "Zungo kha ufuku hiweza,", "Tangwa likwo hiliahwa,", "Hiliatoka nyi upi walio,", "Mba milima hiyeza;", "Chinapeme kwi-uluka,", "Haka mwihi nyi zuwo."]}, {"type": "chorus", "lines": ["Haka mwihi nyi zuwo,", "Haka mwihi nyi zuwo Mwilu;", "Ku zuwo lipema nyi mashima atoma", "Chifuchi cha mwe Zambi."]}, {"type": "verse", "num": 2, "lines": ["Ngeji muze muji muhwa", "Hakunjila cha tangwa,", "Mba hanga aye ahwime.", "Ku milimo ya lamba,", "Chenacho we mwono wacho,", "Mutuka upalika;", "Nyi kutala cha utome,", "Mutuhasa kutesa."]}, {"type": "verse", "num": 3, "lines": ["Tangwa likwo mu-ungeji", "Wakuya mu Malilu,", "Haka mwihi ali lwiji", "Mutoma ngwe katalilo;", "Lilu kulina chilweze", "Tuna mono lie pangu;", "Tangwa nyi tangwa hitwapwa", "Haka mwihi nyi Yesu."]}]}, {"numero": 298, "titulo": "NYI CHISEKE NENDA", "blocos": [{"type": "verse", "num": 1, "lines": ["Natokele mu milima,", "Yesu yangwanda mo,", "Nyi pangu lia zango Lienyi", "Milima hi yahwa."]}, {"type": "chorus", "lines": ["Nawahilila ngwendele mu pangu.", "Mumu Yesu mangu songwela.", "Muze angwanjile", "Kama mu ufwe,", "Nguli nyi chiseke,", "Hangu lamwina!"]}, {"type": "verse", "num": 2, "lines": ["Nyi hanji lilu mulila", "Nyi malelwa a mwilu,", "Yesu Yiye Chilamwina,", "Pangu kulia hiana!"]}, {"type": "verse", "num": 3, "lines": ["Nguli nyi pangu lia Zambi,", "Usendo upema!", "Ngununge lume nyi thachi,", "Nguhichike yeswe."]}, {"type": "verse", "num": 4, "lines": ["Nguka mone huma Lienyi", "Yesu, Chilamwina,", "Yoze wangu fwililile", "Yami muthu mupi."]}]}, {"numero": 299, "titulo": "CHIFUCHI CHA UHENYA", "blocos": [{"type": "verse", "num": 1, "lines": ["Limbo lia Mwilu lia uhenya", "Yelusaleme ya Zambi,", "Nguna zange mo chahiana,", "Nguka wanemo usoko!", "Waze twali zangile chinji", "Ana twaminyina mu fuka,", "Uhindukilo wa chiseke!"]}, {"type": "chorus", "lines": ["Tweya tuye hamuwika,", "Mu Yelusaleme yaha!", "Mumu ako sepa liami,", "Nguka kumone nawa."]}, {"type": "verse", "num": 2, "lines": ["Nguna zange ngukamone", "Akwetu mu malilu,", "Mumu Kristu Yiye hako,", "Yiye Hako lia eswe.", "Nguna zange kwivwa miaso,", "Mukemba yena mukwetu,", "Muze misongo muyihwa,", "Mutu-kembila ku Shiyono."]}, {"type": "verse", "num": 3, "lines": ["Tukendele hamuwika", "Mu matapalo ya olu,", "Chiseke chinji mutukevwa", "Chiseke cha uhenya wacho,", "Uwahililo wahiana.", "Uhenya wami unji", "Waku kathusa mukhondo", "Mu moko ja Mwe Yesu."]}]}, {"numero": 300, "titulo": "USWAMINO WA MWONO", "blocos": [{"type": "verse", "num": 1, "lines": ["Muze upi muwiza,", "Nawa linyika linji,", "Tujikijile Kristu,", "Kuthuchi kwivwa woma."]}, {"type": "chorus", "lines": ["Uswamino wa mwono,", "Uswamino wa kukumba", "Tujikijile Kristu,", "Kuthuchi kwivwa woma."]}, {"type": "verse", "num": 2, "lines": ["Muze yikola nyi lamba", "Muyi chikimisa mbunge,", "Che chipema ufulielo,", "Lihane kuli Yesu."]}, {"type": "verse", "num": 3, "lines": ["Nyi muze muji nguhwa,", "Nyi mangu hungumiona,", "Kulusu mulilema,", "Yesu ngwenyi fuliela."]}, {"type": "verse", "num": 4, "lines": ["Mu milima, mu pangu,", "Yesu haka mwihi ali,", "Ngwenyi hanga alamwine", "Yoze ma mufuliela."]}]}];
